window.NOTETY_CONTENT={"verses": [{"ref": "تث 31:6", "verse": "تَشَدَّدُوا وَتَشَجَّعُوا. لَا تَخَافُوا وَلَا تَرْهَبُوا وُجُوهَهُمْ، لأَنَّ الرَّبَّ إِلَهَكَ سَائِرٌ مَعَكَ. لَا يُهْمِلُكَ وَلَا يَتْرُكُكَ».", "message": "لما تقابل صعوبة، اطلب من ربنا شجاعة وثبات، وافتكر وعده بالمعونة وعدم الترك."}, {"ref": "في 4:5", "verse": "لِيَكُنْ حِلْمُكُمْ مَعْرُوفًا عِنْدَ جَمِيعِ النَّاسِ. اَلرَّبُّ قَرِيبٌ.", "message": "خلي وداعتك تظهر في معاملتك للناس، خصوصًا لما تتعرض لكلام يضايقك."}, {"ref": "في 4:6-7", "verse": "لَا تَهْتَمُّوا بِشَيْءٍ، بَلْ فِي كُلِّ شَيْءٍ بِالصَّلاَةِ وَالدُّعَاءِ مَعَ الشُّكْرِ، لِتُعْلَمْ طِلْبَاتُكُمْ لَدَى اللهِ. وَسَلاَمُ اللهِ الَّذِي يَفُوقُ كُلَّ عَقْلٍ، يَحْفَظُ قُلُوبَكُمْ وَأَفْكَارَكُمْ فِي الْمَسِيحِ يَسُوعَ.", "message": "خطّط لأمورك بهدوء، لكن متشيلش الهم لوحدك؛ صلّي واشكر ربنا، واطلب سلام السيد المسيح حتى وسط الضيقة."}, {"ref": "في 4:8", "verse": "أَخِيرًا أَيُّهَا الإِخْوَةُ كُلُّ مَا هُوَ حَقٌ، كُلُّ مَا هُوَ جَلِيلٌ، كُلُّ مَا هُوَ عَادِلٌ، كُلُّ مَا هُوَ طَاهِرٌ، كُلُّ مَا هُوَ مُسِرٌّ، كُلُّ مَا صِيتُهُ حَسَنٌ، إِنْ كَانَتْ فَضِيلَةٌ وَإِنْ كَانَ مَدْحٌ، فَفِي هَذِهِ افْتَكِرُوا.", "message": "اهتم بنقاوة أفكارك، واشغل قلبك بالحق والخير والفضائل، مش بمجرد تجنب الخطأ."}, {"ref": "في 4:9", "verse": "وَمَا تَعَلَّمْتُمُوهُ، وَتَسَلَّمْتُمُوهُ، وَسَمِعْتُمُوهُ، وَرَأَيْتُمُوهُ فِيَّ، فَهَذَا افْعَلُوا، وَإِلَهُ السَّلاَمِ يَكُونُ مَعَكُمْ.", "message": "متخليش المعرفة الروحية مجرد كلام؛ حول اللي اتعلمته لطريقة حياة وأعمال."}, {"ref": "في 4:13", "verse": "أَسْتَطِيعُ كُلَّ شَيْءٍ فِي الْمَسِيحِ الَّذِي يُقَوِّينِي.", "message": "اتعلّم تواجه ظروفك بالقوة اللي بيديها السيد المسيح، مش بالاعتماد على قدرتك وحدها."}, {"ref": "1تس 5:11", "verse": "لِذَلِكَ عَزُّوا بَعْضُكُمْ بَعْضًا وَابْنُوا أَحَدُكُمُ الآخَرَ، كَمَا تَفْعَلُونَ أَيْضًا.", "message": "شجّع حد محتاج كلمة سند؛ المحبة مش مجرد إحساس، لكنها مساندة تبني غيرك."}, {"ref": "1تس 5:16-18", "verse": "افْرَحُوا كُلَّ حِينٍ. صَلُّوا بِلاَ انْقِطَاعٍ. اشْكُرُوا فِي كُلِّ شَيْءٍ، لأَنَّ هَذِهِ هِيَ مَشِيئَةُ اللهِ فِي الْمَسِيحِ يَسُوعَ مِنْ جِهَتِكُمْ.", "message": "خلّي الصلاة والشكر جزء من يومك، واطلب من ربنا فرحًا ثابتًا مش مرتبطًا بتغيّر الظروف."}, {"ref": "1تس 5:21-22", "verse": "امْتَحِنُوا كُلَّ شَيْءٍ. تَمَسَّكُوا بِالْحَسَنِ. امْتَنِعُوا عَنْ كُلِّ شِبْهِ شَرٍّ.", "message": "مش كل فكرة أو اختيار ينفع تمشي وراه؛ ميّز الصالح وتمسّك بيه وابعد عن الشر."}, {"ref": "1تس 5:24", "verse": "أَمِينٌ هُوَ الَّذِي يَدْعُوكُمُ الَّذِي سَيَفْعَلُ أَيْضًا.", "message": "كمل سعيك الروحي برجاء؛ ربنا أمين في دعوته وعمله معاك."}, {"ref": "رو 12:18", "verse": "إِنْ كَانَ مُمْكِنًا فَحَسَبَ طَاقَتِكُمْ سَالِمُوا جَمِيعَ النَّاسِ.", "message": "اعمل اللي عليك علشان تعيش بسلام مع الكل، حتى لو الطرف التاني مش مستجيب."}, {"ref": "رو 12:21", "verse": "لَا يَغْلِبَنَّكَ الشَّرُّ بَلِ اغْلِبِ الشَّرَّ بِالْخَيْرِ.", "message": "متردش الإساءة بإساءة؛ اطلب نعمة من السيد المسيح تساعدك تقابل الشر بالصبر والإحسان."}, {"ref": "أم 16:3", "verse": "أَلْقِ عَلَى الرَّبِّ أَعْمَالَكَ فَتُثَبَّتَ أَفْكَارُكَ.", "message": "اعمل اللي عليك، وصلّي، وسلّم النتيجة لربنا؛ الاتكال عليه يديك هدوء بدل القلق."}, {"ref": "أم 16:9", "verse": "قَلْبُ الإِنْسَانِ يُفَكِّرُ فِي طَرِيقِهِ، وَالرَّبُّ يَهْدِي خَطْوَتَهُ.", "message": "خطّط واجتهد، لكن خلّي اختياراتك في طريق وصايا ربنا، واطلب إرشاده لخطواتك."}, {"ref": "أم 16:24", "verse": "اَلْكَلاَمُ الْحَسَنُ شَهْدُ عَسَلٍ، حُلْوٌ لِلنَّفْسِ وَشِفَاءٌ لِلْعِظَامِ.", "message": "اختار كلامك بمحبة وهدوء؛ كلمة طيبة ممكن تسند شخص وتفرّح قلبه."}, {"ref": "أم 16:32", "verse": "اَلْبَطِيءُ الْغَضَبِ خَيْرٌ مِنَ الْجَبَّارِ، وَمَالِكُ رُوحِهِ خَيْرٌ مِمَّنْ يَأْخُذُ مَدِينَةً.", "message": "انتصارك على غضبك وشهواتك أهم من انتصارك في خناقة؛ اطلب من ربنا قوة لضبط نفسك."}, {"ref": "يع 1:5", "verse": "وَإِنَّمَا إِنْ كَانَ أَحَدُكُمْ تُعْوِزُهُ حِكْمَةٌ، فَلْيَطْلُبْ مِنَ اللهِ الَّذِي يُعْطِي الْجَمِيعَ بِسَخَاءٍ وَلَا يُعَيِّرُ، فَسَيُعْطَى لَهُ.", "message": "لو محتار في قرار، صلّي واطلب من ربنا حكمة بدل ما تعتمد على رأيك وحده."}, {"ref": "يع 1:12", "verse": "طُوبَى لِلرَّجُلِ الَّذِي يَحْتَمِلُ التَّجْرِبَةَ، لأَنَّهُ إِذَا تَزَكَّى يَنَالُ «إِكْلِيلَ الْحَيَاةِ» الَّذِي وَعَدَ بِهِ الرَّبُّ لِلَّذِينَ يُحِبُّونَهُ.", "message": "وقت التجربة، اطلب من ربنا صبر وثبات؛ احتمالك بمحبة وإيمان له قيمة روحية."}, {"ref": "يع 1:19", "verse": "إِذًا يَا إِخْوَتِي الأَحِبَّاءَ، لِيَكُنْ كُلُّ إِنْسَانٍ مُسْرِعًا فِي الاسْتِمَاعِ، مُبْطِئًا فِي التَّكَلُّمِ، مُبْطِئًا فِي الْغَضَبِ،", "message": "قبل ما ترد في لحظة زعل، اسمع كويس واهدأ؛ ضبط اللسان والغضب فضيلة تتعلّمها."}, {"ref": "مت 5:7", "verse": "طُوبَى لِلرُّحَمَاءِ، لأَنَّهُمْ يُرْحَمُونَ.", "message": "ارحم اللي حواليك في كلامك وتصرفاتك؛ الرحمة من الفضائل اللي السيد المسيح طوّب أصحابها."}, {"ref": "مز 23:1", "verse": "الرَّبُّ رَاعِيَّ فَلاَ يُعْوِزُنِي شَيْءٌ", "message": "السيد المسيح راعيك الصالح؛ خليك قريب منه، واطلب منه يقود خطواتك بدل ما تعتمد على نفسك بس."}, {"ref": "مز 27:1", "verse": "اَلرَّبُّ نُورِي وَخَلاَصِي، مِمَّنْ أَخَافُ؟ الرَّبُّ حِصْنُ حَيَاتِي، مِمَّنْ أَرْتَعِبُ؟", "message": "لما الخوف يدخل قلبك، افتكر إن ربنا هو النور والخلاص؛ صلّي واطلب منه شجاعة وثبات."}, {"ref": "مز 27:14", "verse": "انْتَظِرِ الرَّبَّ. لِيَتَشَدَّدْ وَلْيَتَشَجَّعْ قَلْبُكَ، وَانْتَظِرِ الرَّبَّ", "message": "لو الاستجابة اتأخرت، متفقدش رجاءك؛ انتظر ربنا واطلب منه قلب ثابت وشجاع."}, {"ref": "مز 40:17", "verse": "الرَّبُّ يَهْتَمُّ بِي. عَوْنِي وَمُنْقِذِي أَنْتَ. يَا إِلهِي لاَ تُبْطِئْ", "message": "لما تحس إنك ضعيف أو محتاج معونة، قول لربنا احتياجك بصدق واتكل عليه."}, {"ref": "مز 118:6", "verse": "الرَّبُّ لِي فَلاَ أَخَافُ. مَاذَا يَصْنَعُ بِي الإِنْسَانُ؟", "message": "متخليش خوفك من رأي الناس يحكم قراراتك؛ خلّي ثقتك في ربنا أقوى."}, {"ref": "مز 56:11", "verse": "عَلَى اللهِ تَوَكَّلْتُ فَلاَ أَخَافُ. مَاذَا يَصْنَعُهُ بِي الإِنْسَانُ؟", "message": "وسط الضغوط، اختار الاتكال على ربنا بدل الاستسلام للخوف من الناس."}, {"ref": "مز 118:8", "verse": "الاحْتِمَاءُ بِالرَّبِّ خَيْرٌ مِنَ التَّوَكُّلِ عَلَى إِنْسَانٍ", "message": "وجود ناس تسندك نعمة، لكن خلي اتكالك الأول على ربنا مش على البشر."}, {"ref": "مز 121:7-8", "verse": "الرَّبُّ يَحْفَظُكَ مِنْ كُلِّ سُوءٍ. يَحْفَظُ نَفْسَكَ. الرَّبُّ يَحْفَظُ خُرُوجَكَ وَدُخُولَكَ مِنَ الآنَ وَإِلَى الدَّهْرِ", "message": "ابدأ مشاويرك بالصلاة، واطلب من ربنا يحفظ نفسك ويقود دخولك وخروجك."}, {"ref": "يو 10:11", "verse": "أَنَا هُوَ الرَّاعِي الصَّالِحُ، وَالرَّاعِي الصَّالِحُ يَبْذِلُ نَفْسَهُ عَنِ الْخِرَافِ", "message": "السيد المسيح هو الراعي الصالح اللي بذل نفسه عن خرافه؛ اتعلّم من محبته الباذلة."}, {"ref": "يو 10:14", "verse": "أَمَّا أَنَا فَإِنِّي الرَّاعِي الصَّالِحُ، وَأَعْرِفُ خَاصَّتِي وَخَاصَّتِي تَعْرِفُنِي", "message": "السيد المسيح يعرف خاصته؛ عيش علاقتك بيه في صلاة وطاعة، مش مجرد معلومات عنه."}, {"ref": "يو 11:25", "verse": "أَنَا هُوَ الْقِيَامَةُ وَالْحَيَاةُ. مَنْ آمَنَ بِي وَلَوْ مَاتَ فَسَيَحْيَا", "message": "في مواجهة الحزن والموت، تمسك بالرجاء في السيد المسيح، القيامة والحياة."}, {"ref": "مز 116:7", "verse": "ارْجِعِي يَا نَفْسِي إِلَى رَاحَتِكِ، لأَنَّ الرَّبَّ قَدْ أَحْسَنَ إِلَيْكِ", "message": "افتكر إحسانات ربنا القديمة، وارجع له بالشكر بدل ما تسيب الهم يملأ قلبك."}, {"ref": "مز 103:2", "verse": "بَارِكِي يَا نَفْسِي الرَّبَّ، وَلاَ تَنْسَيْ كُلَّ حَسَنَاتِهِ", "message": "متعدّيش على نعم ربنا كأنها أمر عادي؛ افتكرها كل يوم واشكره عليها."}, {"ref": "مت 11:28", "verse": "تَعَالَوْا إِلَيَّ يَا جَمِيعَ الْمُتْعَبِينَ وَالثَّقِيلِي الأَحْمَالِ، وَأَنَا أُرِيحُكُمْ", "message": "لما تحملك الهموم، متتهربش من الصلاة؛ تعالى للسيد المسيح واطلب راحته."}, {"ref": "يو 14:27", "verse": "سَلاَمًا أَتْرُكُ لَكُمْ. سَلاَمِي أُعْطِيكُمْ. لَيْسَ كَمَا يُعْطِي الْعَالَمُ أُعْطِيكُمْ أَنَا. لاَ تَضْطَرِبْ قُلُوبُكُمْ وَلاَ تَرْهَبْ", "message": "سلام السيد المسيح مش مجرد غياب المشاكل؛ اطلب سلامه لقلبك وسط الظروف."}, {"ref": "مز 126:3", "verse": "عَظَّمَ الرَّبُّ الْعَمَلَ مَعَنَا، وَصِرْنَا فَرِحِينَ", "message": "افتكر عمل ربنا معاك واشكره؛ الشكر يفتح عينيك على إحساناته بدل التركيز على الناقص."}, {"ref": "إش 41:10", "verse": "لاَ تَخَفْ لأَنِّي مَعَكَ. لاَ تَتَلَفَّتْ لأَنِّي إِلهُكَ. قَدْ أَيَّدْتُكَ وَأَعَنْتُكَ وَعَضَدْتُكَ بِيَمِينِ بِرِّي", "message": "حتى لو ضعيف أو خايف، اطلب من ربنا معونته وثق إنه لا يتركك."}, {"ref": "1بط 5:7", "verse": "مُلْقِينَ كُلَّ هَمِّكُمْ عَلَيْهِ، لأَنَّهُ هُوَ يَعْتَنِي بِكُمْ", "message": "بدل ما تفضل شايل الهم لوحدك، احكيه لربنا في الصلاة واتكل على عنايته."}, {"ref": "مرا 3:25", "verse": "طَيِّبٌ هُوَ الرَّبُّ لِلَّذِينَ يَتَرَجَّوْنَهُ، لِلنَّفْسِ الَّتِي تَطْلُبُهُ", "message": "في أوقات الانتظار، خليك ثابت في طلب ربنا، ومتستعجلش تفقد الرجاء."}, {"ref": "مز 34:15", "verse": "عَيْنَا الرَّبِّ نَحْوَ الصِّدِّيقِينَ، وَأُذُنَاهُ إِلَى صُرَاخِهِمْ", "message": "ربنا يسمع صراخ أولاده؛ صلّي بقلب صادق حتى لو مش لاقي كلام كتير."}, {"ref": "نح 2:20", "verse": "إِنَّ إِلهَ السَّمَاءِ يُعْطِينَا النَّجَاحَ، وَنَحْنُ عَبِيدُهُ نَقُومُ وَنَبْنِي", "message": "لما تبدأ خدمة أو مسؤولية، اجتهد واعمل اللي عليك، واتكل على معونة ربنا."}, {"ref": "خر 20:12", "verse": "أَكْرِمْ أَبَاكَ وَأُمَّكَ لِكَيْ تَطُولَ أَيَّامُكَ عَلَى الأَرْضِ الَّتِي يُعْطِيكَ الرَّبُّ إِلهُكَ", "message": "بر والديك يظهر في احترامك وكلامك وطاعتك فيما يرضي ربنا؛ خلي المحبة فعل."}, {"ref": "مز 92:12", "verse": "اَلصِّدِّيقُ كَالنَّخْلَةِ يَزْهُو، كَالأَرْزِ فِي لُبْنَانَ يَنْمُو", "message": "النمو الروحي محتاج ثبات وجذور عميقة؛ استمر في الصلاة والوصية حتى لو التغيير بطيء."}, {"ref": "أم 11:30", "verse": "ثَمَرُ الصِّدِّيقِ شَجَرَةُ حَيَاةٍ، وَرَابحُ النُّفُوسِ حَكِيمٌ", "message": "خلي حياتك تحمل ثمر خير للناس؛ كلمة تشجيع أو خدمة بسيطة ممكن تسند نفس."}, {"ref": "مز 16:8", "verse": "جَعَلْتُ الرَّبَّ أَمَامِي فِي كُلِّ حِينٍ، لأَنَّهُ عَنْ يَمِينِي فَلاَ أَتَزَعْزَعُ", "message": "حاول تخلي حضور ربنا قدام عينيك في قراراتك، وارجع له قبل كل خطوة."}, {"ref": "أع 5:29", "verse": "يَنْبَغِي أَنْ يُطَاعَ اللهُ أَكْثَرَ مِنَ النَّاسِ", "message": "لو ضغط الناس عليك يخالف وصية ربنا، تمسّك بالطاعة لربنا بمحبة وشجاعة."}, {"ref": "أف 6:1", "verse": "أَيُّهَا الأَوْلاَدُ، أَطِيعُوا وَالِدِيكُمْ فِي الرَّبِّ لأَنَّ هذَا حَقٌّ", "message": "طاعتك لوالديك واحترامك ليهم جزء من حياتك مع ربنا؛ عبّر عنها عمليًا."}, {"ref": "مت 5:5", "verse": "طُوبَى لِلْوُدَعَاءِ، لأَنَّهُمْ يَرِثُونَ الأَرْضَ", "message": "الوداعة مش ضعف؛ اتعلم من السيد المسيح ترد بهدوء بدل العصبية."}, {"ref": "مز 37:11", "verse": "أَمَّا الْوُدَعَاءُ فَيَرِثُونَ الأَرْضَ، وَيَتَلَذَّذُونَ فِي كَثْرَةِ السَّلاَمَةِ", "message": "الهدوء والوداعة مش خسارة؛ اطلب من ربنا قلبًا يعرف يعيش بسلام مع الناس."}, {"ref": "أم 12:27", "verse": "الرَّخَاوَةُ لاَ تَمْسِكُ صَيْدًا، أَمَّا ثَرْوَةُ الإِنْسَانِ الْكَرِيمَةُ فَهِيَ الاجْتِهَادُ", "message": "متأجلش مسؤولياتك؛ الاجتهاد والأمانة في الشغل والدراسة جزء من شهادتك المسيحية."}, {"ref": "1تي 6:6", "verse": "أَمَّا التَّقْوَى مَعَ الْقَنَاعَةِ فَهِيَ تِجَارَةٌ عَظِيمَةٌ", "message": "متقيسش قيمتك بكثرة اللي عندك؛ اطلب التقوى والقناعة واشكر ربنا على عطاياه."}, {"ref": "رو 4:7", "verse": "طُوبَى لِلَّذِينَ غُفِرَتْ آثَامُهُمْ وَسُتِرَتْ خَطَايَاهُمْ", "message": "رحمة ربنا وغفرانه يدعوك للتوبة مش لليأس؛ ارجع له بقلب صادق."}, {"ref": "أع 20:35", "verse": "مَغْبُوطٌ هُوَ الْعَطَاءُ أَكْثَرُ مِنَ الأَخْذِ", "message": "جرّب تفرّح حد بالعطاء من غير ما تستنى مقابل؛ المحبة بتظهر في البذل."}, {"ref": "أم 15:33", "verse": "مَخَافَةُ الرَّبِّ أَدَبُ حِكْمَةٍ، وَقَبْلَ الْكَرَامَةِ التَّوَاضُعُ", "message": "لو بتطلب الحكمة، ابدأ بالتواضع وقبول التصحيح، مش بالتعالي على النصيحة."}, {"ref": "1بط 5:6", "verse": "فَتَوَاضَعُوا تَحْتَ يَدِ اللهِ الْقَوِيَّةِ لِكَيْ يَرْفَعَكُمْ فِي حِينِهِ", "message": "متستعجلش تدافع عن نفسك بكل طريقة؛ اتضع قدام ربنا واترك له كرامتك."}, {"ref": "1تي 4:12", "verse": "كُنْ قُدْوَةً لِلْمُؤْمِنِينَ فِي الْكَلاَمِ، فِي التَّصَرُّفِ، فِي الْمَحَبَّةِ، فِي الرُّوحِ، فِي الإِيمَانِ، فِي الطَّهَارَةِ", "message": "سنّك مش عائق إنك تكون قدوة؛ خلي كلامك وتصرفاتك ومحبتك يشهدوا للسيد المسيح."}, {"ref": "في 4:4", "verse": "اِفْرَحُوا فِي الرَّبِّ كُلَّ حِينٍ، وَأَقُولُ أَيْضًا: افْرَحُوا", "message": "الفرح في ربنا مش مرتبط بيوم مثالي؛ خصص وقت للصلاة والشكر حتى وسط التعب."}, {"ref": "رو 12:15", "verse": "فَرَحًا مَعَ الْفَرِحِينَ وَبُكَاءً مَعَ الْبَاكِينَ", "message": "المحبة مشاركة حقيقية؛ افرح لنجاح غيرك واسند اللي قلبه مكسور."}, {"ref": "رو 12:12", "verse": "فَرِحِينَ فِي الرَّجَاءِ، صَابِرِينَ فِي الضَّيْقِ، مُواظِبِينَ عَلَى الصَّلاَةِ", "message": "لما تضيق عليك الأيام، تمسّك بالرجاء والصبر، وخلي الصلاة عادة ثابتة."}, {"ref": "نح 8:10", "verse": "لاَ تَحْزَنُوا، لأَنَّ فَرَحَ الرَّبِّ هُوَ قُوَّتُكُمْ.", "message": "وسط الحزن، افتكر مصدر قوتك في ربنا، واطلب منه رجاء يعينك تكمل."}, {"ref": "أم 4:7", "verse": "الْحِكْمَةُ هِيَ الرَّأْسُ. فَاقْتَنِ الْحِكْمَةَ، وَبِكُلِّ مُقْتَنَاكَ اقْتَنِ الْفَهْمَ", "message": "اختار الحكمة قبل المكسب السريع؛ اسأل عن الصح واتعلم قبل ما تاخد قرار."}, {"ref": "يو 7:24", "verse": "لاَ تَحْكُمُوا حَسَبَ الظَّاهِرِ بَلِ احْكُمُوا حُكْمًا عَادِلًا", "message": "متسرعش في الحكم على حد من مظهره؛ اسمع كويس واطلب من ربنا عدل في نظرتك."}, {"ref": "أم 17:28", "verse": "الأَحْمَقُ إِذَا سَكَتَ يُحْسَبُ حَكِيمًا، وَمَنْ ضَمَّ شَفَتَيْهِ فَهِيمًا", "message": "مش لازم ترد على كل كلمة؛ أحيانًا صمتك وضبط لسانك يكونوا أحكم من الجدال."}, {"ref": "1كو 13:8", "verse": "اَلْمَحَبَّةُ لاَ تَسْقُطُ أَبَدًا", "message": "متستهونش بالمحبة؛ خليها ثابتة في أفعالك حتى لما الظروف تتغير."}, {"ref": "1كو 13:4", "verse": "الْمَحَبَّةُ تَتَأَنَّى وَتَرْفُقُ. الْمَحَبَّةُ لاَ تَحْسِدُ. الْمَحَبَّةُ لاَ تَتَفَاخَرُ، وَلاَ تَنْتَفِخُ", "message": "لو عايز تنمو في المحبة، اتدرب على الصبر والرفق وابتعد عن الحسد والتفاخر."}, {"ref": "يو 13:34", "verse": "وَصِيَّةً جَدِيدَةً أَنَا أُعْطِيكُمْ: أَنْ تُحِبُّوا بَعْضُكُمْ بَعْضًا. كَمَا أَحْبَبْتُكُمْ أَنَا تُحِبُّونَ أَنْتُمْ أَيْضًا بَعْضُكُمْ بَعْضًا", "message": "السيد المسيح وصّانا نحب بعض كما أحبنا؛ اسأل نفسك محبتك ظهرت لمين النهارده؟"}, {"ref": "1كو 16:14", "verse": "لِتَصِرْ كُلُّ أُمُورِكُمْ فِي مَحَبَّةٍ", "message": "خلي المحبة توجه كلامك وقراراتك، حتى في أبسط التفاصيل اليومية."}, {"ref": "رو 12:10", "verse": "وَادِّينَ بَعْضُكُمْ بَعْضًا بِالْمَحَبَّةِ الأَخَوِيَّةِ، مُقَدِّمِينَ بَعْضُكُمْ بَعْضًا فِي الْكَرَامَةِ", "message": "احترامك لغيرك مش بيقلل منك؛ بادر بالتقدير وقدم غيرك في الكرامة."}, {"ref": "مت 5:9", "verse": "طُوبَى لِصَانِعِي السَّلاَمِ، لأَنَّهُمْ أَبْنَاءَ اللهِ يُدْعَوْنَ", "message": "بدل ما تزود الخلاف، خد خطوة صلح؛ السيد المسيح طوّب صانعي السلام."}, {"ref": "2كو 13:11", "verse": "عِيشُوا بِالسَّلاَمِ، وَإِلهُ الْمَحَبَّةِ وَالسَّلاَمِ سَيَكُونُ مَعَكُمْ", "message": "خلي بيتك وعلاقاتك مكان للمصالحة مش الخصام؛ اطلب من ربنا روح السلام."}, {"ref": "مز 34:14", "verse": "حِدْ عَنِ الشَّرِّ، وَاصْنَعِ الْخَيْرَ. اطْلُبِ السَّلاَمَةَ، وَاسْعَ وَرَاءَهَا", "message": "السلام محتاج سعي، مش مجرد أمنية؛ ابعد عن الشر وخد خطوات عملية للخير."}, {"ref": "لو 21:19", "verse": "بِصَبْرِكُمُ اقْتَنُوا أَنْفُسَكُمْ", "message": "لو التجربة طولت، اطلب من ربنا صبرًا يحفظ قلبك من التذمر واليأس."}, {"ref": "غل 5:22-23", "verse": "أَمَّا ثَمَرُ الرُّوحِ فَهُوَ: مَحَبَّةٌ، فَرَحٌ، سَلاَمٌ، طُولُ أَنَاةٍ، لُطْفٌ، صَلاَحٌ، إِيمَانٌ، وَدَاعَةٌ، تَعَفُّفٌ", "message": "اختبر نموك الروحي بثمر الروح: محبة ووداعة وتعفف وصبر، مش بالمظاهر بس."}, {"ref": "لو 16:10", "verse": "اَلأَمِينُ فِي الْقَلِيلِ أَمِينٌ أَيْضًا فِي الْكَثِيرِ، وَالظَّالِمُ فِي الْقَلِيلِ ظَالِمٌ أَيْضًا فِي الْكَثِيرِ", "message": "الأمانة بتبدأ من التفاصيل الصغيرة؛ متستصغرش واجبك حتى لو محدش شايفه."}, {"ref": "مز 34:13", "verse": "صُنْ لِسَانَكَ عَنِ الشَّرِّ، وَشَفَتَيْكَ عَنِ التَّكَلُّمِ بِالْغِشِّ", "message": "قبل ما تقول كلمة جارحة أو تنقل كلام عن حد، اطلب من ربنا يحفظ لسانك."}, {"ref": "أم 1:7", "verse": "مَخَافَةُ الرَّبِّ رَأْسُ الْمَعْرِفَةِ، أَمَّا الْجَاهِلُونَ فَيَحْتَقِرُونَ الْحِكْمَةَ وَالأَدَبَ", "message": "العلم مهم، لكن الحكمة الحقيقية تبدأ باحترام وصايا ربنا وقبول التأديب."}, {"ref": "أم 23:23", "verse": "اِقْتَنِ الْحَقَّ وَلاَ تَبِعْهُ، وَالْحِكْمَةَ وَالأَدَبَ وَالْفَهْمَ", "message": "متساومش على الحق علشان مصلحة سريعة؛ اختار الصدق حتى لو الطريق أصعب."}, {"ref": "أم 24:17", "verse": "لاَ تَفْرَحْ بِسُقُوطِ عَدُوِّكَ، وَلاَ يَبْتَهِجْ قَلْبُكَ إِذَا عَثَرَ", "message": "حتى لو حد أساء لك، متفرحش لو وقع؛ اطلب من ربنا يطهّر قلبك من الشماتة."}, {"ref": "لو 6:37", "verse": "لاَ تَدِينُوا فَلاَ تُدَانُوا. لاَ تَقْضُوا عَلَى أَحَدٍ فَلاَ يُقْضَى عَلَيْكُمْ", "message": "لما تسمع عن خطأ غيرك، متتسرعش في إدانته؛ راجع نفسك واطلب رحمة ربنا."}, {"ref": "مز 119:37", "verse": "حَوِّلْ عَيْنَيَّ عَنِ النَّظَرِ إِلَى الْبَاطِلِ. فِي طَرِيقِكَ أَحْيِنِي", "message": "مش كل حاجة قدام عينيك مفيدة لقلبك؛ اختار اللي يدخل فكرك بوعي ونقاوة."}, {"ref": "أم 6:6", "verse": "اِذْهَبْ إِلَى النَّمْلَةِ أَيُّهَا الْكَسْلاَنُ. تَأَمَّلْ طُرُقَهَا وَكُنْ حَكِيمًا", "message": "الاجتهاد مش بيبدأ بالحماس الكبير؛ ابدأ بواجب صغير وكمّله بأمانة."}, {"ref": "أم 10:19", "verse": "كَثْرَةُ الْكَلاَمِ لاَ تَخْلُو مِنْ مَعْصِيَةٍ، أَمَّا الضَّابِطُ شَفَتَيْهِ فَعَاقِلٌ", "message": "لو الحوار سخن، اختار كلمات أقل وأهدأ؛ ضبط اللسان يحميك من أخطاء كتير."}, {"ref": "1بط 3:9", "verse": "غَيْرَ مُجَازِينَ عَنْ شَرّ بِشَرّ أَوْ عَنْ شَتِيمَةٍ بِشَتِيمَةٍ، بَلْ بِالْعَكْسِ مُبَارِكِينَ، عَالِمِينَ أَنَّكُمْ لِهذَا دُعِيتُمْ لِكَيْ تَرِثُوا بَرَكَةً", "message": "لما تسمع إساءة، متردش بإساءة؛ اطلب من السيد المسيح تعينك تبارك بدل الانتقام."}, {"ref": "1كو 4:12", "verse": "نُشْتَمُ فَنُبَارِكُ. نُضْطَهَدُ فَنَحْتَمِلُ", "message": "مش كل إهانة لازم تقابلها برد قاسي؛ اتعلم من احتمال الرسل ومباركتهم."}, {"ref": "أم 16:18", "verse": "قَبْلَ الْكَسْرِ الْكِبْرِيَاءُ، وَقَبْلَ السُّقُوطِ تَشَامُخُ الرُّوحِ", "message": "لو النجاح خلاك تتكبر، راجع قلبك؛ التواضع يحفظك من سقوط الكبرياء."}, {"ref": "أم 3:7", "verse": "لاَ تَكُنْ حَكِيمًا فِي عَيْنَيْ نَفْسِكَ", "message": "اسمع نصيحة غيرك قبل ما تثق في رأيك وحده؛ التواضع بداية الحكمة."}, {"ref": "أم 29:23", "verse": "كِبْرِيَاءُ الإِنْسَانِ تَضَعُهُ، وَالْوَضِيعُ الرُّوحِ يَنَالُ مَجْدًا", "message": "متقيسش كرامتك بالتعالي؛ القلب المتضع هو اللي يطلب رضا ربنا."}, {"ref": "أم 15:1", "verse": "الْجَوَابُ اللَّيِّنُ يَصْرِفُ الْغَضَبَ، وَالْكَلاَمُ الْمُوجعُ يُهَيِّجُ السَّخَطَ", "message": "وقت الغضب، ردّ بهدوء بدل ما تزود النار؛ كلمة لينة تقدر تهدي الموقف."}, {"ref": "مت 14:27", "verse": "تَشَجَّعُوا! أَنَا هُوَ. لاَ تَخَافُوا", "message": "لما الخوف يزيد، افتكر كلام السيد المسيح لتلاميذه: تشجعوا ولا تخافوا."}, {"ref": "مز 37:27", "verse": "حِدْ عَنِ الشَّرِّ وَافْعَلِ الْخَيْرَ", "message": "الابتعاد عن الشر خطوة، لكن الفضيلة تحتاج كمان إنك تعمل الخير."}, {"ref": "1تس 5:14", "verse": "شَجِّعُوا صِغَارَ النُّفُوسِ. أَسْنِدُوا الضُّعَفَاءَ. تَأَنَّوْا عَلَى الْجَمِيعِ", "message": "شوف مين محتاج سند النهارده؛ شجّع الضعيف واتأنَّ على الجميع."}, {"ref": "أم 24:16", "verse": "الصِّدِّيقَ يَسْقُطُ سَبْعَ مَرَّاتٍ وَيَقُومُ، أَمَّا الأَشْرَارُ فَيَعْثُرُونَ بِالشَّرِّ", "message": "لو وقعت، متستسلمش لليأس؛ قوم بالتوبة وابدأ من جديد مع ربنا."}, {"ref": "مز 141:3", "verse": "ضَع يَا رَبُّ حَافِظًا لِفَمِي. وَبَابًا حَصِينًا لِشَفَتَيَّ", "message": "لما تتضايق، اطلب من ربنا يحفظ فمك قبل ما تجرح حد بكلامك."}, {"ref": "مت 5:8", "verse": "طُوبَى لِلأَنْقِيَاءِ الْقَلْبِ، لأَنَّهُمْ يُعَايِنُونَ اللهَ", "message": "نقاوة القلب مش مجرد مظهر؛ اطلب من ربنا يطهّر دوافعك وأفكارك."}, {"ref": "مت 5:6", "verse": "طُوبَى لِلْجِيَاعِ وَالْعِطَاشِ إِلَى الْبِرِّ، لأَنَّهُمْ يُشْبَعُونَ", "message": "خلي اشتياقك للبر أقوى من رغبتك في إرضاء الناس؛ اطلب النمو في الوصية."}, {"ref": "مز 143:8", "verse": "عَرِّفْنِي الطَّرِيقَ الَّتِي أَسْلُكُ فِيهَا، لأَنِّي إِلَيْكَ رَفَعْتُ نَفْسِي", "message": "قبل قرار محير، صلّي: يا رب عرفني الطريق اللي أسلك فيه، واطلب إرشاده."}, {"ref": "مز 143:10", "verse": "عَلِّمْنِي أَنْ أَعْمَلَ رِضَاكَ، لأَنَّكَ أَنْتَ إِلهِي", "message": "خلي هدف يومك مش مجرد إنجازات؛ اسأل ربنا يساعدك تعمل رضاه."}, {"ref": "أم 14:15", "verse": "الْغَبِيُّ يُصَدِّقُ كُلَّ كَلِمَةٍ، وَالذَّكِيُّ يَنْتَبِهُ إِلَى خَطَوَاتِهِ", "message": "متصدقش كل كلام تسمعه؛ اختبر الأمور بحكمة قبل ما تحكم أو تنقل خبر."}, {"ref": "يو 16:33", "verse": "فِي الْعَالَمِ سَيَكُونُ لَكُمْ ضِيقٌ، وَلكِنْ ثِقُوا: أَنَا قَدْ غَلَبْتُ الْعَالَمَ", "message": "السيد المسيح ما وعدناش إن الدنيا بلا ضيق؛ لكن دعانا نثق في غلبته."}, {"ref": "مز 122:1", "verse": "فَرِحْتُ بِالْقَائِلِينَ لِي: إِلَى بَيْتِ الرَّبِّ نَذْهَبُ", "message": "خلي حضور الكنيسة مصدر فرح، مش مجرد عادة؛ شارك بقلب حاضر في الصلاة."}, {"ref": "مز 118:9", "verse": "الاحْتِمَاءُ بِالرَّبِّ خَيْرٌ مِنَ التَّوَكُّلِ عَلَى الرُّؤَسَاءِ", "message": "لما تتضغط من ناس أصحاب سلطة، افتكر إن اتكالك الأول يكون على ربنا، مش على مكانة أي إنسان."}, {"ref": "حز 34:15-16", "verse": "أَنَا أَرْعَى غَنَمِي وَأُرْبِضُهَا، يَقُولُ السَّيِّدُ الرَّبُّ. وَأَطْلُبُ الضَّالَّ، وَأَسْتَرِدُّ الْمَطْرُودَ، وَأَجْبِرُ الْكَسِيرَ، وَأَعْصِبُ الْجَرِيحَ", "message": "السيد المسيح ما بينساش اللي تاه أو اتجرح. ارجع له بثقة، وخلي قلبك رحيم بالضعيف والمكسور."}, {"ref": "يع 1:17", "verse": "كُلُّ عَطِيَّةٍ صَالِحَةٍ وَكُلُّ مَوْهِبَةٍ تَامَّةٍ هِيَ مِنْ فَوْقُ، نَازِلَةٌ مِنْ عِنْدِ أَبِي الأَنْوَارِ، الَّذِي لَيْسَ عِنْدَهُ تَغْيِيرٌ وَلاَ ظِلُّ دَوَرَانٍ", "message": "لما تفتكر حاجة حلوة في حياتك، اشكر ربنا عليها، ومتتعاملش مع عطاياه كأنها أمر مضمون."}, {"ref": "أم 10:22", "verse": "بَرَكَةُ الرَّبِّ هِيَ تُغْنِي، وَلاَ يَزِيدُ مَعَهَا تَعَبًا", "message": "متقيسش بركة ربنا بالمكسب المادي وحده؛ اطلب حياة فيها قناعة ورضا وضمير مستريح."}, {"ref": "نش 2:16", "verse": "حَبِيبِي لِي وَأَنَا لَهُ. الرَّاعِي بَيْنَ السَّوْسَنِ", "message": "خلي علاقتك بالسيد المسيح علاقة محبة وقرب حقيقي، مش مجرد كلمات بترددها."}, {"ref": "مز 46:7", "verse": "رَبُّ الْجُنُودِ مَعَنَا. مَلْجَأُنَا إِلهُ يَعْقُوبَ", "message": "وقت الخوف، ارجع لربنا في الصلاة؛ وجوده هو الملجأ اللي تعتمد عليه."}, {"ref": "مز 29:11", "verse": "الرَّبُّ يُعْطِي عِزًّا لِشَعْبِهِ. الرَّبُّ يُبَارِكُ شَعْبَهُ بِالسَّلاَمِ", "message": "اطلب من ربنا قوة وسلام، وحاول تكون أنت كمان سبب سلام للي حواليك."}, {"ref": "مز 61:3", "verse": "كُنْتَ مَلْجَأً لِي، بُرْجَ قُوَّةٍ مِنْ وَجْهِ الْعَدُوِّ", "message": "لما تحس إنك محاصر، متنساش إنك تقدر تلجأ لربنا وتفتح له قلبك."}, {"ref": "مز 90:1", "verse": "يَا رَبُّ، مَلْجَأً كُنْتَ لَنَا فِي دَوْرٍ فَدَوْرٍ", "message": "ربنا كان ملجأ لشعبه عبر الأجيال. افتكر أمانته لما تواجه يوم صعب."}, {"ref": "يش 1:5", "verse": "لاَ أُهْمِلُكَ وَلاَ أَتْرُكُكَ", "message": "لما تبقى قدام مسؤولية تقيلة، خليك ثابت واسند خطواتك على وعد ربنا بمعونته."}, {"ref": "تك 26:24", "verse": "لاَ تَخَفْ لأَنِّي مَعَكَ، وَأُبَارِكُكَ", "message": "بدل ما الخوف يوقفك، افتكر إن حضور ربنا معاك يدعوك للطاعة والثقة."}, {"ref": "إر 1:8", "verse": "لاَ تَخَفْ مِنْ وُجُوهِهِمْ، لأَنِّي أَنَا مَعَكَ لأُنْقِذَكَ، يَقُولُ الرَّبُّ", "message": "لو خايف من مواجهة أو رأي ناس، اطلب من ربنا شجاعة تعمل بيها الصح."}, {"ref": "إر 42:11", "verse": "لاَ تَخَافُوا مَلِكَ بَابِلَ الَّذِي أَنْتُمْ خَائِفُوهُ. لاَ تَخَافُوهُ، يَقُولُ الرَّبُّ، لأَنِّي أَنَا مَعَكُمْ لأُخَلِّصَكُمْ وَأُنْقِذَكُمْ مِنْ يَدِهِ", "message": "مهما كان مصدر خوفك، خليك فاكر إن المعونة والخلاص في إيد ربنا، مش في الظروف."}, {"ref": "تك 28:15", "verse": "هَا أَنَا مَعَكَ، وَأَحْفَظُكَ حَيْثُمَا تَذْهَبُ، وَأَرُدُّكَ إِلَى هذِهِ الأَرْضِ، لأَنِّي لاَ أَتْرُكُكَ حَتَّى أَفْعَلَ مَا كَلَّمْتُكَ بِهِ", "message": "في طريقك الجديد، خليك أمين في خطواتك وواثق إن ربنا قادر يقودك."}, {"ref": "إر 1:18", "verse": "فَيُحَارِبُونَكَ وَلاَ يَقْدِرُونَ عَلَيْكَ، لأَنِّي أَنَا مَعَكَ، يَقُولُ الرَّبُّ، لأُنْقِذَكَ", "message": "الثبات مش إن الصعوبات تختفي؛ الثبات إنك تكمّل دعوتك متكلًا على ربنا."}, {"ref": "مز 86:17", "verse": "اصْنَعْ مَعِي آيَةً صَالِحَةٌ، فَيَرَى ذلِكَ مُبْغِضِيَّ فَيَخْزَوْا، لأَنَّكَ أَنْتَ يَا رَبُّ أَعَنْتَنِي وَعَزَّيْتَنِي", "message": "لما تتعرض لرفض أو إساءة، اطلب معونة ربنا وتعزيته بدل ما ترد بنفس الروح."}, {"ref": "إش 43:4", "verse": "صِرْتَ عَزِيزًا فِي عَيْنَيَّ مُكَرَّمًا، وَأَنَا قَدْ أَحْبَبْتُكَ", "message": "قيمتك مش بتتحدد برأي الناس فيك؛ افتكر محبة ربنا، وخلي حياتك استجابة للمحبة دي."}, {"ref": "مز 23:4", "verse": "عَصَاكَ وَعُكَّازُكَ هُمَا يُعَزِّيَانِنِي", "message": "لما تحتاج إرشاد وتصحيح، متقاومش صوت ربنا؛ رعايته كمان بتقودك للطريق الصح."}, {"ref": "مز 23:2", "verse": "فِي مَرَاعٍ خُضْرٍ يُرْبِضُنِي. إِلَى مِيَاهِ الرَّاحَةِ يُورِدُنِي", "message": "اطلب من السيد المسيح يقودك للراحة الحقيقية، مش مجرد الهروب المؤقت من التعب."}, {"ref": "3يو 1:2", "verse": "أَيُّهَا الْحَبِيبُ، فِي كُلِّ شَيْءٍ أَرُومُ أَنْ تَكُونَ نَاجِحًا وَصَحِيحًا، كَمَا أَنَّ نَفْسَكَ نَاجِحَةٌ", "message": "صلّي من أجل إخواتك إنهم ينموا روحيًا وجسديًا؛ المحبة بتفرح بخير الآخر."}, {"ref": "جا 1:8", "verse": "الْعَيْنُ لاَ تَشْبَعُ مِنَ النَّظَرِ، وَالأُذُنُ لاَ تَمْتَلِئُ مِنَ السَّمْعِ", "message": "مش كل حاجة تشوفها أو تسمعها هتشبع قلبك؛ اختار اللي يبنيك فعلًا."}, {"ref": "رو 14:8", "verse": "إِنْ عِشْنَا فَلِلرَّبِّ نَعِيشُ، وَإِنْ مُتْنَا فَلِلرَّبِّ نَمُوتُ. فَإِنْ عِشْنَا وَإِنْ مُتْنَا فَلِلرَّبِّ نَحْنُ", "message": "خلي انتماءك للسيد المسيح ظاهر في قراراتك، مش بس في وقت الصلاة."}, {"ref": "2تي 2:11", "verse": "إِنْ كُنَّا قَدْ مُتْنَا مَعَهُ فَسَنَحْيَا أَيْضًا مَعَهُ", "message": "الرجاء في الحياة مع السيد المسيح يغيّر نظرتك للألم ويشجعك على الثبات."}, {"ref": "مت 5:13", "verse": "أَنْتُمْ مِلْحُ الأَرْضِ", "message": "المسيح دعاك تكون مؤثرًا بالخير؛ خلي وجودك وسط أصحابك يحفظ المحبة والصدق."}, {"ref": "أف 5:18", "verse": "امْتَلِئُوا بِالرُّوحِ", "message": "اطلب امتلاء الروح القدس، وخلي ثمر الروح يبان في كلامك وتصرفاتك."}, {"ref": "مز 125:3", "verse": "لاَ تَسْتَقِرُّ عَصَا الأَشْرَارِ عَلَى نَصِيبِ الصِّدِّيقِينَ", "message": "متخليش انتشار الشر يخليك تيأس من طريق البر؛ اثبت في الوصية."}, {"ref": "مت 11:29", "verse": "اِحْمِلُوا نِيرِي عَلَيْكُمْ وَتَعَلَّمُوا مِنِّي، لأَنِّي وَدِيعٌ وَمُتَوَاضِعُ الْقَلْبِ، فَتَجِدُوا رَاحَةً لِنُفُوسِكُمْ", "message": "الوداعة والتواضع مش ضعف. اتعلمهما من السيد المسيح في مواقفك اليومية."}, {"ref": "يع 5:15", "verse": "صَلاَةُ الإِيمَانِ تَشْفِي الْمَرِيضَ، وَالرَّبُّ يُقِيمُهُ، وَإِنْ كَانَ قَدْ فَعَلَ خَطِيَّةً تُغْفَرُ لَهْ", "message": "لما حد يتعب أو يمرض، صلّوا مع بعض بإيمان، واهتموا بيه بمحبة."}, {"ref": "مت 5:42", "verse": "مَنْ سَأَلَكَ فَأَعْطِهِ، وَمَنْ أَرَادَ أَنْ يَقْتَرِضَ مِنْكَ فَلاَ تَرُدَّهُ", "message": "خلي إيدك مفتوحة للمحتاج حسب استطاعتك؛ العطاء جزء من طاعة وصية السيد المسيح."}, {"ref": "مز 39:4", "verse": "عَرِّفْنِي يَا رَبُّ نِهَايَتِي وَمِقْدَارَ أَيَّامِي كَمْ هِيَ، فَأَعْلَمَ كَيْفَ أَنَا زَائِلٌ", "message": "افتكر إن وقتك عطية محدودة؛ استخدمه فيما ينفع نفسك والناس."}, {"ref": "عا 5:13", "verse": "يَصْمُتُ الْعَاقِلُ فِي ذلِكَ الزَّمَانِ لأَنَّهُ زَمَانٌ رَدِيءٌ", "message": "قبل ما تتكلم وقت التوتر، اسأل نفسك هل الكلام هيصلح الموقف ولا هيزوده سوءًا."}, {"ref": "1تي 5:22", "verse": "اِحْفَظْ نَفْسَكَ طَاهِرًا", "message": "الطهارة قرار يومي؛ اختار اللي يحفظ قلبك وفكرك وتصرفاتك."}, {"ref": "2بط 1:5-7", "verse": "قَدِّمُوا فِي إِيمَانِكُمْ فَضِيلَةً، وَفِي الْفَضِيلَةِ مَعْرِفَةً، وَفِي الْمَعْرِفَةِ تَعَفُّفًا، وَفِي التَّعَفُّفِ صَبْرًا، وَفِي الصَّبْرِ تَقْوَى، وَفِي التَّقْوَى مَوَدَّةً أَخَوِيَّةً، وَفِي الْمَوَدَّةِ الأَخَوِيَّةِ مَحَبَّةً", "message": "الفضائل بتنمو بالتدرّج: اجتهد في الإيمان والمعرفة وضبط النفس والصبر والمحبة."}, {"ref": "سي 1:16", "verse": "رَأْسُ الْحِكْمَةِ مَخَافَةُ اللهِ. إِنَّهَا تَوَلَّدَتْ فِي الرَّحِمِ مَعَ الْمُؤْمِنِينَ، وَجَعَلَتْ عُشَّهَا بَيْنَ النَّاسِ مَدَى الدَّهْرِ، وَسَتُسَلِّمُ نَفْسَهَا إِلَى ذُرِّيَّتِهِمْ", "message": "الحكمة تبدأ بمخافة ربنا؛ خلي طلب رضاه أساس قراراتك."}, {"ref": "إر 9:23,24", "verse": "لاَ يَفْتَخِرَنَّ الْحَكِيمُ بِحِكْمَتِهِ، وَلاَ يَفْتَخِرِ الْجَبَّارُ بِجَبَرُوتِهِ، وَلاَ يَفْتَخِرِ الْغَنِيُّ بِغِنَاهُ. بَلْ بِهذَا لِيَفْتَخِرَنَّ الْمُفْتَخِرُ: بِأَنَّهُ يَفْهَمُ وَيَعْرِفُنِي أَنِّي أَنَا الرَّبُّ الصَّانِعُ رَحْمَةً وَقَضَاءً وَعَدْلًا فِي الأَرْضِ، لأَنِّي بِهذِهِ أُسَرُّ، يَقُولُ الرَّبُّ", "message": "متفتخرش بقوتك أو نجاحك وحدهم؛ افتخر إنك تعرف ربنا وتحب رحمته وعدله."}, {"ref": "رؤ 2:4", "verse": "عِنْدِي عَلَيْكَ: أَنَّكَ تَرَكْتَ مَحَبَّتَكَ الأُولَى", "message": "لو حسيت إن محبتك الأولى فترت، ارجع للصلاة والتوبة وجدد علاقتك بالسيد المسيح."}, {"ref": "يه 1:2", "verse": "لِتَكْثُرْ لَكُمُ الرَّحْمَةُ وَالسَّلاَمُ وَالْمَحَبَّةُ", "message": "اطلب من ربنا إن الرحمة والسلام والمحبة يكبروا في قلبك وعلاقاتك."}, {"ref": "رو 5:3-5", "verse": "نَفْتَخِرُ أَيْضًا فِي الضِّيقَاتِ، عَالِمِينَ أَنَّ الضِّيقَ يُنْشِئُ صَبْرًا، وَالصَّبْرُ تَزْكِيَةً، وَالتَّزْكِيَةُ رَجَاءً، وَالرَّجَاءُ لاَ يُخْزِي، لأَنَّ مَحَبَّةَ اللهِ قَدِ انْسَكَبَتْ فِي قُلُوبِنَا بِالرُّوحِ الْقُدُسِ الْمُعْطَى لَنَا", "message": "الضيقة مش نهاية الطريق؛ اطلب من ربنا صبرًا ينمّي ثباتك ورجاءك."}, {"ref": "1تي 6:11", "verse": "أَمَّا أَنْتَ يَا إِنْسَانَ اللهِ فَاهْرُبْ مِنْ هذَا، وَاتْبَعِ الْبِرَّ وَالتَّقْوَى وَالإِيمَانَ وَالْمَحَبَّةَ وَالصَّبْرَ وَالْوَدَاعَةَ", "message": "مش كفاية تبعد عن الخطأ؛ اسعَ للبر والإيمان والمحبة والصبر والوداعة."}, {"ref": "1كو 13:1", "verse": "إِنْ كُنْتُ أَتَكَلَّمُ بِأَلْسِنَةِ النَّاسِ وَالْمَلاَئِكَةِ وَلكِنْ لَيْسَ لِي مَحَبَّةٌ، فَقَدْ صِرْتُ نُحَاسًا يَطِنُّ أَوْ صَنْجًا يَرِنُّ", "message": "الكلام الجميل من غير محبة حقيقية يفقد قيمته؛ خليك محبًا في الفعل قبل الكلام."}, {"ref": "أم 3:1-2", "verse": "يَا ابْنِي، لاَ تَنْسَ شَرِيعَتِي، بَلْ لِيَحْفَظْ قَلْبُكَ وَصَايَايَ. فَإِنَّهَا تَزِيدُكَ طُولَ أَيَّامٍ، وَسِنِي حَيَاةٍ وَسَلاَمَةً.", "message": "احفظ وصايا ربنا في قلبك، وحوّل معرفتك بيها لاختيارات عملية كل يوم."}, {"ref": "مت 25:21", "verse": "نِعِمَّا أَيُّهَا الْعَبْدُ الصَّالِحُ وَالأَمِينُ! كُنْتَ أَمِينًا فِي الْقَلِيلِ فَأُقِيمُكَ عَلَى الْكَثِيرِ. اُدْخُلْ إِلَى فَرَحِ سَيِّدِكَ", "message": "الأمانة في التفاصيل الصغيرة تدريب لحياة ثابتة؛ متستهونش بالمسؤولية اللي في إيدك."}, {"ref": "1كو 14:33", "verse": "اللهَ لَيْسَ إِلهَ تَشْوِيشٍ بَلْ إِلهُ سَلاَمٍ", "message": "لما النقاش يتلخبط أو يتحول لخناقة، اسعَ للسلام والوضوح بدل التشويش."}, {"ref": "1أخ 28:20", "verse": "تَشَدَّدْ وَتَشَجَّعْ وَاعْمَلْ. لاَ تَخَفْ وَلاَ تَرْتَعِبْ، لأَنَّ الرَّبَّ الإِلهَ إِلهِي مَعَكَ. لاَ يَخْذُلُكَ وَلاَ يَتْرُكُكَ حَتَّى تُكَمِّلَ كُلَّ عَمَلِ خِدْمَةِ بَيْتِ الرَّبِّ", "message": "الشجاعة مش مجرد حماس؛ ابدأ العمل المطلوب منك واتكل على معونة ربنا."}, {"ref": "مت 6:24", "verse": "لاَ يَقْدِرُ أَحَدٌ أَنْ يَخْدِمَ سَيِّدَيْنِ، لأَنَّهُ إِمَّا أَنْ يُبْغِضَ الْوَاحِدَ وَيُحِبَّ الآخَرَ، أَوْ يُلاَزِمَ الْوَاحِدَ وَيَحْتَقِرَ الآخَرَ. لاَ تَقْدِرُونَ أَنْ تَخْدِمُوا اللهَ وَالْمَالَ.", "message": "راجع أولوياتك: متخليش المال أو المكسب ياخد مكان ربنا في قلبك."}, {"ref": "أم 25:21-22", "verse": "إِنْ جَاعَ عَدُوُّكَ فَأَطْعِمْهُ خُبْزًا، وَإِنْ عَطِشَ فَاسْقِهِ مَاءً، فَإِنَّكَ تَجْمَعُ جَمْرًا عَلَى رَأْسِهِ، وَالرَّبُّ يُجَازِيكَ", "message": "حتى لو حد عداك، متمنعش عنه الخير وقت احتياجه؛ المحبة تتغلب على الانتقام."}, {"ref": "سي 5:15-17", "verse": "فِي الْكَلاَمِ كَرَامَةٌ وَهَوَانٌ، وَلِسَانُ الإِنْسَانِ تَهْلُكَتُهُ. لاَ تُدْعَ نَمَّامًا، وَلاَ تَخْتُلْ بِلِسَانِكَ. فَإِنَّ لِلسَّارِقِ الْخِزْيَ، وَلِذِي اللِّسَانَيْنِ الْمَذَمَّةَ الشَّدِيدَةَ", "message": "حافظ على أسرار الناس وابعد عن النميمة؛ الكلام ممكن يبني الثقة أو يهدمها."}, {"ref": "مز 140:1", "verse": "أَنْقِذْنِي يَا رَبُّ مِنْ أَهْلِ الشَّرِّ. مِنْ رَجُلِ الظُّلْمِ احْفَظْنِي", "message": "لما تتعرض لظلم، صلّي لربنا واطلب حمايته، ومتخليش الخوف يقود تصرفاتك."}, {"ref": "مز 71:4", "verse": "يَا إِلهِي، نَجِّنِي مِنْ يَدِ الشِّرِّيرِ، مِنْ كَفِّ فَاعِلِ الشَّرِّ وَالظَّالِمِ", "message": "وقت القلق من أذى الآخرين، اطلب من ربنا نجاة وحكمة في خطواتك."}, {"ref": "2تي 2:23-24", "verse": "وَالْمُبَاحَثَاتُ الْغَبِيَّةُ وَالسَّخِيفَةُ اجْتَنِبْهَا، عَالِمًا أَنَّهَا تُوَلِّدُ خُصُومَاتٍ، وَعَبْدُ الرَّبِّ لاَ يَجِبُ أَنْ يُخَاصِمَ،", "message": "مش كل نقاش يستاهل تدخل فيه؛ ابعد عن الجدل اللي بيولّد خصامًا."}, {"ref": "يع 5:12", "verse": "لاَ تَحْلِفُوا، لاَ بِالسَّمَاءِ، وَلاَ بِالأَرْضِ، وَلاَ بِقَسَمٍ آخَرَ. بَلْ لِتَكُنْ نَعَمْكُمْ نَعَمْ، وَلاَكُمْ لاَ، لِئَلاَّ تَقَعُوا تَحْتَ دَيْنُونَةٍ", "message": "خلي كلمتك صادقة وواضحة من غير مبالغة أو حلفان."}, {"ref": "رو 6:23", "verse": "أُجْرَةَ الْخَطِيَّةِ هِيَ مَوْتٌ، وَأَمَّا هِبَةُ اللهِ فَهِيَ حَيَاةٌ أَبَدِيَّةٌ بِالْمَسِيحِ يَسُوعَ رَبِّنَا", "message": "الخطية مش حاجة بسيطة، لكن عطية الحياة الأبدية في السيد المسيح تدعوك للتوبة والرجاء."}, {"ref": "سي 21:2", "verse": "اهْرُبْ مِنَ الْخَطِيئَةِ هَرَبَكَ مِنَ الْحَيَّةِ؛ فَإِنَّهَا إِنْ دَنَوْتَ مِنْهَا لَدَغَتْكَ", "message": "ابعد عن الخطية من بدايتها، ومتجربش قوتك في الاقتراب من أسباب السقوط."}, {"ref": "1يو 2:11", "verse": "مَنْ يُبْغِضُ أَخَاهُ فَهُوَ فِي الظُّلْمَةِ، وَفِي الظُّلْمَةِ يَسْلُكُ، وَلاَ يَعْلَمُ أَيْنَ يَمْضِي، لأَنَّ الظُّلْمَةَ أَعْمَتْ عَيْنَيْهِ", "message": "الخصام والكراهية بيظلموا القلب؛ اطلب من السيد المسيح نعمة الغفران والمحبة."}, {"ref": "تك 39:9", "verse": "كَيْفَ أَصْنَعُ هذَا الشَّرَّ الْعَظِيمَ وَأُخْطِئُ إِلَى اللهِ؟!", "message": "وقت التجربة افتكر موقف يوسف: رضا ربنا أهم من أي لذة أو مكسب لحظي."}, {"ref": "يع 1:20", "verse": "لأَنَّ غَضَبَ الإِنْسَانِ لاَ يَصْنَعُ بِرَّ اللهِ", "message": "لما تغضب، متاخدش قرار وأنت منفعل؛ اطلب من ربنا هدوءًا وضبطًا للنفس."}, {"ref": "1بط 2:1", "verse": "اطْرَحُوا كُلَّ خُبْثٍ وَكُلَّ مَكْرٍ وَالرِّيَاءَ وَالْحَسَدَ وَكُلَّ مَذَمَّةٍ", "message": "راجع نيتك واترك الغش والحسد والكلام الجارح؛ النقاوة تبدأ من جوه."}, {"ref": "جا 7:8", "verse": "نِهَايَةُ أَمْرٍ خَيْرٌ مِنْ بَدَايَتِهِ", "message": "متقيسش قيمة حياتك بالبدايات بس؛ كمل الطريق بأمانة وصبر."}, {"ref": "يع 1:2", "verse": "اِحْسِبُوهُ كُلَّ فَرَحٍ يَا إِخْوَتِي حِينَمَا تَقَعُونَ فِي تَجَارِبَ مُتَنَوِّعَةٍ", "message": "لما تمر بتجربة، اطلب صبرًا وثباتًا بدل ما تستسلم للإحباط."}, {"ref": "مز 34:19", "verse": "كَثِيرَةٌ هِيَ بَلاَيَا الصِّدِّيقِ، وَمِنْ جَمِيعِهَا يُنَجِّيهِ الرَّبُّ", "message": "الضيقات موجودة، لكن متفقدش رجاءك في معونة ربنا وسطها."}, {"ref": "إش 5:20", "verse": "وَيْلٌ لِلْقَائِلِينَ لِلشَّرِّ خَيْرًا وَلِلْخَيْرِ شَرًّا، الْجَاعِلِينَ الظَّلاَمَ نُورًا وَالنُّورَ ظَلاَمًا، الْجَاعِلِينَ الْمُرَّ حُلْوًا وَالْحُلْوَ مُرًّا", "message": "خليك واضح في تمييز الخير من الشر، حتى لو الناس حواليك بدّلت المسميات."}, {"ref": "مت 5:44", "verse": "أَحِبُّوا أَعْدَاءَكُمْ. بَارِكُوا لاَعِنِيكُمْ. أَحْسِنُوا إِلَى مُبْغِضِيكُمْ، وَصَلُّوا لأَجْلِ الَّذِينَ يُسِيئُونَ إِلَيْكُمْ وَيَطْرُدُونَكُمْ", "message": "محبة الأعداء مش إحساس بس: صلّي للمسيئين، واطلب نعمة تحسن ليهم بدل الانتقام."}, {"ref": "مت 18:9", "verse": "إِنْ أَعْثَرَتْكَ عَيْنُكَ فَاقْلَعْهَا وَأَلْقِهَا عَنْكَ. خَيْرٌ لَكَ أَنْ تَدْخُلَ الْحَيَاةَ أَعْوَرَ مِنْ أَنْ تُلْقَى فِي جَهَنَّمِ النَّارِ وَلَكَ عَيْنَانِ", "message": "خد أسباب الخطية بجدية، وابعد عن اللي بيعطلك عن الحياة مع ربنا."}, {"ref": "مز 126:5", "verse": "الَّذِينَ يَزْرَعُونَ بِالدُّمُوعِ يَحْصُدُونَ بِالابْتِهَاجِ", "message": "مفيش تعب صادق يضيع عند ربنا؛ خليك ثابت حتى في أيام الدموع."}, {"ref": "1كو 3:16", "verse": "أَمَا تَعْلَمُونَ أَنَّكُمْ هَيْكَلُ اللهِ، وَرُوحُ اللهِ يَسْكُنُ فِيكُمْ؟", "message": "جسدك وحياتك لهما كرامة روحية؛ احفظ نفسك في الطهارة والمسؤولية."}, {"ref": "مز 118:18", "verse": "تَأْدِيبًا أَدَّبَنِي الرَّبُّ، وَإِلَى الْمَوْتِ لَمْ يُسْلِمْنِي", "message": "لما تمر بتأديب أو تصحيح، اسأل ربنا تتعلم وتقوم، مش بس إن التعب ينتهي."}, {"ref": "تك 39:2", "verse": "وَكَانَ الرَّبُّ مَعَ يُوسُفَ فَكَانَ رَجُلاً نَاجِحًا، وَكَانَ فِي بَيْتِ سَيِّدِهِ الْمِصْرِيِّ.", "message": "الأمانة في عملك جزء من شهادتك؛ اعمل بإخلاص زي يوسف، حتى في ظروف صعبة."}, {"ref": "رو 8:31", "verse": "إِنْ كَانَ اللهُ مَعَنَا، فَمَنْ عَلَيْنَا؟", "message": "اتشجع بمعونة ربنا، لكن خليك أمين في الطريق اللي دعاك تمشيه."}, {"ref": "مت 6:6", "verse": "وَأَمَّا أَنْتَ فَمَتَى صَلَّيْتَ فَادْخُلْ إِلَى مِخْدَعِكَ وَأَغْلِقْ بَابَكَ، وَصَلِّ إِلَى أَبِيكَ الَّذِي فِي الْخَفَاءِ. فَأَبُوكَ الَّذِي يَرَى فِي الْخَفَاءِ يُجَازِيكَ عَلاَنِيَةً.", "message": "خصص لحظة صلاة بعيدًا عن لفت النظر؛ خلي علاقتك بربنا صادقة وشخصية."}, {"ref": "مز 50:15", "verse": "وَادْعُنِي فِي يَوْمِ الضِّيقِ أُنْقِذْكَ فَتُمَجِّدَنِي».", "message": "وقت الضيق، بدل ما تقفل على نفسك، صلّي واطلب من ربنا معونته."}, {"ref": "أم 3:5-6", "verse": "تَوَكَّلْ عَلَى الرَّبِّ بِكُلِّ قَلْبِكَ، وَعَلَى فَهْمِكَ لاَ تَعْتَمِدْ. فِي كُلِّ طُرُقِكَ اعْرِفْهُ، وَهُوَ يُقَوِّمُ سُبُلَكَ.", "message": "خطط وفكر، لكن متعتمدش على فهمك وحده؛ اسأل ربنا يوجّه خطواتك."}, {"ref": "أم 8:17", "verse": "الَّذِينَ يُبَكِّرُونَ إِلَيَّ يَجِدُونَنِي.", "message": "ابدأ يومك بطلب الحكمة ومعرفة ربنا بدل ما تسيب الوقت يعدي بلا هدف."}, {"ref": "2كو 9:7", "verse": "الْمُعْطِيَ الْمَسْرُورَ يُحِبُّهُ اللهُ.", "message": "ادّي بمحبة وفرح، مش علشان الناس تمدحك أو تشوفك."}, {"ref": "مز 34:8", "verse": "ذُوقُوا وَانْظُرُوا مَا أَطْيَبَ الرَّبَّ! طُوبَى لِلرَّجُلِ الْمُتَوَكِّلِ عَلَيْهِ", "message": "اختبر صلاح ربنا في حياة الصلاة والطاعة، واتعلم تثق فيه."}, {"ref": "يؤ 1:14", "verse": "قَدِّسُوا صَوْمًا. نَادُوا بِاعْتِكَافٍ. اجْمَعُوا الشُّيُوخَ، جَمِيعَ سُكَّانِ الأَرْضِ إِلَى بَيْتِ الرَّبِّ إِلَهِكُمْ وَاصْرُخُوا إِلَى الرَّبِّ", "message": "الصوم دعوة للتوبة والصلاة؛ شارك بقلبك مش بالمظهر فقط."}, {"ref": "مت 17:21", "verse": "هذَا الْجِنْسُ لاَ يُمْكِنُ أَنْ يَخْرُجَ بِشَيْءٍ إِلاَّ بِالصَّلاَةِ وَالصَّوْمِ", "message": "في الحرب الروحية متستهونش بالصلاة والصوم؛ اطلب من ربنا قوة وثباتًا."}, {"ref": "مت 6:16-18", "verse": "وَمَتَى صُمْتُمْ فَلاَ تَكُونُوا عَابِسِينَ كَالْمُرَائِينَ، فَإِنَّهُمْ يُغَيِّرُونَ وُجُوهَهُمْ لِكَيْ يَظْهَرُوا لِلنَّاسِ صَائِمِينَ. اَلْحَقَّ أَقُولُ لَكُمْ: إِنَّهُمْ قَدِ اسْتَوْفَوْا أَجْرَهُمْ. وَأَمَّا أَنْتَ فَمَتَى صُمْتَ فَادْهُنْ رَأْسَكَ وَاغْسِلْ وَجْهَكَ، لِكَيْ لاَ تَظْهَرَ لِلنَّاسِ صَائِمًا، بَلْ لأَبِيكَ الَّذِي فِي الْخَفَاءِ. فَأَبُوكَ الَّذِي يَرَى فِي الْخَفَاءِ يُجَازِيكَ عَلاَنِيَةً", "message": "الصوم مش عرض قدام الناس؛ خليه علاقة صادقة مع ربنا في الخفاء."}, {"ref": "رو 12:9", "verse": "اَلْمَحَبَّةُ فَلْتَكُنْ بِلاَ رِيَاءٍ. كُونُوا كَارِهِينَ الشَّرَّ، مُلْتَصِقِينَ بِالْخَيْرِ", "message": "المحبة مش مجاملة؛ ارفض الشر، وتمسك بالخير حتى لما يكون صعب."}, {"ref": "1بط 3:11", "verse": "لِيُعْرِضْ عَنِ الشَّرِّ وَيَصْنَعِ الْخَيْرَ، لِيَطْلُبِ السَّلاَمَ وَيَجِدَّ فِي أَثَرِهِ", "message": "صنع السلام محتاج مجهود؛ اسعَ للمصالحة بدل ما تغذي الخصام."}, {"ref": "مت 22:29", "verse": "تَضِلُّونَ إِذْ لاَ تَعْرِفُونَ الْكُتُبَ وَلاَ قُوَّةَ اللهِ", "message": "اقرأ الكتاب المقدس بانتظام علشان تعرف الحق وما تتوهش وراء أفكار غلط."}, {"ref": "يو 10:27-28", "verse": "خِرَافِي تَسْمَعُ صَوْتِي، وَأَنَا أَعْرِفُهَا فَتَتْبَعُنِي، وَأَنَا أُعْطِيهَا حَيَاةً أَبَدِيَّةً، وَلَنْ تَهْلِكَ إِلَى الأَبَدِ، وَلاَ يَخْطَفُهَا أَحَدٌ مِنْ يَدِي", "message": "اسمع كلام السيد المسيح واتبع وصاياه؛ القرب منه يظهر في الطاعة."}, {"ref": "يو 14:2", "verse": "فِي بَيْتِ أَبِي مَنَازِلُ كَثِيرَةٌ", "message": "خلي رجاء الحياة الأبدية يدي اختياراتك النهارده معنى واتجاهًا."}, {"ref": "يو 18:36", "verse": "مَمْلَكَتِي لَيْسَتْ مِنْ هذَا الْعَالَمِ", "message": "ملكوت السيد المسيح غير مبني على مجد العالم؛ خلي قلبك متعلق بما هو أبدي."}, {"ref": "مت 7:14", "verse": "مَا أَضْيَقَ الْبَابَ وَأَكْرَبَ الطَّرِيقَ الَّذِي يُؤَدِّي إِلَى الْحَيَاةِ، وَقَلِيلُونَ هُمُ الَّذِينَ يَجِدُونَهُ", "message": "اختيار طريق الوصية مش دايمًا سهل، لكنه طريق الحياة؛ اثبت فيه."}, {"ref": "مت 11:12", "verse": "مَلَكُوتُ السَّمَاوَاتِ يُغْصَبُ، وَالْغَاصِبُونَ يَخْتَطِفُونَهُ", "message": "الجهاد الروحي محتاج جدية، مش تأجيل؛ ابدأ بخطوة طاعة حقيقية."}, {"ref": "1يو 1:9,10", "verse": "إِنِ اعْتَرَفْنَا بِخَطَايَانَا فَهُوَ أَمِينٌ وَعَادِلٌ، حَتَّى يَغْفِرَ لَنَا خَطَايَانَا وَيُطَهِّرَنَا مِنْ كُلِّ إِثْمٍ. إِنْ قُلْنَا: إِنَّنَا لَمْ نُخْطِئْ نَجْعَلْهُ كَاذِبًا، وَكَلِمَتُهُ لَيْسَتْ فِينَا", "message": "بدل ما تخفي خطيتك أو تبررها، ارجع لربنا بالتوبة والاعتراف بصدق."}, {"ref": "يو 6:55", "verse": "جَسَدِي مَأْكَلٌ حَقٌّ وَدَمِي مَشْرَبٌ حَقٌّ", "message": "التناول سر مقدس؛ اقترب منه بإيمان واستعداد روحي وإرشاد أب اعترافك."}, {"ref": "يو 15:1", "verse": "أَنَا الْكَرْمَةُ الْحَقِيقِيَّةُ", "message": "السيد المسيح هو الكرمة الحقيقية؛ اطلب الثبات فيه علشان حياتك تثمر."}, {"ref": "يو 3:5", "verse": "إِنْ كَانَ أَحَدٌ لاَ يُولَدُ مِنَ الْمَاءِ وَالرُّوحِ لاَ يَقْدِرُ أَنْ يَدْخُلَ مَلَكُوتَ اللهِ", "message": "اشكر ربنا على نعمة الميلاد الجديد بالماء والروح، وعيش كابن له."}, {"ref": "مز 103:1", "verse": "بَارِكِي يَا نَفْسِي الرَّبَّ، وَكُلُّ مَا فِي بَاطِنِي لِيُبَارِكِ اسْمَهُ الْقُدُّوسَ", "message": "خلي الشكر جزءًا من صلاتك، وافتكر عطايا ربنا اللي بتعدي عليها بسرعة."}, {"ref": "1كو 9:27", "verse": "بَلْ أَقْمَعُ جَسَدِي وَأَسْتَعْبِدُهُ، حَتَّى بَعْدَ مَا كَرَزْتُ لِلآخَرِينَ لاَ أَصِيرُ أَنَا نَفْسِي مَرْفُوضًا", "message": "ضبط الجسد والرغبات جزء من الجهاد الروحي؛ درّب نفسك على الأمانة."}, {"ref": "مت 22:37-38", "verse": "تُحِبُّ الرَّبَّ إِلهَكَ مِنْ كُلِّ قَلْبِكَ، وَمِنْ كُلِّ نَفْسِكَ، وَمِنْ كُلِّ فِكْرِكَ، وَمِنْ كُلِّ قُدْرَتِكَ. هذِهِ هِيَ الْوَصِيَّةُ الأُولَى", "message": "محبة ربنا مش مجرد شعور؛ ادّيه قلبك وفكرك وقوتك في كل يوم."}, {"ref": "غل 6:14", "verse": "حَاشَا لِي أَنْ أَفْتَخِرَ إِلاَّ بِصَلِيبِ رَبِّنَا يَسُوعَ الْمَسِيحِ، الَّذِي بِهِ قَدْ صُلِبَ الْعَالَمُ لِي وَأَنَا لِلْعَالَمِ", "message": "خلي افتخارك بصليب السيد المسيح، مش بمكانتك أو إنجازاتك."}, {"ref": "سي 27:17", "verse": "الَّذِي يُفْشِي الأَسْرَارَ يَهْدِمُ الثِّقَةَ. وَلاَ يَجِدُ صَدِيقًا لِنَفْسِهِ", "message": "خيانة السر بتجرح الثقة؛ احفظ كلام أصحابك ومتستخدمهوش ضدهم."}, {"ref": "أم 28:20", "verse": "الرَّجُلُ الأَمِينُ كَثِيرُ الْبَرَكَاتِ، وَالْمُسْتَعْجِلُ إِلَى الْغِنَى لاَ يُبْرَأُ", "message": "اختار الأمانة على المكسب السريع؛ البركة مش في الطريق المختصر الغلط."}, {"ref": "مز 119:164", "verse": "سَبْعَ مَرَّاتٍ فِي النَّهَارِ سَبَّحْتُكَ عَلَى أَحْكَامِ عَدْلِكَ", "message": "وسط زحمة يومك، خصص أوقات تسبّح فيها ربنا وتشكره."}, {"ref": "مت 6:22-23", "verse": "سِرَاجُ الْجَسَدِ هُوَ الْعَيْنُ، فَإِنْ كَانَتْ عَيْنُكَ بَسِيطَةً فَجَسَدُكَ كُلُّهُ يَكُونُ نَيِّرًا، وَإِنْ كَانَتْ عَيْنُكَ شِرِّيرَةً فَجَسَدُكَ كُلُّهُ يَكُونُ مُظْلِمًا، فَإِنْ كَانَ النُّورُ الَّذِي فِيكَ ظَلاَمًا فَالظَّلاَمُ كَمْ يَكُونُ؟!", "message": "احفظ نظرك وفكرك؛ اللي بتدخله لقلبك بيأثر على حياتك."}, {"ref": "أف 5:20", "verse": "شَاكِرِينَ كُلَّ حِينٍ عَلَى كُلِّ شَيْءٍ فِي اسْمِ رَبِّنَا يَسُوعَ الْمَسِيحِ، ِللهِ وَالآبِ", "message": "اشكر ربنا في كل حين، حتى لو اليوم مش ماشي زي ما توقعت."}, {"ref": "أم 10:21", "verse": "شَفَتَا الصِّدِّيقِ تَهْدِيَانِ كَثِيرِينَ، أَمَّا الأَغْبِيَاءُ فَيَمُوتُونَ مِنْ نَقْصِ الْفَهْمِ", "message": "خلي كلامك يرشد ويشجع، مش يجرح أو يضلل."}, {"ref": "مز 39:9", "verse": "صَمَتُّ. لاَ أَفْتَحُ فَمِي، لأَنَّكَ أَنْتَ فَعَلْتَ", "message": "في المواقف اللي مش فاهمها، اتعلم تسكت قدام ربنا وتطلب حكمته."}, {"ref": "مز 119:176", "verse": "ضَلَلْتُ مِثْلَ الخَرُف الْضَال، فاطْلُبْ عَبْدَكَ، لأَنِّي لِوَصَايَاكَ لَمْ أَنْسَ", "message": "لو حسيت إنك بُعدت عن الطريق، ارجع للسيد المسيح واطلب منه يردك ليه؛ متخليش الضياع يبقى آخر الحكاية."}, {"ref": "مز 1:1", "verse": "طُوبَى لِلرَّجُلِ الَّذِي لَمْ يَسْلُكْ فِي مَشُورَةِ الأَشْرَارِ، وَفِي طَرِيقِ الْخُطَاةِ لَمْ يَقِفْ، وَفِي مَجْلِسِ الْمُسْتَهْزِئِينَ لَمْ يَجْلِسْ", "message": "اختيار أصحابك والمكان اللي تقف فيه بيأثر على قلبك؛ اطلب من ربنا حكمة تختار الطريق الصالح."}, {"ref": "مز 41:1", "verse": "طُوبَى لِلَّذِي يَنْظُرُ إِلَى الْمَسْكِينِ. فِي يَوْمِ الشَّرِّ يُنَجِّيهِ الرَّبُّ", "message": "خلي عينك على المحتاج، مش على نفسك بس؛ الرحمة اللي بتقدمها لغيرك عبادة عملية."}, {"ref": "سي 31:14", "verse": "الْعَيْنَ الشِّرِّيرَةَ سُوءٌ عَظِيمٌ", "message": "احفظ نظرتك من الحسد والطمع؛ اشكر ربنا على نصيبك وفرحك بنعمة غيرك."}, {"ref": "في 1:27", "verse": "عِيشُوا كَمَا يَحِقُّ لإِنْجِيلِ الْمَسِيحِ", "message": "قبل ما تتكلم عن إيمانك، خلّي أسلوبك وتصرفاتك يليقوا بإنجيل السيد المسيح."}, {"ref": "مز 69:9", "verse": "غَيْرَةُ بَيْتِكَ أَكَلَتْنِي", "message": "خلّي محبتك لبيت ربنا تظهر في خدمتك واحترامك للصلاة، مش مجرد كلام."}, {"ref": "أم 12:20", "verse": "الْغِشُّ فِي قَلْبِ الَّذِينَ يُفَكِّرُونَ فِي الشَّرِّ، أَمَّا الْمُشِيرُونَ بِالسَّلاَمِ فَلَهُمْ فَرَحٌ", "message": "ما تخططش لإيذاء حد حتى لو زعلك؛ اختار مشورة السلام، وخلّي قلبك بعيد عن الغش."}, {"ref": "مز 138:3", "verse": "فِي يَوْمَ دَعَوْتُكَ أَجَبْتَنِي. شَجَّعْتَنِي قُوَّةً فِي نَفْسِي", "message": "لما تحس إنك مش قادر تكمل، صلّي بصدق واطلب من ربنا قوة تشجع نفسك."}, {"ref": "جا 7:14", "verse": "فِي يَوْمِ الْخَيْرِ كُنْ بِخَيْرٍ، وَفِي يَوْمِ الشَّرِّ اعْتَبِرْ. إِنَّ اللهَ جَعَلَ هذَا مَعَ ذَاكَ، لِكَيْلاَ يَجِدَ الإِنْسَانُ شَيْئًا بَعْدَهُ", "message": "وقت الفرح اشكر، ووقت الشدة اتعلّم؛ خليك قريب من ربنا في الاتنين."}, {"ref": "أم 4:23", "verse": "فوْقَ كُلِّ تَحَفُّظٍ احْفَظْ قَلْبَكَ، لأَنَّ مِنْهُ مَخَارِجَ الْحَيَاةِ", "message": "احرس قلبك من الكلام والأفكار اللي بتسحبك بعيد؛ مش كل حاجة تسمح لها تدخل جواك."}, {"ref": "مز 34:18", "verse": "قَرِيبٌ هُوَ الرَّبُّ مِنَ الْمُنْكَسِرِي الْقُلُوبِ، وَيُخَلِّصُ الْمُنْسَحِقِي الرُّوحِ", "message": "لو قلبك مكسور، متفتكرش إنك بعيد عن ربنا؛ افتح له وجعك في الصلاة."}, {"ref": "مز 51:10", "verse": "قَلْبًا نَقِيًّا اخْلُقْ فِيَّ يَا اَللهُ، وَرُوحًا مُسْتَقِيمًا جَدِّدْ فِي دَاخِلِي", "message": "بدل ما تبرر أخطاءك، اطلب من ربنا يجدد قلبك ويصلح دوافعك من جوه."}, {"ref": "مز 3:7", "verse": "قُمْ يَا رَبُّ! خَلِّصْنِي يَا إِلهِي", "message": "وقت الخوف، اجري على الصلاة واطلب الخلاص من ربنا بدل الاستسلام للقلق."}, {"ref": "إش 3:10", "verse": "قُولُوا لِلصِّدِّيقِ خَيْرٌ! لأَنَّهُمْ يَأْكُلُونَ ثَمَرَ أَفْعَالِهِمْ", "message": "متستهونش بالاختيارات الصالحة الصغيرة؛ ثمر الأمانة بيظهر مع الوقت."}, {"ref": "مز 118:14", "verse": "قُوَّتِي وَتَرَنُّمِي الرَّبُّ، وَقَدْ صَارَ لِي خَلاَصًا", "message": "لما تفتكر خلاص ربنا ومعونته، افتح قلبك للشكر والتسبيح بدل الخوف."}, {"ref": "أم 12:22", "verse": "كَرَاهَةُ الرَّبِّ شَفَتَا كَذِبٍ، أَمَّا الْعَامِلُونَ بِالصِّدْقِ فَرِضَاهُ", "message": "حتى لو الكذبة هتخرجك من موقف صعب، اختار الصدق اللي يرضي ربنا."}, {"ref": "1يو 2:16", "verse": "كُلَّ مَا فِي الْعَالَمِ: شَهْوَةَ الْجَسَدِ، وَشَهْوَةَ الْعُيُونِ، وَتَعَظُّمَ الْمَعِيشَةِ، لَيْسَ مِنَ الآبِ بَلْ مِنَ الْعَالَمِ", "message": "مش كل رغبة تستحق تمشي وراها؛ اطلب من ربنا قلب حر من شهوة التملك والمظاهر."}, {"ref": "1كو 6:12", "verse": "كُلُّ الأَشْيَاءِ تَحِلُّ لِي، لكِنْ لَيْسَ كُلُّ الأَشْيَاءِ تُوافِقُ. كُلُّ الأَشْيَاءِ تَحِلُّ لِي، لكِنْ لاَ يَتَسَلَّطُ عَلَيَّ شَيْءٌ", "message": "اسأل نفسك: الحاجة دي نافعة لي فعلًا؟ وهل بقيت متحكم فيّ؟ الحرية الحقيقية مش عبودية لأي عادة."}, {"ref": "2تي 3:16-17", "verse": "كُلُّ الْكِتَابِ هُوَ مُوحًى بِهِ مِنَ اللهِ، وَنَافِعٌ لِلتَّعْلِيمِ وَالتَّوْبِيخِ، لِلتَّقْوِيمِ وَالتَّأْدِيبِ الَّذِي فِي الْبِرِّ، لِكَيْ يَكُونَ إِنْسَانُ اللهِ كَامِلًا، مُتَأَهِّبًا لِكُلِّ عَمَل صَالِحٍ", "message": "افتح الكتاب المقدس مش علشان تعرف معلومات بس، لكن علشان تتعلم وتتقوّم وتتهيأ للخير."}, {"ref": "مز 25:10", "verse": "كُلُّ سُبُلِ الرَّبِّ رَحْمَةٌ وَحَقٌّ لِحَافِظِي عَهْدِهِ وَشَهَادَاتِهِ", "message": "ربنا يقودك في الحق والرحمة؛ خلي وصيته مرجعك وانت بتاخد قراراتك."}, {"ref": "لو 12:8", "verse": "كُلُّ مَنِ اعْتَرَفَ بِي قُدَّامَ النَّاسِ، يَعْتَرِفُ بِهِ ابْنُ الإِنْسَانِ قُدَّامَ مَلاَئِكَةِ اللهِ", "message": "متخجلش تعترف بالسيد المسيح وسط الناس؛ خلي إيمانك واضح بمحبة واتضاع."}, {"ref": "تث 30:14", "verse": "الْكَلِمَةُ قَرِيبَةٌ مِنْكَ جِدًّا، فِي فَمِكَ وَفِي قَلْبِكَ لِتَعْمَلَ بِهَا", "message": "كلمة ربنا مش للقراءة بس؛ خلّي اللي تعرفه من الوصية يتحوّل لعمل."}, {"ref": "جا 3:1", "verse": "لِكُلِّ شَيْءٍ زَمَانٌ، وَلِكُلِّ أَمْرٍ تَحْتَ السَّمَاوَاتِ وَقْتٌ", "message": "مش كل حاجة لازم تحصل دلوقتي؛ اتعلم تصبر وتستخدم وقتك بأمانة."}, {"ref": "مت 5:39", "verse": "لاَ تُقَاوِمُوا الشَّرَّ، بَلْ مَنْ لَطَمَكَ عَلَى خَدِّكَ الأَيْمَنِ فَحَوِّلْ لَهُ الآخَرَ أَيْضًا", "message": "لما حد يستفزك، متخليش رد فعلك مجرد انتقام؛ اطلب نعمة الهدوء من السيد المسيح."}, {"ref": "يش 1:8", "verse": "لاَ يَبْرَحْ سِفْرُ هذِهِ الشَّرِيعَةِ مِنْ فَمِكَ، بَلْ تَلْهَجُ فِيهِ نَهَارًا وَلَيْلًا، لِكَيْ تَتَحَفَّظَ لِلْعَمَلِ حَسَبَ كُلِّ مَا هُوَ مَكْتُوبٌ فِيهِ. لأَنَّكَ حِينَئِذٍ تُصْلِحُ طَرِيقَكَ وَحِينَئِذٍ تُفْلِحُ", "message": "خصص وقت ثابت لكلمة ربنا، وخلي قراءتك تقودك للطاعة مش مجرد إنهاء صفحات."}, {"ref": "مت 9:12", "verse": "لاَ يَحْتَاجُ الأَصِحَّاءُ إِلَى طَبِيبٍ بَلِ الْمَرْضَى", "message": "السيد المسيح جاء ينادي الخطاة؛ متخلّيش ضعفك يبعدك عن التوبة والرجوع له."}, {"ref": "1تي 4:15", "verse": "لاَحِظْ نَفْسَكَ وَالتَّعْلِيمَ وَدَاوِمْ عَلَى ذلِكَ، لأَنَّكَ إِذَا فَعَلْتَ هذَا، تُخَلِّصُ نَفْسَكَ وَالَّذِينَ يَسْمَعُونَكَ أَيْضًا", "message": "النمو الروحي محتاج مواظبة؛ راقب تقدمك في المحبة والصلاة بدل انتظار تغيير مفاجئ."}, {"ref": "أم 3:27", "verse": "لاَ تَمْنَعِ الْخَيْرَ عَنْ أَهْلِهِ، حِينَ يَكُونُ فِي طَاقَةِ يَدِكَ أَنْ تَفْعَلَهُ", "message": "لو الخير في إيدك النهارده، متأجلوش؛ اسند حد محتاج فعلًا."}, {"ref": "سي 12:8", "verse": "لاَ يُعْرَفُ الصَّدِيقُ فِي السَّرَّاءِ، وَلاَ يَخْفَى الْعَدُوُّ فِي الضَّرَّاءِ", "message": "الصداقة الحقيقية بتظهر وقت الضيقة؛ اختار اللي يسندك للخير ويقف جنبك في التعب."}, {"ref": "سي 4:31", "verse": "لاَ تَسْتَحِي أَنْ تَعْتَرِفَ بِخَطَايَاكَ، وَلاَ تُغَالِبْ مَجْرَى النَّهْرِ", "message": "الاعتراف بالخطأ مش عيب؛ ابدأ بالصراحة مع نفسك، وارجع لربنا بقلب تائب."}, {"ref": "أم 24:1-2", "verse": "لاَ تَحْسِدْ أَهْلَ الشَّرِّ، وَلاَ تَشْتَهِ أَنْ تَكُونَ مَعَهُمْ، لأَنَّ قَلْبَهُمْ يَلْهَجُ بِالاغْتِصَابِ، وَشِفَاهَهُمْ تَتَكَلَّمُ بِالْمَشَقَّةِ", "message": "متنبهرش بنجاح مبني على ظلم؛ اختار الصح حتى لو الطريق أبطأ."}, {"ref": "رو 10:15", "verse": "مَا أَجْمَلَ أَقْدَامَ الْمُبَشِّرِينَ بِالسَّلاَمِ، الْمُبَشِّرِينَ بِالْخَيْرَاتِ", "message": "كلمة سلام وتشجيع صادقة ممكن تفتح باب للخير؛ خلي وجودك يبشّر بمحبة السيد المسيح."}, {"ref": "مز 84:1", "verse": "مَا أَحْلَى مَسَاكِنَكَ يَا رَبَّ الْجُنُودِ", "message": "خلي ليك اشتياق حقيقي لبيت ربنا؛ القداس والصلاة شركة مش مجرد موعد."}, {"ref": "أم 19:17", "verse": "مَنْ يَرْحَمُ الْفَقِيرَ يُقْرِضُ الرَّبَّ، وَعَنْ مَعْرُوفِهِ يُجَازِيهِ", "message": "ساعد الفقير بكرامة ومن غير انتظار مقابل؛ ربنا يرى المحبة في العطاء."}, {"ref": "أم 24:8", "verse": "الْمُتَفَكِّرُ فِي عَمَلِ الشَّرِّ يُدْعَى مُفْسِدًا", "message": "قبل ما الفكرة الشريرة تتحول لتصرف، ارفضها واطلب من ربنا ينقّي قصدك."}, {"ref": "أم 15:12", "verse": "الْمُسْتَهْزِئُ لاَ يُحِبُّ مُوَبِّخَهُ. إِلَى الْحُكَمَاءِ لاَ يَذْهَبُ", "message": "لما حد ينبهك لخطأ، اسمع الأول بدل الدفاع المستمر عن نفسك."}, {"ref": "لو 14:27", "verse": "مَنْ لاَ يَحْمِلُ صَلِيبَهُ وَيَأْتِي وَرَائِي فَلاَ يَقْدِرُ أَنْ يَكُونَ لِي تِلْمِيذًا", "message": "اتباع السيد المسيح فيه احتمال وتضحية؛ اطلب منه ثباتًا وقت الصعوبة."}, {"ref": "مت 12:30", "verse": "مَنْ لَيْسَ مَعِي فَهُوَ عَلَيَّ، وَمَنْ لاَ يَجْمَعُ مَعِي فَهُوَ يُفَرِّقُ", "message": "متخليش علاقتك بالسيد المسيح مجرد موقف متردد؛ اختار تتبعه بأمانة."}, {"ref": "أم 28:27", "verse": "مَنْ يُعْطِي الْفَقِيرَ لاَ يَحْتَاجُ", "message": "متقفلش قلبك قدام المحتاج؛ اتعلم العطاء بحكمة ومحبة."}, {"ref": "رو 14:19", "verse": "فَلْنَعْكُفْ إِذًا عَلَى مَا هُوَ لِلسَّلاَمِ، وَمَا هُوَ لِلْبُنْيَانِ بَعْضُنَا لِبَعْضٍ", "message": "قبل أي نقاش اسأل: كلامي هيبني ولا هيكسر؟ اختار اللي يعمل سلام ويشجع غيرك."}, {"ref": "2بط 1:4", "verse": "هَارِبِينَ مِنَ الْفَسَادِ الَّذِي فِي الْعَالَمِ بِالشَّهْوَةِ", "message": "ابعد عن اللي يجرّك للفساد والشهوة، وتمسك بوعد الحياة مع ربنا."}, {"ref": "إش 1:18", "verse": "هَلُمَّ نَتَحَاجَجْ، يَقُولُ الرَّبُّ. إِنْ كَانَتْ خَطَايَاكُمْ كَالْقِرْمِزِ تَبْيَضُّ كَالثَّلْجِ. إِنْ كَانَتْ حَمْرَاءَ كَالدُّودِيِّ تَصِيرُ كَالصُّوفِ", "message": "حتى لو خطيتك كبيرة في نظرك، متيأسش من التوبة؛ ارجع لربنا واطلب تطهيره."}, {"ref": "أم 23:12", "verse": "وَجِّهْ قَلْبَكَ إِلَى الأَدَبِ، وَأُذُنَيْكَ إِلَى كَلِمَاتِ الْمَعْرِفَةِ", "message": "افتح قلبك للتعليم والتصحيح؛ الحكمة محتاجة أذن تسمع وقلب يتعلم."}, {"ref": "سي 6:18", "verse": "يَا بُنَيَّ، اتَّخِذِ التَّأْدِيبَ مُنْذُ شَبَابِكَ، فَتَجِدَ الْحِكْمَةَ إِلَى مَشِيبِكَ", "message": "ما تستناش تكبر علشان تطلب الحكمة؛ ابدأ من شبابك بالتعلم والطاعة."}, {"ref": "أم 23:26", "verse": "يَا ابْنِي أَعْطِنِي قَلْبَكَ، وَلْتُلاَحِظْ عَيْنَاكَ طُرُقِي", "message": "ربنا عايز قلبك، مش مجرد مظهر متدين؛ سلّمه اختياراتك ووقتك."}, {"ref": "أم 3:11-12", "verse": "يَا ابْنِي، لاَ تَحْتَقِرْ تَأْدِيبَ الرَّبِّ وَلاَ تَكْرَهْ تَوْبِيخَهُ، لأَنَّ الَّذِي يُحِبُّهُ الرَّبُّ يُؤَدِّبُهُ، وَكَأَبٍ بِابْنٍ يُسَرُّ بِهِ", "message": "لما تلاقي تصحيح صعب، متعتبرهوش رفض؛ اتعلم منه واطلب من ربنا قلب متواضع."}, {"ref": "مت 5:16", "verse": "فَلْيُضِئْ نُورُكُمْ هكَذَا قُدَّامَ النَّاسِ، لِكَيْ يَرَوْا أَعْمَالَكُمُ الْحَسَنَةَ، وَيُمَجِّدُوا أَبَاكُمُ الَّذِي فِي السَّمَاوَاتِ", "message": "اعمل الخير بأمانة علشان الناس تمجّد ربنا، مش علشان يمدحوك."}, {"ref": "إر 15:20", "verse": "فَيُحَارِبُونَكَ وَلاَ يَقْدِرُونَ عَلَيْكَ، لأَنِّي مَعَكَ لأُخَلِّصَكَ وَأُنْقِذَكَ، يَقُولُ الرَّبُّ", "message": "وقت المقاومة والتعب، اطلب من ربنا قوة تكمّل بيها بأمانة."}, {"ref": "إش 40:29", "verse": "يُعْطِي الْمُعْيِيَ قُدْرَةً وَلِعَدِيمِ الْقُوَّةِ يُكَثِّرُ شِدَّةً.", "message": "لو طاقتك خلصت، اطلب من ربنا قوة؛ الضعف مش سبب إنك تبطل الصلاة."}, {"ref": "مز 103:3", "verse": "الَّذِي يَغْفِرُ جَمِيعَ ذُنُوبِكِ. الَّذِي يَشْفِي كُلَّ أَمْرَاضِكِ.", "message": "افتكر غفران ربنا وإحساناته، وقابل رحمته بالتوبة والشكر."}, {"ref": "إش 53:5", "verse": "وَهُوَ مَجْرُوحٌ لأَجْلِ مَعَاصِينَا مَسْحُوقٌ لأَجْلِ آثَامِنَا. تَأْدِيبُ سَلاَمِنَا عَلَيْهِ وَبِحُبُرِهِ شُفِينَا.", "message": "اتأمل في آلام السيد المسيح لأجل خطايانا، وخلي محبته تدعوك للتوبة."}, {"ref": "رو 12:17", "verse": "لاَ تُجَازُوا أَحَداً عَنْ شَرٍّ بِشَرٍّ. مُعْتَنِينَ بِأُمُورٍ حَسَنَةٍ قُدَّامَ جَمِيعِ النَّاسِ.", "message": "لما تتظلم، متردش الشر بشر؛ خليك أمين في عمل الخير قدام الجميع."}, {"ref": "أم 28:13", "verse": "مَنْ يَكْتُمُ خَطَايَاهُ لاَ يَنْجَحُ وَمَنْ يُقِرُّ بِهَا وَيَتْرُكُهَا يُرْحَمُ.", "message": "متغطيش على الخطية بالتبرير؛ اعترف بيها واتركها واطلب الرحمة."}, {"ref": "يع 5:16", "verse": "اِعْتَرِفُوا بَعْضُكُمْ لِبَعْضٍ بِالّزَلاَّتِ، وَصَلُّوا بَعْضُكُمْ لأَجْلِ بَعْضٍ لِكَيْ تُشْفَوْا. طِلْبَةُ الْبَارِّ تَقْتَدِرُ كَثِيراً فِي فِعْلِهَا.", "message": "صلّوا لأجل بعض بمحبة، وماتستهونش بقوة الصلاة الصادقة."}, {"ref": "مت 7:7", "verse": "اسْأَلُوا تُعْطَوْا. اطْلُبُوا تَجِدُوا. اقْرَعُوا يُفْتَحْ لَكُمْ.", "message": "استمر في الطلب والصلاة من غير يأس؛ خلي قلبك متكلًا على ربنا."}, {"ref": "يو 15:7", "verse": "إِنْ ثَبَتُّمْ فِيَّ وَثَبَتَ كلاَمِي فِيكُمْ تَطْلُبُونَ مَا تُرِيدُونَ فَيَكُونُ لَكُمْ.", "message": "خلي كلمة السيد المسيح ثابتة فيك؛ الصلاة مش منفصلة عن الحياة معاه."}, {"ref": "إر 33:3", "verse": "اُدْعُنِي فَأُجِيبَكَ وَأُخْبِرَكَ بِعَظَائِمَ وَعَوَائِصَ لَمْ تَعْرِفْهَا.", "message": "وقت الحيرة، ادعُ ربنا واطلب إرشاده؛ مش لازم تكون فاهم كل حاجة من الأول."}, {"ref": "إر 29:13", "verse": "وَتَطْلُبُونَنِي فَتَجِدُونَنِي إِذْ تَطْلُبُونَنِي بِكُلِّ قَلْبِكُمْ.", "message": "دوّر على ربنا من كل قلبك، مش وقت الاحتياج بس."}, {"ref": "إش 65:24", "verse": "وَيَكُونُ أَنِّي قَبْلَمَا يَدْعُونَ أَنَا أُجِيبُ وَفِيمَا هُمْ يَتَكَلَّمُونَ بَعْدُ أَنَا أَسْمَعُ.", "message": "افتكر إن ربنا يسمع؛ صلّي بثقة، حتى لو الإجابة مش زي تصورك."}, {"ref": "يو 3:16", "verse": "لأَنَّهُ هَكَذَا أَحَبَّ اللَّهُ الْعَالَمَ حَتَّى بَذَلَ ابْنَهُ الْوَحِيدَ لِكَيْ لاَ يَهْلِكَ كُلُّ مَنْ يُؤْمِنُ بِهِ بَلْ تَكُونُ لَهُ الْحَيَاةُ الأَبَدِيَّةُ.", "message": "محبة ربنا ظهرت في بذل الابن الوحيد؛ ردّ على المحبة دي بإيمان وحياة توبة."}, {"ref": "بط 4:8", "verse": "وَلَكِنْ قَبْلَ كُلِّ شَيْءٍ لِتَكُنْ مَحَبَّتُكُمْ بَعْضِكُمْ لِبَعْضٍ شَدِيدَةً، لأَنَّ الْمَحَبَّةَ تَسْتُرُ كَثْرَةً مِنَ الْخَطَايَا.", "message": "لا تسيب الخلافات الصغيرة تهدم أخوّتك؛ تمسك بالمحبة والغفران."}, {"ref": "مت 7:12", "verse": "فَكُلُّ مَا تُرِيدُونَ أَنْ يَفْعَلَ النَّاسُ بِكُمُ افْعَلُوا هَكَذَا أَنْتُمْ أَيْضاً بِهِمْ لأَنَّ هَذَا هُوَ النَّامُوسُ وَالأَنْبِيَاءُ.", "message": "عامل الناس بالرحمة والاحترام اللي تتمناه لنفسك، حتى في المواقف البسيطة."}, {"ref": "كو 3:13,14", "verse": "مُحْتَمِلِينَ بَعْضُكُمْ بَعْضاً، وَمُسَامِحِينَ بَعْضُكُمْ بَعْضاً انْ كَانَ لأَحَدٍ عَلَى احَدٍ شَكْوَى. كَمَا غَفَرَ لَكُمُ الْمَسِيحُ هَكَذَا انْتُمْ ايْضاً.وَعَلَى جَمِيعِ هَذِهِ الْبَسُوا الْمَحَبَّةَ الَّتِي هِيَ رِبَاطُ الْكَمَالِ.", "message": "لو حد أخطأ في حقك، اطلب من السيد المسيح قلب يسامح بدل ما يحتفظ بالمرارة."}, {"ref": "يو 15:13", "verse": "لَيْسَ لأَحَدٍ حُبٌّ أَعْظَمُ مِنْ هَذَا أَنْ يَضَعَ أَحَدٌ نَفْسَهُ لأَجْلِ أَحِبَّائِهِ.", "message": "المحبة مش كلام حلو وبس؛ اسأل نفسك إزاي تضحّي بوقتك وراحتك لخير غيرك."}, {"ref": "يو 4:19", "verse": "نَحْنُ نُحِبُّهُ لأَنَّهُ هُوَ أَحَبَّنَا أَوَّلاً.", "message": "محبتنا لربنا رد على محبته السابقة؛ خليه الأول في اختياراتك."}, {"ref": "مز 55:22", "verse": "أَلْقِ عَلَى الرَّبِّ هَمَّكَ فَهُوَ يَعُولُكَ. لاَ يَدَعُ الصِّدِّيقَ يَتَزَعْزَعُ إِلَى الأَبَدِ.", "message": "احكي همّك لربنا في الصلاة، واطلب معونته بدل ما تشيل كل شيء لوحدك."}, {"ref": "مز 62:8", "verse": "تَوَكَّلُوا عَلَيْهِ فِي كُلِّ حِينٍ يَا قَوْمُ. اسْكُبُوا قُدَّامَهُ قُلُوبَكُمْ. اللهُ مَلْجَأٌ لَنَا. سِلاَهْ.", "message": "مش محتاج كلام منمق؛ اسكب قلبك قدام ربنا بكل اللي فيه."}, {"ref": "أم 3:12", "verse": "لأَنَّ الَّذِي يُحِبُّهُ الرَّبُّ يُؤَدِّبُهُ وَكَأَبٍ بِابْنٍ يُسَرُّ بِهِ.", "message": "لو اتصححت في حاجة، متفقدش الثقة في محبة ربنا؛ اتعلم وابدأ من جديد."}, {"ref": "يو 15:4", "verse": "اُثْبُتُوا فِيَّ وَأَنَا فِيكُمْ. كَمَا أَنَّ الْغُصْنَ لاَ يَقْدِرُ أَنْ يَأْتِيَ بِثَمَرٍ مِنْ ذَاتِهِ إِنْ لَمْ يَثْبُتْ فِي الْكَرْمَةِ كَذَلِكَ أَنْتُمْ أَيْضاً إِنْ لَمْ تَثْبُتُوا فِيَّ.", "message": "خلي صلاتك ووصيتك مصدر ثباتك في السيد المسيح؛ الثمر بييجي من الشركة معاه."}, {"ref": "رو 6:13", "verse": "وَلاَ تُقَدِّمُوا أَعْضَاءَكُمْ آلاَتِ إِثْمٍ لِلْخَطِيَّةِ بَلْ قَدِّمُوا ذَوَاتِكُمْ لِلَّهِ كَأَحْيَاءٍ مِنَ الأَمْوَاتِ وَأَعْضَاءَكُمْ آلاَتِ بِرٍّ لِلَّهِ.", "message": "استخدم وقتك وجسمك ومواهبك للخير، بدل ما تسيبها أدوات للخطية."}, {"ref": "يع 1:2,3", "verse": "اِحْسِبُوهُ كُلَّ فَرَحٍ يَا إِخْوَتِي حِينَمَا تَقَعُونَ فِي تَجَارِبَ مُتَنَّوِعَةٍ، عَالِمِينَ أَنَّ امْتِحَانَ إِيمَانِكُمْ يُنْشِئُ صَبْراً.", "message": "التجارب مش سهلة، لكن اطلب من ربنا صبرًا يثبت إيمانك وسطها."}, {"ref": "يع 4:7", "verse": "فَاخْضَعُوا لِلَّهِ. قَاوِمُوا إِبْلِيسَ فَيَهْرُبَ مِنْكُمْ.", "message": "الخضوع لربنا يديك اتجاه واضح؛ قاوم الشر ومتساومش مع التجربة."}, {"ref": "حز 36:26", "verse": "وَأُعْطِيكُمْ قَلْباً جَدِيداً, وَأَجْعَلُ رُوحاً جَدِيدَةً فِي دَاخِلِكُمْ, وَأَنْزِعُ قَلْبَ الْحَجَرِ مِنْ لَحْمِكُمْ وَأُعْطِيكُمْ قَلْبَ لَحْمٍ.", "message": "بدل الاعتماد على قوتك وحدك، اطلب من ربنا يجدد قلبك وينزع القساوة."}, {"ref": "في 3:13,14", "verse": "أَيُّهَا الإِخْوَةُ، أَنَا لَسْتُ أَحْسِبُ نَفْسِي أَنِّي قَدْ أَدْرَكْتُ. وَلَكِنِّي أَفْعَلُ شَيْئاً وَاحِداً: إِذْ أَنَا أَنْسَى مَا هُوَ وَرَاءُ وَأَمْتَدُّ إِلَى مَا هُوَ قُدَّامُ. أَسْعَى نَحْوَ الْغَرَضِ لأَجْلِ جَعَالَةِ دَعْوَةِ اللهِ الْعُلْيَا فِي الْمَسِيحِ يَسُوعَ.", "message": "متخليش إخفاقات امبارح تمنع جهاد النهارده؛ كمل نحو دعوة السيد المسيح."}, {"ref": "كو 9:6", "verse": "هَذَا وَإِنَّ مَنْ يَزْرَعُ بِالشُّحِّ فَبِالشُّحِّ أَيْضاً يَحْصُدُ، وَمَنْ يَزْرَعُ بِالْبَرَكَاتِ فَبِالْبَرَكَاتِ أَيْضاً يَحْصُدُ.", "message": "البذل مش خسارة؛ اتعلم تزرع خيرًا بسخاء ومن غير حسابات أنانية."}, {"ref": "غل 6:1", "verse": "أَيُّهَا الإِخْوَةُ، إِنِ انْسَبَقَ إِنْسَانٌ فَأُخِذَ فِي زَلَّةٍ مَا، فَأَصْلِحُوا أَنْتُمُ الرُّوحَانِيِّينَ مِثْلَ هَذَا بِرُوحِ الْوَدَاعَةِ، نَاظِرًا إِلَى نَفْسِكَ لِئَلاَّ تُجَرَّبَ أَنْتَ أَيْضًا.", "message": "لو شفت حد وقع، ساعده يقوم بوداعة بدل ما تفضحه، وافتكر إنك أنت كمان محتاج رحمة."}, {"ref": "غل 6:2", "verse": "اِحْمِلُوا بَعْضُكُمْ أَثْقَالَ بَعْضٍ، وَهَكَذَا تَمِّمُوا نَامُوسَ الْمَسِيحِ.", "message": "متسيبش صاحبك يشيل تعبه وحده؛ شاركه الحمل بمحبة وعمل."}, {"ref": "غل 6:3", "verse": "لأَنَّهُ إِنْ ظَنَّ أَحَدٌ أَنَّهُ شَيْءٌ وَهُوَ لَيْسَ شَيْئًا، فَإِنَّهُ يَغُشُّ نَفْسَهُ.", "message": "متخليش الإعجاب بنفسك يعميك؛ خليك متواضعًا وصريحًا مع نفسك."}, {"ref": "غل 6:7", "verse": "لَا تَضِلُّوا! اَللهُ لَا يُشْمَخُ عَلَيْهِ. فَإِنَّ الَّذِي يَزْرَعُهُ الإِنْسَانُ إِيَّاهُ يَحْصُدُ أَيْضًا.", "message": "اختياراتك اليومية ليها ثمر؛ ازرع خيرًا حتى في اللي محدش شايفه."}, {"ref": "غل 6:8", "verse": "لأَنَّ مَنْ يَزْرَعُ لِجَسَدِهِ فَمِنَ الْجَسَدِ يَحْصُدُ فَسَادًا، وَمَنْ يَزْرَعُ لِلرُّوحِ فَمِنَ الرُّوحِ يَحْصُدُ حَيَاةً أَبَدِيَّةً.", "message": "اهتم بالاختيارات اللي تغذي حياتك الروحية بدل ما تسيب نفسك للشهوة."}, {"ref": "غل 6:9", "verse": "فَلَا نَفْشَلْ فِي عَمَلِ الْخَيْرِ لأَنَّنَا سَنَحْصُدُ فِي وَقْتِهِ إِنْ كُنَّا لَا نَكِلُّ.", "message": "حتى لو خيرك مش ظاهر ثمره دلوقتي، متبطلش تعمل الصالح."}, {"ref": "غل 6:10", "verse": "فَإِذًا حَسْبَمَا لَنَا فُرْصَةٌ فَلْنَعْمَلِ الْخَيْرَ لِلْجَمِيعِ، وَلَا سِيَّمَا لأَهْلِ الإِيمَانِ.", "message": "متستناش مناسبة كبيرة علشان تعمل الخير؛ استغل الفرصة اللي قدامك."}, {"ref": "أف 4:2", "verse": "بِكُلِّ تَوَاضُعٍ، وَوَدَاعَةٍ، وَبِطُولِ أَنَاةٍ، مُحْتَمِلِينَ بَعْضُكُمْ بَعْضًا فِي الْمَحَبَّةِ.", "message": "في البيت والخدمة، احتمال الناس بحب محتاج تواضع وصبر، مش عصبية."}, {"ref": "أف 4:3", "verse": "مُجْتَهِدِينَ أَنْ تَحْفَظُوا وَحْدَانِيَّةَ الرُّوحِ بِرِبَاطِ السَّلاَمِ.", "message": "متستهونش بكلمة تصلح خلافًا؛ اسعَ لوحدة المحبة والسلام."}, {"ref": "أف 4:7", "verse": "وَلكِنْ لِكُلِّ وَاحِدٍ مِنَّا أُعْطِيَتِ النِّعْمَةُ حَسَبَ قِيَاسِ هِبَةِ الْمَسِيحِ.", "message": "متقارنش موهبتك بغيرك؛ اشكر السيد المسيح واستخدم عطيتك للخير."}, {"ref": "أف 4:14", "verse": "كَيْ لَا نَكُونَ فِي مَا بَعْدُ أَطْفَالًا مُضْطَرِبِينَ وَمَحْمُولِينَ بِكُلِّ رِيحِ تَعْلِيمٍ، بِحِيلَةِ النَّاسِ، بِمَكْرٍ إِلَى مَكِيدَةِ الضَّلاَلِ.", "message": "مش كل فكرة منتشرة صح؛ ثبّت إيمانك في تعليم الكنيسة."}, {"ref": "أف 4:15", "verse": "بَلْ صَادِقِينَ فِي الْمَحَبَّةِ، نَنْمُو فِي كُلِّ شَيْءٍ إِلَى ذَاكَ الَّذِي هُوَ الرَّأْسُ: الْمَسِيحُ،", "message": "قول الحق بمحبة؛ الصراحة من غير قسوة تساعدك وتنمي غيرك."}, {"ref": "أف 4:22-24", "verse": "أَنْ تَخْلَعُوا مِنْ جِهَةِ التَّصَرُّفِ السَّابِقِ الإِنْسَانَ الْعَتِيقَ الْفَاسِدَ بِحَسَبِ شَهَوَاتِ الْغُرُورِ، وَتَتَجَدَّدُوا بِرُوحِ ذِهْنِكُمْ، وَتَلْبَسُوا الإِنْسَانَ الْجَدِيدَ الْمَخْلُوقَ بِحَسَبِ اللهِ فِي الْبِرِّ وَقَدَاسَةِ الْحَقِّ.", "message": "التوبة مش مجرد ترك عادة؛ اطلب من ربنا يجدد فكرك وسلوكك."}, {"ref": "أف 4:25", "verse": "لِذَلِكَ اطْرَحُوا عَنْكُمُ الْكَذِبَ، وَتَكَلَّمُوا بِالصِّدْقِ كُلُّ وَاحِدٍ مَعَ قَرِيبِهِ، لأَنَّنَا بَعْضَنَا أَعْضَاءُ الْبَعْضِ.", "message": "الصدق يحفظ الثقة بين الناس؛ متضحّيش بيه علشان مكسب سريع."}, {"ref": "أف 4:26", "verse": "اِغْضَبُوا وَلَا تُخْطِئُوا. لَا تَغْرُبِ الشَّمْسُ عَلَى غَيْظِكُمْ،", "message": "لو اتضايقت، متسيبش الغضب يقودك للخطية؛ اسعَ للصلح بسرعة."}, {"ref": "أف 4:28", "verse": "لَا يَسْرِقِ السَّارِقُ فِي مَا بَعْدُ، بَلْ بِالْحَرِيِّ يَتْعَبُ عَامِلًا الصَّالِحَ بِيَدَيْهِ، لِيَكُونَ لَهُ أَنْ يُعْطِيَ مَنْ لَهُ احْتِيَاجٌ.", "message": "اشتغل بأمانة، وخلي تعب إيدك سبب إنك تساعد محتاجًا."}, {"ref": "أف 4:29", "verse": "لَا تَخْرُجْ كَلِمَةٌ رَدِيَّةٌ مِنْ أَفْوَاهِكُمْ، بَلْ كُلُّ مَا كَانَ صَالِحًا لِلْبُنْيَانِ، حَسَبَ الْحَاجَةِ، كَيْ يُعْطِيَ نِعْمَةً لِلسَّامِعِينَ.", "message": "قبل ما تتكلم، اسأل نفسك: كلامي هيقوي اللي قدامي ولا يجرحه؟"}, {"ref": "أف 4:31", "verse": "لِيُرْفَعْ مِنْ بَيْنِكُمْ كُلُّ مَرَارَةٍ وَسَخَطٍ وَغَضَبٍ وَصِيَاحٍ وَتَجْدِيفٍ مَعَ كُلِّ خُبْثٍ.", "message": "متخزنش مرارة جواك؛ اطلب من ربنا ينزع الحقد ويعلّمك السلام."}, {"ref": "أف 4:32", "verse": "وَكُونُوا لُطَفَاءَ بَعْضُكُمْ نَحْوَ بَعْضٍ، شَفُوقِينَ مُتَسَامِحِينَ كَمَا سَامَحَكُمُ اللهُ أَيْضًا فِي الْمَسِيحِ.", "message": "خليك رقيق في كلامك وسريع في المسامحة، فاكرًا غفران السيد المسيح ليك."}, {"ref": "رو 12:2", "verse": "وَلَا تُشَاكِلُوا هَذَا الدَّهْرَ، بَلْ تَغَيَّرُوا عَنْ شَكْلِكُمْ بِتَجْدِيدِ أَذْهَانِكُمْ، لِتَخْتَبِرُوا مَا هِيَ إِرَادَةُ اللهِ: الصَّالِحَةُ الْمَرْضِيَّةُ الْكَامِلَةُ.", "message": "مش لازم تقلّد كل اللي حواليك؛ خلّي كلمة ربنا تجدّد طريقة تفكيرك."}, {"ref": "رو 12:8", "verse": "أَمِ الْوَاعِظُ فَفِي الْوَعْظِ، الْمُعْطِي فَبِسَخَاءٍ، الْمُدَبِّرُ فَبِاجْتِهَادٍ، الرَّاحِمُ فَبِسُرُورٍ.", "message": "استخدم موهبتك بجدية وفرح؛ الخدمة مش سباق للمظهر."}, {"ref": "رو 12:11", "verse": "غَيْرَ مُتَكَاسِلِينَ فِي الاجْتِهَادِ، حَارِّينَ فِي الرُّوحِ، عَابِدِينَ الرَّبَّ،", "message": "خلي خدمتك وصلاتك فيها نشاط وأمانة؛ متخليش الفتور يتحكم فيك."}, {"ref": "رو 12:13", "verse": "مُشْتَرِكِينَ فِي احْتِيَاجَاتِ الْقِدِّيسِينَ، عَاكِفِينَ عَلَى إِضَافَةِ الْغُرَبَاءِ.", "message": "افتح قلبك وبيتك للمحتاج والغريب على قد استطاعتك."}, {"ref": "رو 12:16", "verse": "مُهْتَمِّينَ بَعْضُكُمْ لِبَعْضٍ اهْتِمَامًا وَاحِدًا، غَيْرَ مُهْتَمِّينَ بِالأُمُورِ الْعَالِيَةِ بَلْ مُنْقَادِينَ إِلَى الْمُتَّضِعِينَ. لَا تَكُونُوا حُكَمَاءَ عِنْدَ أَنْفُسِكُمْ.", "message": "قرّب من الناس من غير تعالٍ، واتعلم تسمع رأي غيرك."}, {"ref": "رو 12:19", "verse": "لَا تَنْتَقِمُوا لأَنْفُسِكُمْ أَيُّهَا الأَحِبَّاءُ، بَلْ أَعْطُوا مَكَانًا لِلْغَضَبِ، لأَنَّهُ مَكْتُوبٌ: «لِيَ النَّقْمَةُ أَنَا أُجَازِي يَقُولُ الرَّبُّ.", "message": "متخليش الانتقام ياكل قلبك؛ سلّم حقك لربنا واسعَ للسلام."}, {"ref": "أم 11:1", "verse": "مَوَازِينُ غِشٍّ مَكْرَهَةُ الرَّبِّ، وَالْوَزْنُ الصَّحِيحُ رِضَاهُ.", "message": "في البيع والشغل والمذاكرة، خليك أمين حتى لو الغش أسهل؛ ربنا يفرح بالحق."}, {"ref": "أم 11:2", "verse": "تَأْتِي الْكِبْرِيَاءُ فَيَأْتِي الْهَوَانُ، وَمَعَ الْمُتَوَاضِعِينَ حِكْمَةٌ.", "message": "لما تنجح، متتعالش على غيرك؛ التواضع يخليك تفضل تتعلم."}, {"ref": "أم 11:3", "verse": "اِسْتِقَامَةُ الْمُسْتَقِيمِينَ تَهْدِيهِمْ، وَاعْوِجَاجُ الْغَادِرِينَ يُخْرِبُهُمْ.", "message": "خليك واضح وصادق في قراراتك؛ اللف والدوران بيكلف القلب كتير."}, {"ref": "أم 11:5", "verse": "بِرُّ الْكَامِلِ يُقَوِّمُ طَرِيقَهُ، أَمَّا الشِّرِّيرُ فَيَسْقُطُ بِشَرِّهِ.", "message": "متستهونش بالاختيارات الصغيرة؛ الاستقامة بتحدد اتجاه حياتك."}, {"ref": "أم 11:6", "verse": "بِرُّ الْمُسْتَقِيمِينَ يُنَجِّيهِمْ، أَمَّا الْغَادِرُونَ فَيُؤْخَذُونَ بِفَسَادِهِمْ.", "message": "اختار الأمانة حتى لو طريقها أصعب، ومتخليش المصلحة تجرّك للغدر."}, {"ref": "أم 11:9", "verse": "بِالْفَمِ يُخْرِبُ الْمُنَافِقُ صَاحِبَهُ، وَبِالْمَعْرِفَةِ يَنْجُو الصِّدِّيقُونَ.", "message": "متنقلش كلام يهدّ علاقة أو يوجع حد؛ خلي لسانك وسيلة خير."}, {"ref": "أم 11:11", "verse": "بِبَرَكَةِ الْمُسْتَقِيمِينَ تَعْلُو الْمَدِينَةُ، وَبِفَمِ الأَشْرَارِ تُهْدَمُ.", "message": "حياتك الأمينة ممكن تفيد ناس كتير حواليك؛ خليك سبب بنيان مش هدم."}, {"ref": "أم 11:12", "verse": "اَلْمُحْتَقِرُ صَاحِبَهُ هُوَ نَاقِصُ الْفَهْمِ، أَمَّا ذُو الْفَهْمِ فَيَسْكُتُ.", "message": "متسخرش من حد عشان مختلف عنك؛ ساعات السكوت أرقى من الرد."}, {"ref": "أم 11:13", "verse": "السَّاعِي بِالْوِشَايَةِ يُفْشِي السِّرَّ، وَالأَمِينُ الرُّوحِ يَكْتُمُ الأَمْرَ.", "message": "لما حد يأتمنك على كلامه، احفظ سره ومتخليش الفضول يغلب الأمانة."}, {"ref": "أم 11:14", "verse": "حَيْثُ لَا تَدْبِيرٌ يَسْقُطُ الشَّعْبُ، أَمَّا الْخَلاَصُ فَبِكَثْرَةِ الْمُشِيرِينَ.", "message": "قبل قرار كبير، صلّي واسمع نصيحة ناس حكماء؛ مش لازم تعرف كل حاجة لوحدك."}, {"ref": "أم 11:17", "verse": "اَلرَّجُلُ الرَّحِيمُ يُحْسِنُ إِلَى نَفْسِهِ، وَالْقَاسِي يُكَدِّرُ لَحْمَهُ.", "message": "الرحمة مش ضعف؛ ابعد عن القسوة وخلي معاملتك فيها رأفة."}, {"ref": "أم 11:18", "verse": "اَلشِّرِّيرُ يَكْسَبُ أُجْرَةَ غِشٍّ، وَالزَّارِعُ الْبِرَّ أُجْرَةَ أَمَانَةٍ.", "message": "متقيسش النجاح بمكسب سريع؛ ازرع خيرًا بضمير مرتاح."}, {"ref": "أم 11:19", "verse": "كَمَا أَنَّ الْبِرَّ يَؤُولُ إِلَى الْحَيَاةِ كَذَلِكَ مَنْ يَتْبَعُ الشَّرَّ فَإِلَى مَوْتِهِ.", "message": "المسار اللي بتختاره كل يوم ليه نهاية؛ اختار طريق البر واثبت فيه."}, {"ref": "أم 11:20", "verse": "كَرَاهَةُ الرَّبِّ مُلْتَوُو الْقَلْبِ، وَرِضَاهُ مُسْتَقِيمُو الطَّرِيقِ.", "message": "اطلب من ربنا قلب مستقيم من جوه؛ المظاهر وحدها مش كفاية."}, {"ref": "أم 11:23", "verse": "شَهْوَةُ الأَبْرَارِ خَيْرٌ فَقَطْ. رَجَاءُ الأَشْرَارِ سَخَطٌ.", "message": "راجع رغباتك: هل بتطلب خير حقيقي ولا مجرد انتصار لنفسك؟"}, {"ref": "أم 11:24", "verse": "يُوجَدُ مَنْ يُفَرِّقُ فَيَزْدَادُ أَيْضًا، وَمَنْ يُمْسِكُ أَكْثَرَ مِنَ اللاَّئِقِ وَإِنَّمَا إِلَى الْفَقْرِ.", "message": "متخليش الخوف من النقص يقفل إيدك؛ تعلّم العطاء بحكمة ومحبة."}, {"ref": "أم 11:25", "verse": "النَّفْسُ السَّخِيَّةُ تُسَمَّنُ، وَالْمُرْوِي هُوَ أَيْضًا يُرْوَى.", "message": "لما تساعد شخص محتاج بصدق، انت كمان بتتعلّم محبة أوسع."}, {"ref": "أم 11:27", "verse": "مَنْ يَطْلُبُ الْخَيْرَ يَلْتَمِسُ الرِّضَا، وَمَنْ يَطْلُبُ الشَّرَّ فَالشَّرُّ يَأْتِيهِ.", "message": "دوّر على فرصة تعمل خير بدل انتظار حد يشجعك عليه."}, {"ref": "أم 11:28", "verse": "مَنْ يَتَّكِلُ عَلَى غِنَاهُ يَسْقُطُ، أَمَّا الصِّدِّيقُونَ فَكَالْوَرَقِ يَزْهُونَ.", "message": "خلي أمانك في ربنا، مش في فلوس أو مكانة ممكن تتغير."}, {"ref": "أم 11:29", "verse": "مَنْ يُكَدِّرُ بَيْتَهُ يَرِثِ الرِّيحَ، وَالأَحْمَقُ خَادِمٌ لِحَكِيمِ الْقَلْبِ.", "message": "متخليش غضبك يصعب الحياة على أهل بيتك؛ ابدأ أنت بالهدوء."}, {"ref": "أم 12:1", "verse": "مَنْ يُحِبُّ التَّأْدِيبَ يُحِبُّ الْمَعْرِفَةَ، وَمَنْ يُبْغِضُ التَّوْبِيخَ فَهُوَ بَلِيدٌ.", "message": "النصيحة مش إهانة؛ اسمع وراجع نفسك قبل ما ترفض الكلام."}, {"ref": "أم 12:2", "verse": "الصَّالِحُ يَنَالُ رِضًى مِنْ قِبَلِ الرَّبِّ، أَمَّا رَجُلُ الْمَكَايِدِ فَيَحْكُمُ عَلَيْهِ.", "message": "خلي قصدك نقي، وابتعد عن التخطيط لإيذاء غيرك."}, {"ref": "أم 12:3", "verse": "لَا يُثَبَّتُ الإِنْسَانُ بِالشَّرِّ، أَمَّا أَصْلُ الصِّدِّيقِينَ فَلَا يَتَقَلْقَلُ.", "message": "متبنيش مستقبلك على ظلم؛ الثبات يبدأ بالصدق والبر."}, {"ref": "أم 12:5", "verse": "أَفْكَارُ الصِّدِّيقِينَ عَدْلٌ. تَدَابِيرُ الأَشْرَارِ غِشٌّ.", "message": "العدل يبدأ من أفكارك قبل تصرفاتك؛ متظلمش حد في حكمك عليه."}, {"ref": "أم 12:8", "verse": "بِحَسَبِ فِطْنَتِهِ يُحْمَدُ الإِنْسَانُ، أَمَّا الْمُلْتَوِي الْقَلْبِ فَيَكُونُ لِلْهَوَانِ.", "message": "اطلب الفهم من ربنا وخليك مستقيم في تعاملاتك."}, {"ref": "أم 12:10", "verse": "الصِّدِّيقُ يُرَاعِي نَفْسَ بَهِيمَتِهِ، أَمَّا مَرَاحِمُ الأَشْرَارِ فَقَاسِيَةٌ.", "message": "خلي رحمتك تظهر حتى مع المخلوقات الضعيفة اللي محدش بيدافع عنها."}, {"ref": "أم 12:11", "verse": "مَنْ يَشْتَغِلُ بِحَقْلِهِ يَشْبَعُ خُبْزًا، أَمَّا تَابِعُ الْبَطَّالِينَ فَهُوَ عَدِيمُ الْفَهْمِ.", "message": "الشغل الأمين خطوة خطوة أفضل من الجري وراء وعود سهلة وفارغة."}, {"ref": "أم 12:13", "verse": "فِي مَعْصِيَةِ الشَّفَتَيْنِ شَرَكُ الشِّرِّيرِ، أَمَّا الصِّدِّيقُ فَيَخْرُجُ مِنَ الضِّيقِ.", "message": "كلمة متسرعة ممكن تورطك؛ اطلب من ربنا حكمة قبل ما تتكلم."}, {"ref": "أم 12:14", "verse": "الإِنْسَانُ يَشْبَعُ خَيْرًا مِنْ ثَمَرِ فَمِهِ، وَمُكَافَأَةُ يَدَيِ الإِنْسَانِ تُرَدُّ لَهُ.", "message": "كلامك وشغلك ليهم ثمر؛ خلّي الاتنين مصدر خير للناس."}, {"ref": "أم 12:15", "verse": "طَرِيقُ الْجَاهِلِ مُسْتَقِيمٌ فِي عَيْنَيْهِ، أَمَّا سَامِعُ الْمَشُورَةِ فَهُوَ حَكِيمٌ.", "message": "مش كل مرة تكون شايف صح؛ اتعلّم تسمع الرأي اللي يصحّح طريقك."}, {"ref": "أم 12:16", "verse": "غَضَبُ الْجَاهِلِ يُعْرَفُ فِي يَوْمِهِ، أَمَّا سَاتِرُ الْهَوَانِ فَهُوَ ذَكِيٌّ.", "message": "مش كل استفزاز لازم ترد عليه؛ الهدوء ساعات يكون أقوى رد."}, {"ref": "أم 12:17", "verse": "مَنْ يَتَفَوَّهْ بِالْحَقِّ يُظْهِرِ الْعَدْلَ، وَالشَّاهِدُ الْكَاذِبُ يُظْهِرُ غِشًّا.", "message": "لو شهادتك هتأثر في حق حد، قل الحقيقة من غير مجاملة."}, {"ref": "أم 12:18", "verse": "يُوجَدُ مَنْ يَهْذُرُ مِثْلَ طَعْنِ السَّيْفِ، أَمَّا لِسَانُ الْحُكَمَاءِ فَشِفَاءٌ.", "message": "قبل ما ترد على حد موجوع، اختار كلام يداوي بدل ما يجرح."}, {"ref": "أم 12:19", "verse": "شَفَةُ الصِّدْقِ تَثْبُتُ إِلَى الأَبَدِ، وَلِسَانُ الْكَذِبِ إِنَّمَا هُوَ إِلَى طَرْفَةِ الْعَيْنِ.", "message": "الكذبة ممكن تنقذك لحظة، لكن الصدق يبني ثقة تدوم."}, {"ref": "أم 12:23", "verse": "اَلرَّجُلُ الذَّكِيُّ يَسْتُرُ الْمَعْرِفَةَ، وَقَلْبُ الْجَاهِلِ يُنَادِي بِالْحَمَقِ.", "message": "مش لازم تثبت في كل نقاش إنك تعرف أكتر؛ خليك حكيمًا في الكلام."}, {"ref": "أم 12:24", "verse": "يَدُ الْمُجْتَهِدِينَ تَسُودُ، أَمَّا الرَّخْوَةُ فَتَكُونُ تَحْتَ الْجِزْيَةِ.", "message": "خليك أمين في مسؤولياتك حتى في الأيام اللي مفيهاش حماس."}, {"ref": "أم 12:25", "verse": "الْغَمُّ فِي قَلْبِ الرَّجُلِ يُحْنِيهِ، وَالْكَلِمَةُ الطَّيِّبَةُ تُفَرِّحُهُ.", "message": "يمكن كلمة تشجيع منك تغير يوم شخص متعب؛ متبخلش بيها."}, {"ref": "أم 12:26", "verse": "الصِّدِّيقُ يَهْدِي صَاحِبَهُ، أَمَّا طَرِيقُ الأَشْرَارِ فَتُضِلُّهُمْ.", "message": "الصاحب الحقيقي يقربك للخير ويعينك تختار الصح."}, {"ref": "أم 12:28", "verse": "فِي سَبِيلِ الْبِرِّ حَيَاةٌ، وَفِي طَرِيقِ مَسْلِكِهِ لَا مَوْتَ.", "message": "خليك ثابت في طريق الوصية، حتى لو محتاج صبر ومجاهدة."}, {"ref": "أم 13:1", "verse": "اَلابْنُ الْحَكِيمُ يَقْبَلُ تَأْدِيبَ أَبِيهِ، وَالْمُسْتَهْزِئُ لَا يَسْمَعُ انْتِهَارًا.", "message": "اسمع توجيه أهلك بمحبة، حتى لو مش موافق من أول لحظة."}, {"ref": "أم 13:2", "verse": "مِنْ ثَمَرَةِ فَمِهِ يَأْكُلُ الإِنْسَانُ خَيْرًا، وَمَرَامُ الْغَادِرِينَ ظُلْمٌ.", "message": "خلّي كلامك مستقيم ومفيد؛ اللي بتقوله مش بيختفي من غير أثر."}, {"ref": "أم 13:3", "verse": "مَنْ يَحْفَظُ فَمَهُ يَحْفَظُ نَفْسَهُ. مَنْ يَشْحَرْ شَفَتَيْهِ فَلَهُ هَلاَكٌ.", "message": "متتكلمش في كل حاجة وكل وقت؛ فكّر قبل ما ترد."}, {"ref": "أم 13:4", "verse": "نَفْسُ الْكَسْلاَنِ تَشْتَهِي وَلَا شَيْءَ لَهَا، وَنَفْسُ الْمُجْتَهِدِينَ تَسْمَنُ.", "message": "الأماني من غير تعب مش كفاية؛ ابدأ خطوة جدية النهارده."}, {"ref": "أم 13:5", "verse": "اَلصِّدِّيقُ يُبْغِضُ كَلاَمَ كَذِبٍ، وَالشِّرِّيرُ يُخْزِي وَيُخْجِلُ.", "message": "حتى لو الكذبة هتخليك مقبول، متتنازلش عن الحق."}, {"ref": "أم 13:6", "verse": "اَلْبِرُّ يَحْفَظُ الْكَامِلَ طَرِيقَهُ، وَالشَّرُّ يَقْلِبُ الْخَاطِئَ.", "message": "امشِ باستقامة في الخفاء قبل العلن؛ البر يسند خطواتك."}, {"ref": "أم 13:9", "verse": "نُورُ الصِّدِّيقِينَ يُفَرِّحُ، وَسِرَاجُ الأَشْرَارِ يَنْطَفِئُ.", "message": "خلي وجودك يفرّح اللي حواليك بالصدق واللطف."}, {"ref": "أم 13:10", "verse": "اَلْخِصَامُ إِنَّمَا يَصِيرُ بِالْكِبْرِيَاءِ، وَمَعَ الْمُتَشَاوِرِينَ حِكْمَةٌ.", "message": "لو النقاش اتحول لخناقة، جرّب تسمع بدل ما تتمسك بكبريائك."}, {"ref": "أم 13:11", "verse": "غِنَى الْبُطْلِ يَقِلُّ، وَالْجَامِعُ بِيَدِهِ يَزْدَادُ.", "message": "خلي نجاحك مبني على شغل شريف وصبر، مش طرق مختصرة مشبوهة."}, {"ref": "أم 13:12", "verse": "الرَّجَاءُ الْمُمَاطَلُ يُمْرِضُ الْقَلْبَ، وَالشَّهْوَةُ الْمُتَمَّمَةُ شَجَرَةُ حَيَاةٍ.", "message": "لو أمنية اتأخرت، احكي تعبك لربنا واطلب منه صبر وحكمة."}, {"ref": "أم 13:13", "verse": "مَنِ ازْدَرَى بِالْكَلِمَةِ يُخْرِبُ نَفْسَهُ، وَمَنْ خَشِيَ الْوَصِيَّةَ يُكَافَأُ.", "message": "اقرأ وصية ربنا باهتمام، وخليها تغير اختياراتك مش مجرد معلومات."}, {"ref": "أم 13:14", "verse": "شَرِيعَةُ الْحَكِيمِ يَنْبُوعُ حَيَاةٍ لِلْحَيَدَانِ عَنْ أَشْرَاكِ الْمَوْتِ.", "message": "المشورة الصالحة تحميك من طرق مؤذية؛ ما تستقلش بالنصيحة."}, {"ref": "أم 13:15", "verse": "اَلْفِطْنَةُ الْجَيِّدَةُ تَمْنَحُ نِعْمَةً، أَمَّا طَرِيقُ الْغَادِرِينَ فَأَوْعَرُ.", "message": "الغش ممكن يبدو سهل في البداية، لكن الأمانة أسلم للقلب."}, {"ref": "أم 13:16", "verse": "كُلُّ ذَكِيٍّ يَعْمَلُ بِالْمَعْرِفَةِ، وَالْجَاهِلُ يَنْشُرُ حُمْقًا.", "message": "ما تاخدش قرار متسرع لمجرد إثبات نفسك؛ افهم الأول وبعدين اتصرف."}, {"ref": "أم 13:17", "verse": "اَلرَّسُولُ الشِّرِّيرُ يَقَعُ فِي الشَّرِّ، وَالسَّفِيرُ الأَمِينُ شِفَاءٌ.", "message": "في أي مسؤولية أو رسالة بتنقلها، خليك أمينًا وموثوقًا."}, {"ref": "أم 13:18", "verse": "فَقْرٌ وَهَوَانٌ لِمَنْ يَرْفُضُ التَّأْدِيبَ، وَمَنْ يُلاَحِظِ التَّوْبِيخَ يُكْرَمْ.", "message": "متعتبرش كل ملاحظة هجومًا؛ ممكن تكون باب لنموك."}, {"ref": "أم 13:20", "verse": "اَلْمُسَايِرُ الْحُكَمَاءَ يَصِيرُ حَكِيمًا، وَرَفِيقُ الْجُهَّالِ يُضَرُّ.", "message": "اختار الصحبة اللي تعلمك خير وتشجعك تقرب من ربنا."}, {"ref": "أم 13:21", "verse": "اَلشَّرُّ يَتْبَعُ الْخَاطِئِينَ، وَالصِّدِّيقُونَ يُجَازَوْنَ خَيْرًا.", "message": "متقارنش نفسك بمكسب مؤقت ناتج عن خطأ؛ اثبت على الخير."}, {"ref": "أم 13:22", "verse": "اَلصَّالِحُ يُورِثُ بَنِي الْبَنِينَ، وَثَرْوَةُ الْخَاطِئِ تُذْخَرُ لِلصِّدِّيقِ.", "message": "فكر في الأثر اللي هتسيبه بعدك، مش في مكسب النهارده بس."}, {"ref": "أم 13:25", "verse": "اَلصِّدِّيقُ يَأْكُلُ لِشَبَعِ نَفْسِهِ، أَمَّا بَطْنُ الأَشْرَارِ فَيَحْتَاجُ.", "message": "اطلب قلب قنوع يشكر ربنا، بدل رغبات ملهاش نهاية."}, {"ref": "أم 14:1", "verse": "حِكْمَةُ الْمَرْأَةِ تَبْنِي بَيْتَهَا، وَالْحَمَاقَةُ تَهْدِمُهُ بِيَدِهَا.", "message": "كل كلمة وقرار ممكن يبني بيتك أو يجرحه؛ اختار الحكمة."}, {"ref": "أم 14:2", "verse": "اَلسَّالِكُ بِاسْتِقَامَتِهِ يَتَّقِي الرَّبَّ، وَالْمُعَوِّجُ طُرُقَهُ يَحْتَقِرُهُ.", "message": "خلّي احترامك لربنا واضح في أمانتك لما محدش يكون شايفك."}, {"ref": "أم 14:3", "verse": "فِي فَمِ الْجَاهِلِ قَضِيبٌ لِكِبْرِيَائِهِ، أَمَّا شِفَاهُ الْحُكَمَاءِ فَتَحْفَظُهُمْ.", "message": "الكلام المتعالي بيوقع صاحبه؛ خليك لطيفًا في ردودك."}, {"ref": "أم 14:5", "verse": "اَلشَّاهِدُ الأَمِينُ لَنْ يَكْذِبَ، وَالشَّاهِدُ الزُّورُ يَتَفَوَّهُ بِالأَكَاذِيبِ.", "message": "متبيعش الحقيقة علشان ترضي حد؛ كن أمينًا في شهادتك."}, {"ref": "أم 14:6", "verse": "اَلْمُسْتَهْزِئُ يَطْلُبُ الْحِكْمَةَ وَلَا يَجِدُهَا، وَالْمَعْرِفَةُ هَيِّنَةٌ لِلْفَهِيمِ.", "message": "ادخل وقت التعلم بقلب متواضع، مش بروح السخرية."}, {"ref": "أم 14:7", "verse": "اِذْهَبْ مِنْ قُدَّامِ رَجُلٍ جَاهِلٍ إِذْ لَا تَشْعُرُ بِشَفَتَيْ مَعْرِفَةٍ.", "message": "مش كل نقاش لازم تكمله؛ ابعد عن الجدال اللي بلا فائدة."}, {"ref": "أم 14:8", "verse": "حِكْمَةُ الذَّكِيِّ فَهْمُ طَرِيقِهِ، وَغَبَاوَةُ الْجُهَّالِ غِشٌّ.", "message": "قبل ما تمشي ورا الناس، افهم طريقك واسأل عن عواقبه."}, {"ref": "أم 14:9", "verse": "اَلْجُهَّالُ يَسْتَهْزِئُونَ بِالإِثْمِ، وَبَيْنَ الْمُسْتَقِيمِينَ رِضًى.", "message": "متتعاملش مع الخطية كأنها هزار؛ خليك جاد في الرجوع لربنا."}, {"ref": "أم 14:10", "verse": "اَلْقَلْبُ يَعْرِفُ مَرَارَةَ نَفْسِهِ، وَبِفَرَحِهِ لَا يُشَارِكُهُ غَرِيبٌ.", "message": "مش كل اللي قدامك ظاهر عليه تعبه؛ عامل الناس برحمة."}, {"ref": "أم 14:11", "verse": "بَيْتُ الأَشْرَارِ يُخْرَبُ، وَخَيْمَةُ الْمُسْتَقِيمِينَ تُزْهِرُ.", "message": "خلي بيتك قائم على الصدق والمحبة مش على الظلم والمظاهر."}, {"ref": "أم 14:12", "verse": "تُوجَدُ طَرِيقٌ تَظْهَرُ لِلإِنْسَانِ مُسْتَقِيمَةً، وَعَاقِبَتُهَا طُرُقُ الْمَوْتِ.", "message": "مش كل حاجة تبدو صح تكون نافعة؛ قارن قراراتك بوصية ربنا."}, {"ref": "أم 14:14", "verse": "اَلْمُرْتَدُّ فِي الْقَلْبِ يَشْبَعُ مِنْ طُرُقِهِ، وَالرَّجُلُ الصَّالِحُ مِمَّا عِنْدَهُ.", "message": "احفظ قلبك من الرجوع للعادات القديمة، واطلب نعمة الثبات."}, {"ref": "أم 14:16", "verse": "اَلْحَكِيمُ يَخْشَى وَيَحِيدُ عَنِ الشَّرِّ، وَالْجَاهِلُ يَتَصَلَّفُ وَيَثِقُ.", "message": "الشجاعة مش إنك تقرب من التجربة؛ الحكمة إنك تبعد عن الشر."}, {"ref": "أم 14:17", "verse": "اَلسَّرِيعُ الْغَضَبِ يَعْمَلُ بِالْحَمَقِ، وَذُو الْمَكَايِدِ يُشْنَأُ.", "message": "قبل ما تتصرف وأنت متضايق، ادي لنفسك فرصة تهدى."}, {"ref": "أم 14:21", "verse": "مَنْ يَحْتَقِرُ قَرِيبَهُ يُخْطِئُ، وَمَنْ يَرْحَمُ الْمَسَاكِينَ فَطُوبَى لَهُ.", "message": "احترم كل إنسان مهما كانت ظروفه، وساعد المحتاج من غير تعالٍ."}, {"ref": "أم 14:22", "verse": "أَمَا يَضِلُّ مُخْتَرِعُو الشَّرِّ؟ أَمَّا الرَّحْمَةُ وَالْحَقُّ فَيَهْدِيَانِ مُخْتَرِعِي الْخَيْرِ.", "message": "خطط لعمل خير بدل التفكير في رد الأذى بأذى."}, {"ref": "أم 14:23", "verse": "فِي كُلِّ تَعَبٍ مَنْفَعَةٌ، وَكَلاَمُ الشَّفَتَيْنِ إِنَّمَا هُوَ إِلَى الْفَقْرِ.", "message": "ما تكتفيش بالكلام عن التغيير؛ ابدأ بمجهود حقيقي."}, {"ref": "أم 14:25", "verse": "اَلشَّاهِدُ الأَمِينُ مُنَجِّي النُّفُوسِ، وَمَنْ يَتَفَوَّهُ بِالأَكَاذِيبِ فَغِشٌّ.", "message": "ممكن شهادتك الصادقة تنقذ مظلوم؛ متستخفش بكلمة الحق."}, {"ref": "أم 14:26", "verse": "فِي مَخَافَةِ الرَّبِّ ثِقَةٌ شَدِيدَةٌ، وَيَكُونُ لِبَنِيهِ مَلْجَأٌ.", "message": "خلي اتكالك على ربنا نابع من مخافته وطاعته."}, {"ref": "أم 14:27", "verse": "مَخَافَةُ الرَّبِّ يَنْبُوعُ حَيَاةٍ لِلْحَيَدَانِ عَنْ أَشْرَاكِ الْمَوْتِ.", "message": "مخافة ربنا تحفظ خطواتك من طرق تهلكك؛ تمسّك بالوصية."}, {"ref": "أم 14:29", "verse": "بَطِيءُ الْغَضَبِ كَثِيرُ الْفَهْمِ، وَقَصِيرُ الرُّوحِ مُعَلِّي الْحَمَقِ.", "message": "ما تستعجلش الرد وانت غضبان؛ التمهّل علامة فهم."}, {"ref": "أم 14:30", "verse": "حَيَاةُ الْجَسَدِ هُدُوءُ الْقَلْبِ، وَنَخْرُ الْعِظَامِ الْحَسَدُ.", "message": "بدل مقارنة حياتك بغيرك، اشكر ربنا على عطاياه."}, {"ref": "أم 14:31", "verse": "ظَالِمُ الْفَقِيرِ يُعَيِّرُ خَالِقَهُ، وَيُمَجِّدُهُ رَاحِمُ الْمِسْكِينِ.", "message": "كرامة المحتاج مش أقل منك؛ لما ترحمه أنت بتمجد ربنا."}, {"ref": "أم 14:33", "verse": "فِي قَلْبِ الْفَهِيمِ تَسْتَقِرُّ الْحِكْمَةُ، وَمَا فِي دَاخِلِ الْجُهَّالِ يُعْرَفُ.", "message": "ما تستعرضش معلوماتك؛ خلي الحكمة تظهر في سلوكك."}, {"ref": "أم 14:34", "verse": "اَلْبِرُّ يَرْفَعُ شَأْنَ الأُمَّةِ، وَعَارُ الشُّعُوبِ الْخَطِيَّةُ.", "message": "خليك صالحًا في بيتك ووسط مجتمعك؛ خيرك له أثر أبعد منك."}, {"ref": "أم 15:2", "verse": "لِسَانُ الْحُكَمَاءِ يُحَسِّنُ الْمَعْرِفَةَ، وَفَمُ الْجُهَّالِ يُنْبِعُ حَمَاقَةً.", "message": "خلي كلامك يفيد اللي يسمعك، مش مجرد كلام كتير."}, {"ref": "أم 15:3", "verse": "فِي كُلِّ مَكَانٍ عَيْنَا الرَّبِّ مُرَاقِبَتَانِ الطَّالِحِينَ وَالصَّالِحِينَ.", "message": "افتكر إن ربنا شايفك حتى في الخفاء؛ خليك مستقيمًا من قلبك."}, {"ref": "أم 15:4", "verse": "هُدُوءُ اللِّسَانِ شَجَرَةُ حَيَاةٍ، وَاعْوِجَاجُهُ سَحْقٌ فِي الرُّوحِ.", "message": "كلمة هادية ممكن تصلح خلاف كبير؛ اختار السلام في ردك."}, {"ref": "أم 15:5", "verse": "اَلأَحْمَقُ يَسْتَهِينُ بِتَأْدِيبِ أَبِيهِ، أَمَّا مُرَاعِي التَّوْبِيخِ فَيَذْكَى.", "message": "مش كل تصحيح ضدك؛ اسمع وتعلّم قبل ما ترفض."}, {"ref": "أم 15:7", "verse": "شِفَاهُ الْحُكَمَاءِ تَذُرُّ مَعْرِفَةً، أَمَّا قَلْبُ الْجُهَّالِ فَلَيْسَ كَذَلِكَ.", "message": "خلّي نصيحتك لغيرك صادقة ومفيدة، ومن غير استعراض."}, {"ref": "أم 15:8", "verse": "ذَبِيحَةُ الأَشْرَارِ مَكْرَهَةُ الرَّبِّ، وَصَلاَةُ الْمُسْتَقِيمِينَ مَرْضَاتُهُ.", "message": "قبل ما تركز على الشكل، اطلب من ربنا قلبًا صادقًا في الصلاة."}, {"ref": "أم 15:9", "verse": "مَكْرَهَةُ الرَّبِّ طَرِيقُ الشِّرِّيرِ، وَتَابِعُ الْبِرِّ يُحِبُّهُ.", "message": "الخير مش موقف عابر؛ خلي السعي للبر أسلوب حياة."}, {"ref": "أم 15:13", "verse": "اَلْقَلْبُ الْفَرْحَانُ يَجْعَلُ الْوَجْهَ طَلِقًا، وَبِحُزْنِ الْقَلْبِ تَنْسَحِقُ الرُّوحُ.", "message": "اطلب من ربنا فرحًا وسلامًا داخليين، وخلّي قلبك صريحًا معاه."}, {"ref": "أم 15:14", "verse": "قَلْبُ الْفَهِيمِ يَطْلُبُ مَعْرِفَةً، وَفَمُ الْجُهَّالِ يَرْعَى حَمَاقَةً.", "message": "خلّي شغفك بالمعرفة النافعة أكبر من تضييع الوقت في الكلام الفارغ."}, {"ref": "أم 15:16", "verse": "اَلْقَلِيلُ مَعَ مَخَافَةِ الرَّبِّ، خَيْرٌ مِنْ كَنْزٍ عَظِيمٍ مَعَ هَمٍّ.", "message": "الغنى مش كل حاجة؛ القليل مع قلب يخاف ربنا أفضل من مال يسرق سلامك."}, {"ref": "أم 15:17", "verse": "أَكْلَةٌ مِنَ الْبُقُولِ حَيْثُ تَكُونُ الْمَحَبَّةُ، خَيْرٌ مِنْ ثَوْرٍ مَعْلُوفٍ وَمَعَهُ بُغْضَةٌ.", "message": "مائدة بسيطة فيها محبة أكرم من وفرة معها خصام."}, {"ref": "أم 15:18", "verse": "اَلرَّجُلُ الْغَضُوبُ يُهَيِّجُ الْخُصُومَةَ، وَبَطِيءُ الْغَضَبِ يُسَكِّنُ الْخِصَامَ.", "message": "لما النقاش يسخن، كن الشخص اللي يهدّي مش اللي يشعل الخلاف."}, {"ref": "أم 15:20", "verse": "اَلابْنُ الْحَكِيمُ يَسُرُّ أَبَاهُ، وَالرَّجُلُ الْجَاهِلُ يَحْتَقِرُ أُمَّهُ.", "message": "احترام أهلك يظهر في أفعالك قبل كلامك، حتى وقت الاختلاف."}, {"ref": "أم 15:21", "verse": "الْحَمَاقَةُ فَرَحٌ لِنَاقِصِ الْفَهْمِ، أَمَّا ذُو الْفَهْمِ فَيُقَوِّمُ سُلُوكَهُ.", "message": "مش كل حاجة تضحك الناس تكون صح؛ خليك واعي بتصرفاتك."}, {"ref": "أم 15:22", "verse": "مَقَاصِدُ بِغَيْرِ مَشُورَةٍ تَبْطُلُ، وَبِكَثْرَةِ الْمُشِيرِينَ تَقُومُ.", "message": "قبل قرار مصيري، صلّي وخد مشورة صادقة من ناس موثوقين."}, {"ref": "أم 15:23", "verse": "لِلإِنْسَانِ فَرَحٌ بِجَوَابِ فَمِهِ، وَالْكَلِمَةُ فِي وَقْتِهَا مَا أَحْسَنَهَا!", "message": "قول الكلمة الطيبة في وقتها؛ يمكن تكون بالضبط اللي حد محتاج يسمعه."}], "prayers": [{"title": "صلاة يهوشافاط", "ref": "( 2 أخبار 20 : 6 – 12 )", "text": "«يا رب إله آبائنا، أما أنت هو الله في السماء، وأنت المتسلط على جميع ممالك الأمم، وبيدك قوة وجبروت وليس من يقف معك؟ ألست أنت إلهنا الذي طردت سكان هذه الأرض من أمام شعبك إسرائيل وأعطيتها لنسل إبراهيم خليلك إلى الأبد؟ فسكنوا فيها وبنوا لك فيها مقدسا لاسمك قائلين: إذا جاء علينا شر، سيف قضاء أو وبأ أو جوع، ووقفنا أمام هذا البيت وأمامك، لأن اسمك في هذا البيت، وصرخنا إليك من ضيقنا فإنك تسمع وتخلص. والآن هوذا بنو عمون وموآب وجبل ساعير، الذين لم تدع إسرائيل يدخلون إليهم حين جاءوا من أرض مصر، بل مالوا عنهم ولم يهلكوهم، فهوذا هم يكافئوننا بمجيئهم لطردنا من ملكك الذي ملكتنا إياه. يا إلهنا أما تقضي عليهم، لأنه ليس فينا قوة أمام هذا الجمهور الكثير الآتي علينا، ونحن لا نعلم ماذا نعمل ولكن نحوك أعيننا»"}, {"title": "صلاة مردخاي", "ref": "( تتمة أستير 13 : 8 – 17 )", "text": "«اللهم أيها الرب الملك القادر على الكل، إذ كل شيء في طاعتك وليس من يقاوم مشيئتك إذا هممت بنجاة إسرائيل. أنت صنعت السماء والأرض وكل ما تحت السموات، أنت رب الجميع وليس من يقاوم عزتك. إنك تعرف كل شيء، وتعلم أني لا تكبرا ولا احتقارا ولا رغبة في شيء من الكرامة فعلت هذا: أني لم أسجد لهامان العاتي، فإني مستعد أن أقبل حتى آثار قدميه عن طيب نفس لأجل نجاة إسرائيل، ولكن خفت أن أحول كرامة إلهي إلى إنسان، وأعبد أحدا سوى إلهي. فالآن أيها الرب الملك، إله إبراهيم، ارحم شعبك، لأن أعداءنا يطلبون أن يهلكونا، ويستأصلوا ميراثك، لا تهمل نصيبك الذي افتديته لك من مصر. واستجب لتضرعي واعطف على نصيبك وميراثك وحول حزننا فرحا لنحيا ونسبح اسمك أيها الرب، ولا تسدد أفواه المرنمين لك»"}, {"title": "صلاة حزقيال أبان حصار سنحاريب", "ref": "( 2مل 19 : 15 – 19 ، أش 37 : 15 – 20 )", "text": "وصلى حزقيا أمام الرب وقال: «أيها الرب إله إسرائيل، الجالس فوق الكروبيم، أنت هو الإله وحدك لكل ممالك الأرض. أنت صنعت السماء والأرض.  أمل يا رب أذنك واسمع. افتح يا رب عينيك وانظر، واسمع كلام سنحاريب الذي أرسله ليعير الله الحي.  حقا يا رب إن ملوك أشور قد خربوا الأمم وأراضيهم،  ودفعوا آلهتهم إلى النار. ولأنهم ليسوا آلهة، بل صنعة أيدي الناس: خشب وحجر، فأبادوهم.  والآن أيها الرب إلهنا خلصنا من يده، فتعلم ممالك الأرض كلها أنك أنت الرب الإله وحدك»."}, {"title": "صلاة سليمان الحكيم", "ref": "( الحكمة 9 : 1 - 19 )", "text": "يا إله الآباء، يا رب الرحمة، يا صانع الجميع بكلمتك،  وفاطر الإنسان بحكمتك، لكي يسود على الخلائق التي كونتها،  ويسوس العالم بالقداسة والبر، ويجري الحكم باستقامة النفس.  هب لي الحكمة الجالسة إلى عرشك، ولا ترذلني من بين بنيك،  فإني أنا عبدك وابن أمتك، إنسان ضعيف قليل البقاء، وناقص الفهم في القضاء والشرائع.  على أنه إن كان في بني البشر أحد كامل؛ فما لم تكن معه الحكمة التي منك، لا يحسب شيئا.  إنك قد اخترتني لشعبك ملكا، ولبنيك وبناتك قاضيا،  وأمرتني أن أبني هيكلا في جبل قدسك، ومذبحا في مدينة سكناك على مثال المسكن المقدس الذي هيأته منذ البدء.   إن معك الحكمة العليمة بأعمالك، والتي كانت حاضرة إذ صنعت العالم، وهي عارفة ما المرضي في عينيك، والمستقيم في وصاياك،  فأرسلها من السموات المقدسة، وابعثها من عرش مجدك، حتى إذا حضرت تجد معي، وأعلم ما المرضي لديك.  فإنها تعلم وتفهم كل شيء؛ فتكون لي في أفعالي مرشدا فطينا، وبعزها تحفظني،  فتغدو أعمالي مقبولة، وأحكم لشعبك بالعدل، وأكون أهلا لعرش أبي.  فأي إنسان يعلم مشورة الله، أو يفطن لما يريد الرب؟  إن أفكار البشر ذات إحجام، وبصائرنا غير راسخة،  إذ الجسد الفاسد يثقل النفس، والمسكن الأرضي يخفض العقل الكثير الهموم.  ونحن بالجهد نتمثل ما على الأرض، وبالكد ندرك ما بين أيدينا، فما في السموات من اطلع عليه؟  ومن علم مشورتك لو لم تؤت الحكمة، وتبعث روحك القدوس من الأعالي؟  فإنه كذلك قومت سبل الذين على الأرض، وتعلم الناس مرضاتك،  والحكمة هي التي خلصت كل من أرضاك، يا رب، منذ البدء."}, {"title": "صلاة يشوع", "ref": "( سيراخ  51 : 13 – 30 )", "text": "فرفعت من الأرض صلاتي، وتضرعت لأنقذ من الموت.  دعوت الرب أبا ربي، لئلا يخذلني في أيام الضيق، في عهد المتكبرين الخاذلين لي.  إني أسبح اسمك في كل حين، وأرنم له بالاعتراف، لأن صلاتي قد استجيبت.  فإنك قد خلصتني من الهلكة، وأنقذتني من زمان السوء.  فلذلك أعترف لك وأسبحك، وأبارك اسم الرب.  في صبائي قبل أن أتيه، التمست الحكمة علانية في صلاتي.  أمام الهيكل ابتهلت لأجلها، وإلى أواخري ألتمسها. فأزهرت كباكورة العنب.  ابتهج بها قلبي، ودرجت قدمي في الاستقامة، ومنذ صبائي جددت في إثرها.  أملت أذني قليلا ووعيت،  فوجدت لنفسي تأديبا كثيرا، وكان لي فيها نجح عظيم.  إن الذي أتاني حكمة، أوتيه تمجيدا،  فإني عزمت أن أعمل بها، وقد حرصت على الخير، ولست أخزى.  جاهدت نفسي لأجلها، وفي أعمالي لم أبرح متنطسا.  مددت يدي إلى العلاء، وبكيت على جهالاتي.  وجهت نفسي إليها، وبالطهارة وجدتها.  بها ملكت قلبي من البدء؛ فلذلك لا أخذل.  وجوفي اضطرب في طلبها؛ فلذلك اقتنيت قنية صالحة.  أعطاني الرب اللسان جزاء؛ فبه أسبحه."}, {"title": "صلاة آسا الملك", "ref": "( 2 اخبار 14  : 11 - 12 )", "text": "ودعا آسا الرب إلهه وقال: «أيها الرب، ليس فرقا عندك أن تساعد الكثيرين ومن ليس لهم قوة. فساعدنا أيها الرب إلهنا لأننا عليك اتكلنا وباسمك قدمنا على هذا الجيش. أيها الرب أنت إلهنا. لا يقو عليك إنسان»"}, {"title": "صلاة يهوديت", "ref": "( يهوديت 9 : 2 - 19 )", "text": "«أيها الرب إله أبي شمعون الذي أعطاه سيفا لينتقم من الغرباء الذين بنجاستهم فضحوا وكشفوا عذراء للخزي  فجعلت نساءهم غنيمة وبناتهم سبيا وكل سلبهم مقتسما بين عبيدك الذين غاروا غيرتك، أتوسل إليك أيها الرب إلهي أن تعينني أنا الأرملة.  فإن لك الأفعال الأولى وأنت قدرت بعضها في عقب بعض وما أردته كان،  فإن طرائقك جميعها مهيأة، وقد أقمت أحكامك بعنايتك.  فانظر الآن إلى معسكر الأشوريين كما تنازلت فنظرت إلى معسكر المصريين حين كانوا يسعون في إثر عبيدك بسلاحهم متوكلين على مراكبهم وفرسانهم وعلى كثرة رجال حربهم،  حينئذ نظرت إلى معسكرهم فزعجتهم الظلمة،  التزقت أقدامهم بالعمق وغطتهم المياه.  يا رب فليكن مثلهم هؤلاء المتوكلون على كثرة عددهم ومراكبهم وحرابهم وتروسهم وسهامهم، المفتخرون برماحهم،  وهم لا يعلمون أنك أنت إلهنا الذي يمحق الحروب منذ البدء وأن اسمك الرب.  فارفع ذراعك كما فعلت من البدء، واحطم قوتهم بقوتك، ولتسقط بغضبك قوة الذين يطمعون أنفسهم في ابتذال أقداسك وتنجيس مسكن اسمك وهدم قرن مذبحك بسيفهم.  اجعل، يا رب، كبرياءه تقطع بنفس سيفه،  ليصد بفخ نظره إلي واضربه بعذوبة الكلام الخارج من شفتي،  وهبني ثباتا في قلبي حتى أزدريه وقوة حتى أهلكه،  فيكون هذا ذكرا لاسمك إذا أهلكته يد امرأة،  لأنها ليست قوتك بالكثرة يا رب ولا مرضاتك بقدرة الخيل، ومنذ البدء لا ترضى من المتكبرين، بل يسرك دائما تضرع المتواضعين الودعاء.  يا إله السموات خالق المياه ورب كل خليقة، استجبني أنا المسكينة المتضرعة والمتوكلة على رحمتك،  واذكر يا رب ميثاقك، واجعل الكلام في في، وثبت مشورة قلبي ليثبت بيتك في قدسك،  فيعرف جميع الأمم أنك أنت الإله وليس آخر سواك»."}, {"title": "صلاة استير", "ref": "( تتمة استير  14 : 3 - 19 )", "text": "وكانت تتضرع إلى الرب إله إسرائيل قائلة: «أيها الرب، الذي هو وحده ملكنا، أعني أنا المنقطعة التي ليس لها معين سواك. فإن خطري بين يدي. لقد سمعت من أبي أنك أيها الرب اتخذت إسرائيل من جميع الأمم وآباءنا من جميع أسلافهم الأقدمين لتحوزهم ميراثا أبديا، وصنعت معهم كما قلت، إنا قد خطئنا أمامك ولذلك أسلمتنا إلى أيدي أعدائنا. لأنا عبدنا آلهتهم، وأنت عادل أيها الرب. والآن لم يكفهم أنهم استعبدونا عبودية شاقة جدا، بل بما أنهم يعزون قوة أيديهم إلى أوثانهم. يحاولون أن ينقضوا مواعيدك ويمحوا ميراثك، ويسدوا أفواه المسبحين لك، ويطفئوا مجد هيكلك ومذبحك. ليفتحوا أفواه الأمم فيسبحوا لقوة الأوثان ويمجدوا ملكا بشريا إلى الأبد. لا تسلم أيها الرب صولجانك إلى من ليسوا بشيء، لئلا يضحكوا من هلاكنا، ولكن اردد مشورتهم عليهم وأهلك الذي ابتدأ يشدد علينا. اذكرنا يا رب. واستعلن لنا في\n\nوقت ضنكنا، وهبني ثقة، أيها الرب ملك الآلهة، وملك كل قدرة، ألق في فمي كلاما مرصفا بحضرة ذاك الأسد وحول قلبه إلى بغض عدونا لكي يهلك هو وسائر المتواطئين معه. وإيانا فأنقذنا بيدك وأعني أنا التي لا معونة لها سواك أيها الرب العالم بكل شيء. إنك تعلم أني أبغض مجد الظالمين وأكره مضجع القلف وجميع الغرباء. وأنت عالم بضرورتي، وأني أكره سمة أبهتي ومجدي التي أحملها على رأسي أيام بروزي، وأمقتها كفرصة الطامث ولا أحملها في أيام قراري، وأني لم آكل على مائدة هامان ولا لذذت بوليمة الملك ولم أشرب خمر السكب، ولم أفرح أنا أمتك، منذ نقلت إلى ههنا إلى اليوم إلا بك أيها الرب إله إبراهيم. الإله القدير على الجميع فاستجب لأصوات الذين ليس لهم رجاء غيرك، ونجنا من أيدي الأثماء، وأنقذني من مخافتي»."}, {"title": "صلاة يشوع", "ref": "( سيراخ  36 : 1 - 18 )", "text": "أيها الرب إله الجميع، ارحمنا وانظر إلينا وأرنا نور مراحمك.  ألق رعبك على جميع الأمم الذين لم يلتمسوك، ليعلموا أنه لا إله إلا أنت ويخبروا بعظائمك.  رفع يدك على الأمم الغريبة، وليعرفوا عزتك. كما قد ظهرت فينا قداستك أمامهم، هكذا فلتظهر عظمتك فيهم أمامنا.  ليعرفوك كما عرفنا نحن: أن لا إله إلا أنت يا رب.  ستأنف الآيات، وأحدث العجائب.  مجد يدك، وذراعك اليمنى. أثر غضبك، وصب سخطك. دمر المقاوم، واحطم العدو. عجل الزمان، واذكر الميثاق، وليخبر بعظائمك. لتأكل نار الغضب الناجي، وليلق مضايقو شعبك الهلاك. اهشم رؤوس قادة الأعداء القائلين: «ليس غيرنا». اجمع كل أسباط يعقوب، واتخذها ميراثا لك، كما كانت في البدء. أيها الرب، ارحم الشعب الذي دعي باسمك، وإسرائيل الذي أنزلته منزلة بكرك. أشفق على مدينة قدسك أورشليم، مدينة راحتك. املأ صهيون لكي تنادي بأقوالك. املأ شعبك من مجدك. اشهد للذين هم خلقك منذ البدء، وأيقظ النبوءات التي باسمك. أعط الذين ينتظرونك الثواب، وليتبين صدق أنبيائك. استجب، أيها الرب، لصلاة المتضرعين إليك ."}, {"title": "صلاة الكنيسة الأولي", "ref": "( أع  4 : 24 - 30 )", "text": "فلما سمعوا، رفعوا بنفس واحدة صوتا إلى الله وقالوا: «أيها السيد، أنت هو الإله الصانع السماء والأرض والبحر وكل ما فيها، القائل بفم داود فتاك: لماذا ارتجت الأمم وتفكر الشعوب بالباطل؟  قامت ملوك الأرض، واجتمع الرؤساء معا على الرب وعلى مسيحه.  لأنه بالحقيقة اجتمع على فتاك القدوس يسوع، الذي مسحته، هيرودس وبيلاطس البنطي مع أمم وشعوب إسرائيل،  ليفعلوا كل ما سبقت فعينت يدك ومشورتك أن يكون.  والآن يا رب، انظر إلى تهديداتهم، وامنح عبيدك أن يتكلموا بكلامك بكل مجاهرة،  بمد يدك للشفاء، ولتجر آيات وعجائب باسم فتاك القدوس يسوع»."}, {"title": "صلاة يشوع بن سيراخ", "ref": "( سيراخ  23 : 1 - 6 )", "text": "أَيُّهَا الرَّبُّ الأَبُ، يَا سَيِّدَ حَيَاتِي، لاَ تَتْرُكْنِي وَمَشُورَةَ شَفَتَيَّ، وَلاَ تَدَعْنِي أَسْقُطُ بِهِمَا.  مَنْ يَأْخُذُ أَفْكَارِي بِالسِّيَاطِ وَقَلْبِي بِتَأْدِيبِ الْحِكْمَةِ، بِحَيْثُ لاَ يُشْفَقُ عَلَى جَهَالاَتِي، وَلاَ تُهْمَلُ خَطَايَايَ.  لِكَيْ لاَ تَتَكَاثَرَ جَهَالاَتِي وَتَتَوَافَرَ خَطَايَايَ؛ فَأَسْقُطَ تُجَاهَ أَضْدَادِي وَيَشْمَتَ عَدُوِّي بِي.  أَيُّهَا الرَّبُّ الأَبُ، يَا إِلهَ حَيَاتِي، لاَ تَتْرُكْنِي وَمَشُورَةَ شَفَتَيَّ.  لاَ تَدَعْنِي أَطْمَحُ بِعَيْنَيَّ وَالْهَوَى اصْرِفْهُ عَنِّي.  لاَ تَمْلِكْنِي شَهْوَةُ الْبَطْنِ وَلاَ الزِّنَا وَلاَ تُسَلِّمْنِي إِلَى نَفْسٍ وَقِحَةٍ."}, {"title": "صلاة أرميا النبي", "ref": "( أر  17 : 13- 18)", "text": "لذلك هكذا قال الرب: «اسألوا بين الأمم. من سمع كهذه؟ ما يقشعر منه جدا عملت عذراء إسرائيل.  هل يخلو صخر حقلي من ثلج لبنان؟ أو هل تنشف المياه المنفجرة الباردة الجارية؟  لأن شعبي قد نسيني! بخروا للباطل، وقد أعثروهم في طرقهم، في السبل القديمة ليسلكوا في شعب، في طريق غير مسهل،  لتجعل أرضهم خرابا وصفيرا أبديا. كل مار فيها يدهش وينغض رأسه.  كريح شرقية أبددهم أمام العدو. أريهم القفا لا الوجه في يوم مصيبتهم».  فقالوا: «هلم فنفكر على إرميا أفكارا، لأن الشريعة لا تبيد عن الكاهن، ولا المشورة عن الحكيم، ولا الكلمة عن النبي. هلم فنضربه باللسان ولكل كلامه لا نصغي»."}, {"title": "صلاة أرميا النبي", "ref": "( أر  20 : 7- 13)", "text": "قَدْ أَقْنَعْتَنِي يَا رَبُّ فَاقْتَنَعْتُ، وَأَلْحَحْتَ عَلَيَّ فَغَلَبْتَ. صِرْتُ لِلضَّحِكِ كُلَّ النَّهَارِ. كُلُّ وَاحِدٍ اسْتَهْزَأَ بِي.  لأَنِّي كُلَّمَا تَكَلَّمْتُ صَرَخْتُ. نَادَيْتُ: «ظُلْمٌ وَاغْتِصَابٌ!» لأَنَّ كَلِمَةَ الرَّبِّ صَارَتْ لِي لِلْعَارِ وَلِلسُّخْرَةِ كُلَّ النَّهَارِ.  فَقُلْتُ: «لاَ أَذْكُرُهُ وَلاَ أَنْطِقُ بَعْدُ بِاسْمِهِ». فَكَانَ فِي قَلْبِي كَنَارٍ مُحْرِقَةٍ مَحْصُورَةٍ فِي عِظَامِي، فَمَلِلْتُ مِنَ الإِمْسَاكِ وَلَمْ أَسْتَطِعْ.  لأَنِّي سَمِعْتُ مَذَمَّةً مِنْ كَثِيرِينَ. خَوْفٌ مِنْ كُلِّ جَانِبٍ. يَقُولُونَ: «اشْتَكُوا، فَنَشْتَكِيَ عَلَيْهِ». كُلُّ أَصْحَابِي يُرَاقِبُونَ ظَلْعِي قَائِلِينَ: «لَعَلَّهُ يُطْغَى فَنَقْدِرَ عَلَيْهِ وَنَنْتَقِمَ مِنْهُ».  وَلكِنَّ الرَّبَّ مَعِي كَجَبَّارٍ قَدِيرٍ. مِنْ أَجْلِ ذلِكَ يَعْثُرُ مُضْطَهِدِيَّ وَلاَ يَقْدِرُونَ. خَزُوا جِدًّا لأَنَّهُمْ لَمْ يَنْجَحُوا، خِزْيًا أَبَدِيًّا لاَ يُنْسَى.  فَيَا رَبَّ الْجُنُودِ، مُخْتَبِرَ الصِّدِّيقِ، نَاظِرَ الْكُلَى وَالْقَلْبِ، دَعْنِي أَرَى نَقْمَتَكَ مِنْهُمْ لأَنِّي لَكَ كَشَفْتُ دَعْوَايَ.  رَنِّمُوا لِلرَّبِّ، سَبِّحُوا الرَّبَّ، لأَنَّهُ قَدْ أَنْقَذَ نَفْسَ الْمِسْكِينِ مِنْ يَدِ الأَشْرَارِ."}, {"title": "صلاة عزرا الكاهن", "ref": "( عز  9 : 6- 15)", "text": "«اللهم، إني أخجل وأخزى من أن أرفع يا إلهي وجهي نحوك، لأن ذنوبنا قد كثرت فوق رؤوسنا، وآثامنا تعاظمت إلى السماء.  منذ أيام آبائنا نحن في إثم عظيم إلى هذا اليوم. ولأجل ذنوبنا قد دفعنا نحن وملوكنا وكهنتنا ليد ملوك الأراضي للسيف والسبي والنهب وخزي الوجوه كهذا اليوم.  والآن كلحيظة كانت رأفة من لدن الرب إلهنا ليبقي لنا نجاة ويعطينا وتدا في مكان قدسه، لينير إلهنا أعيننا ويعطينا حياة قليلة في عبوديتنا.  لأننا عبيد نحن، وفي عبوديتنا لم يتركنا إلهنا بل بسط علينا رحمة أمام ملوك فارس، ليعطينا حياة لنرفع بيت إلهنا ونقيم خرائبه، وليعطينا حائطا في يهوذا وفي أورشليم.  والآن، فماذا نقول يا إلهنا بعد هذا؟ لأننا قد تركنا وصاياك  التي أوصيت بها عن يد عبيدك الأنبياء قائلا: إن الأرض التي تدخلون لتمتلكوها هي أرض متنجسة بنجاسة شعوب الأراضي، برجاساتهم التي ملأوها بها من جهة إلى جهة بنجاستهم.  والآن فلا تعطوا بناتكم لبنيهم ولا تأخذوا بناتهم لبنيكم، ولا تطلبوا سلامتهم وخيرهم إلى الأبد لكي تتشددوا وتأكلوا خير الأرض وتورثوا بنيكم إياها إلى الأبد.  وبعد كل ما جاء علينا لأجل أعمالنا الرديئة وآثامنا العظيمة، لأنك قد جازيتنا يا إلهنا أقل من آثامنا وأعطيتنا نجاة كهذه،  أفنعود ونتعدى وصاياك ونصاهر شعوب هذه الرجاسات؟ أما تسخط علينا حتى تفنينا فلا تكون بقية ولا نجاة؟  أيها الرب إله إسرائيل، أنت بار لأننا بقينا ناجين كهذا اليوم. ها نحن أمامك في آثامنا، لأنه ليس لنا أن نقف أمامك من أجل هذا»."}, {"title": "صلاة عزرا الكاهن وهو يقود الشعب للتوبة", "ref": "( نح  9 : 6- 38)", "text": "أنت هو الرب وحدك. أنت صنعت السماوات وسماء السماوات وكل جندها، والأرض وكل ما عليها، والبحار وكل ما فيها، وأنت تحييها كلها. وجند السماء لك يسجد.  أنت هو الرب الإله الذي اخترت أبرام وأخرجته من أور الكلدانيين وجعلت اسمه إبراهيم.  ووجدت قلبه أمينا أمامك، وقطعت معه العهد أن تعطيه أرض الكنعانيين والحثيين والأموريين والفرزيين واليبوسيين والجرجاشيين وتعطيها لنسله. وقد أنجزت وعدك لأنك صادق.  ورأيت ذل آبائنا في مصر، وسمعت صراخهم عند بحر سوف،  وأظهرت آيات وعجائب على فرعون وعلى جميع عبيده وعلى كل شعب أرضه، لأنك علمت أنهم بغوا عليهم، وعملت لنفسك اسما كهذا اليوم.  وفلقت اليم أمامهم، وعبروا في وسط البحر على اليابسة، وطرحت مطارديهم في الأعماق كحجر في مياه قوية.  وهديتهم بعمود سحاب نهارا، وبعمود نار ليلا لتضيء لهم في الطريق التي يسيرون فيها.  ونزلت على جبل سيناء، وكلمتهم من السماء، وأعطيتهم أحكاما مستقيمة وشرائع صادقة، فرائض ووصايا صالحة.  وعرفتهم سبتك المقدس، وأمرتهم بوصايا وفرائض وشرائع عن يد موسى عبدك.  وأعطيتهم خبزا من السماء لجوعهم، وأخرجت لهم ماء من الصخرة لعطشهم، وقلت لهم أن يدخلوا ويرثوا الأرض التي رفعت يدك أن تعطيهم إياها.  «ولكنهم بغوا هم وآباؤنا، وصلبوا رقابهم ولم يسمعوا لوصاياك،  وأبوا الاستماع، ولم يذكروا عجائبك التي صنعت معهم، وصلبوا رقابهم. وعند تمردهم أقاموا رئيسا ليرجعوا إلى عبوديتهم. وأنت إله غفور وحنان ورحيم، طويل الروح وكثير الرحمة، فلم تتركهم.  مع أنهم عملوا لأنفسهم عجلا مسبوكا وقالوا: هذا إلهك الذي أخرجك من مصر، وعملوا إهانة عظيمة.  أنت برحمتك الكثيرة لم تتركهم في البرية، ولم يزل عنهم عمود السحاب نهارا لهدايتهم في الطريق، ولا عمود النار ليلا ليضيء لهم في الطريق التي يسيرون فيها.  وأعطيتهم روحك الصالح لتعليمهم، ولم تمنع منك عن أفواههم، وأعطيتهم ماء لعطشهم.  وعلتهم أربعين سنة في البرية فلم يحتاجوا. لم تبل ثيابهم، ولم تتورم أرجلهم.  وأعطيتهم ممالك وشعوبا، وفرقتهم إلى جهات، فامتلكوا أرض سيحون، وأرض ملك حشبون، وأرض عوج ملك باشان.  وأكثرت بنيهم كنجوم السماء، وأتيت بهم إلى الأرض التي قلت لآبائهم أن يدخلوا ويرثوها.  فدخل البنون وورثوا الأرض، وأخضعت لهم سكان أرض الكنعانيين، ودفعتهم ليدهم مع ملوكهم وشعوب الأرض ليعملوا بهم حسب إرادتهم.  وأخذوا مدنا حصينة وأرضا سمينة، وورثوا بيوتا ملآنة كل خير، وآبارا محفورة وكروما وزيتونا وأشجارا مثمرة بكثرة، فأكلوا وشبعوا وسمنوا وتلذذوا بخيرك العظيم.  وعصوا وتمردوا عليك، وطرحوا شريعتك وراء ظهورهم، وقتلوا أنبياءك الذين أشهدوا عليهم ليردوهم إليك، وعملوا إهانة عظيمة.  فدفعتهم ليد مضايقيهم فضايقوهم. وفي وقت ضيقهم صرخوا إليك، وأنت من السماء سمعت، وحسب مراحمك الكثيرة أعطيتهم مخلصين خلصوهم من يد مضايقيهم.  ولكن لما استراحوا رجعوا إلى عمل الشر قدامك، فتركتهم بيد أعدائهم، فتسلطوا عليهم ثم رجعوا وصرخوا إليك، وأنت من السماء سمعت وأنقذتهم حسب مراحمك الكثيرة أحيانا كثيرة.  وأشهدت عليهم لتردهم إلى شريعتك، وأما هم فبغوا ولم يسمعوا لوصاياك وأخطأوا ضد أحكامك، التي إذا عملها إنسان يحيا بها. وأعطوا كتفا معاندة، وصلبوا رقابهم ولم يسمعوا.  فاحتملتهم سنين كثيرة، وأشهدت عليهم بروحك عن يد أنبيائك فلم يصغوا، فدفعتهم ليد شعوب الأراضي.  ولكن لأجل مراحمك الكثيرة لم تفنهم ولم تتركهم، لأنك إله حنان ورحيم.  «والآن يا إلهنا، الإله العظيم الجبار المخوف، حافظ العهد والرحمة، لا تصغر لديك كل المشقات التي أصابتنا نحن وملوكنا ورؤساءنا وكهنتنا وأنبياءنا وآباءنا وكل شعبك، من أيام ملوك أشور إلى هذا اليوم.  وأنت بار في كل ما أتى علينا لأنك عملت بالحق، ونحن أذنبنا.  وملوكنا ورؤساؤنا وكهنتنا وآباؤنا لم يعملوا شريعتك، ولا أصغوا إلى وصاياك وشهاداتك التي أشهدتها عليهم.  وهم لم يعبدوك في مملكتهم وفي خيرك الكثير الذي أعطيتهم، وفي الأرض الواسعة السمينة التي جعلتها أمامهم، ولم يرجعوا عن أعمالهم الردية.  ها نحن اليوم عبيد، والأرض التي أعطيت لآبائنا ليأكلوا أثمارها وخيرها، ها نحن عبيد فيها.   وغلاتها كثيرة للملوك الذين جعلتهم علينا لأجل خطايانا، وهم يتسلطون على أجسادنا وعلى بهائمنا حسب إرادتهم، ونحن في كرب عظيم.  «ومن أجل كل ذلك نحن نقطع ميثاقا ونكتبه. ورؤساؤنا ولاويونا وكهنتنا يختمون»."}, {"title": "صلاة نحميا لأجل شعبه", "ref": "( نح  1 : 4- 11 )", "text": "فلما سمعت هذا الكلام جلست وبكيت ونحت أياما، وصمت وصليت أمام إله السماء، وقلت: «أيها الرب إله السماء، الإله العظيم المخوف، الحافظ العهد والرحمة لمحبيه وحافظي وصاياه، لتكن أذنك مصغية وعيناك مفتوحتين لتسمع صلاة عبدك الذي يصلي إليك الآن نهارا وليلا لأجل بني إسرائيل عبيدك، ويعترف بخطايا بني إسرائيل التي أخطأنا بها إليك. فإني أنا وبيت أبي قد أخطأنا. لقد أفسدنا أمامك، ولم نحفظ الوصايا والفرائض والأحكام التي أمرت بها موسى عبدك. اذكر الكلام الذي أمرت به موسى عبدك قائلا: إن خنتم فإني أفرقكم في الشعوب، وإن رجعتم إلي وحفظتم وصاياي وعملتموها، إن كان المنفيون منكم في أقصاء السماوات، فمن هناك أجمعهم وآتي بهم إلى المكان الذي اخترت لإسكان اسمي فيه. فهم عبيدك وشعبك الذي افتديت بقوتك العظيمة ويدك الشديدة. يا سيد، لتكن أذنك مصغية إلى صلاة عبدك وصلاة عبيدك الذين يريدون مخافة اسمك. وأعط النجاح اليوم لعبدك وامنحه رحمة أمام هذا الرجل». لأني كنت ساقيا للملك."}, {"title": "صلاة نحميا", "ref": "( 2 مك 24 - 29 )", "text": "و هذا ما صلى به نحميا ايها الرب الرب الاله خالق الكل المرهوب القوي العادل الرحيم يا من هو وحده الملك والبار يا من هو وحده المتفضل العادل القدير الازلي مخلص اسرائيل من كل شر الذي اصطفى اباءنا وقدسهم تقبل الذبيحة من اجل جميع شعبك اسرائيل وصن ميراثك وقدسه و اجمع شتاتنا واعتق المستعبدين عند الامم وانظر الى الممتهنين والممقوتين ولتعلم الامم انك انت الهنا و عاقب الظالمين والقاذفين بتجبر و اغرس شعبك في مكانك المقدس كما قال موسى"}, {"title": "صلاة ارميا", "ref": "( مر أ 5 : 1 - 22 )", "text": "اذكر يا رب ماذا صار لنا. أشرف وانظر إلى عارنا. قد صار ميراثنا للغرباء. بيوتنا للأجانب. صرنا أيتاما بلا أب. أمهاتنا كأرامل. شربنا ماءنا بالفضة. حطبنا بالثمن يأتي.  على أعناقنا نضطهد. نتعب ولا راحة لنا.  أعطينا اليد للمصريين والأشوريين لنشبع خبزا.  آباؤنا أخطأوا وليسوا بموجودين، ونحن نحمل آثامهم.  عبيد حكموا علينا. ليس من يخلص من أيديهم. بأنفسنا نأتي بخبزنا من جرى سيف البرية.  جلودنا اسودت كتنور من جرى نيران الجوع. أذلوا النساء في صهيون، العذارى في مدن يهوذا. الرؤساء بأيديهم يعلقون، ولم تعتبر وجوه الشيوخ.  أخذوا الشبان للطحن، والصبيان عثروا تحت الحطب. كفت الشيوخ عن الباب، والشبان عن غنائهم.  مضى فرح قلبنا. صار رقصنا نوحا.  سقط إكليل رأسنا. ويل لنا لأننا قد أخطأنا.  من أجل هذا حزن قلبنا. من أجل هذه أظلمت عيوننا.  من أجل جبل صهيون الخرب. الثعالب ماشية فيه.  أنت يا رب إلى الأبد تجلس. كرسيك إلى دور فدور.  لماذا تنسانا إلى الأبد وتتركنا طول الأيام؟  ارددنا يا رب إليك فنرتد. جدد أيامنا كالقديم.  هل كل الرفض رفضتنا؟ هل غضبت علينا جدا؟"}, {"title": "صلاة بولس الرسول", "ref": "( أف 3 : 14 - 21 )", "text": "بسبب هذا أحني ركبتي لدى أبي ربنا يسوع المسيح، الذي منه تسمى كل عشيرة في السماوات وعلى الأرض. لكي يعطيكم بحسب غنى مجده، أن تتأيدوا بالقوة بروحه في الإنسان الباطن، ليحل المسيح بالإيمان في قلوبكم، وأنتم متأصلون ومتأسسون في المحبة، حتى تستطيعوا أن تدركوا مع جميع القديسين، ما هو العرض والطول والعمق والعلو، وتعرفوا محبة المسيح الفائقة المعرفة، لكي تمتلئوا إلى كل ملء الله. والقادر أن يفعل فوق كل شيء، أكثر جدا مما نطلب أو نفتكر، بحسب القوة التي تعمل فينا، له المجد في الكنيسة في المسيح يسوع إلى جميع أجيال دهر الدهور. آمين."}, {"title": "صلاة بولس الرسول", "ref": "(في 1: 3 ، 9 - 11 )", "text": "أشكر إلهي عند كل ذكري إياكم .........  وهذا أصليه: أن تزداد محبتكم أيضا أكثر فأكثر في المعرفة وفي كل فهم،حتى تميزوا الأمور المتخالفة، لكي تكونوا مخلصين وبلا عثرة إلى يوم المسيح،  مملوئين من ثمر البر الذي بيسوع المسيح لمجد الله وحمده."}, {"title": "صلاة بولس الرسول", "ref": "(1 كو 3:  9 - 14 )", "text": "لا تكذبوا بعضكم على بعض، إذ خلعتم الإنسان العتيق مع أعماله، ولبستم الجديد الذي يتجدد للمعرفة حسب صورة خالقه، حيث ليس يوناني ويهودي، ختان وغرلة، بربري سكيثي، عبد حر، بل المسيح الكل وفي الكل. فالبسوا كمختاري الله القديسين المحبوبين أحشاء رأفات، ولطفا، وتواضعا، ووداعة، وطول أناة، محتملين بعضكم بعضا، ومسامحين بعضكم بعضا إن كان لأحد على أحد شكوى. كما غفر لكم المسيح هكذا أنتم أيضا. وعلى جميع هذه البسوا المحبة التي هي رباط الكمال."}, {"title": "صلاة بولس الرسول", "ref": "(1 تس 3:  11- 13 )", "text": "والله نفسه أبونا وربنا يسوع المسيح يهدي طريقنا إليكم. والرب ينميكم ويزيدكم في المحبة بعضكم لبعض وللجميع، كما نحن أيضا لكم، لكي يثبت قلوبكم بلا لوم في القداسة، أمام الله أبينا في مجيء ربنا يسوع المسيح مع جميع قديسيه."}, {"title": "صلاة بولس الرسول", "ref": "(1 تس 5:  23 )", "text": "وإله السلام نفسه يقدسكم بالتمام. ولتحفظ روحكم ونفسكم وجسدكم كاملة بلا لوم عند مجيء ربنا يسوع المسيح."}, {"title": "صلاة بولس الرسول", "ref": "(عب 13:  20 )", "text": "وإله السلام الذي أقام من الأموات راعي الخراف العظيم، ربنا يسوع، بدم العهد الأبدي، ليكملكم في كل عمل صالح لتصنعوا مشيئته، عاملا فيكم ما يرضي أمامه بيسوع المسيح، الذي له المجد إلى أبد الآبدين. آمين."}, {"title": "صلاة بطرس الرسول", "ref": "(1 بط 5: 10 – 11 )", "text": "وإله كل نعمة الذي دعانا إلى مجده الأبدي في المسيح يسوع، بعدما تألمتم يسيرا، هو يكملكم، ويثبتكم، ويقويكم، ويمكنكم.  له المجد والسلطان إلى أبد الآبدين. آمين."}, {"title": "صلاة يهوذا الرسول", "ref": "(يه 1: 24 – 25 )", "text": "والقادر أن يحفظكم غير عاثرين، ويوقفكم أمام مجده بلا عيب في الابتهاج، الإله الحكيم الوحيد مخلصنا، له المجد والعظمة والقدرة والسلطان، الآن وإلى كل الدهور. آمين."}, {"title": "صلاة موسي النبي  لأجل خطية شعبه", "ref": "(تث 9: 25 – 29  ، خر 32 )", "text": "«فسقطت أمام الرب الأربعين نهارا والأربعين ليلة التي سقطتها، لأن الرب قال إنه يهلككم. وصليت للرب وقلت: يا سيد الرب، لا تهلك شعبك وميراثك الذي فديته بعظمتك، الذي أخرجته من مصر بيد شديدة. اذكر عبيدك إبراهيم وإسحاق ويعقوب. لا تلتفت إلى غلاظة هذا الشعب وإثمه وخطيته، لئلا تقول الأرض التي أخرجتنا منها: لأجل أن الرب لم يقدر أن يدخلهم الأرض التي كلمهم عنها، ولأجل أنه أبغضهم، أخرجهم لكي يميتهم في البرية. وهم شعبك وميراثك الذي أخرجته بقوتك العظيمة وبذراعك الرفيعة."}, {"title": "صلاة يشوع بعد الهزيمة في عاي", "ref": "(يش7 : 7 – 9 )", "text": "وقال يشوع: «آه يا سيد الرب! لماذا عبرت هذا الشعب الأردن تعبيرا لكي تدفعنا إلى يد الأموريين ليبيدونا؟ ليتنا ارتضينا وسكنا في عبر الأردن. أسألك يا سيد: ماذا أقول بعدما حول إسرائيل قفاه أمام أعدائه؟ فيسمع الكنعانيون وجميع سكان الأرض ويحيطون بنا ويقرضون اسمنا من الأرض. وماذا تصنع لاسمك العظيم؟»"}, {"title": "صلاة أشعياء", "ref": "(اش 63 : 7 – 19 )", "text": "إحسانات الرب أذكر، تسابيح الرب، حسب كل ما كافأنا به الرب، والخير العظيم لبيت إسرائيل الذي كافأهم به حسب مراحمه، وحسب كثرة إحساناته. وقد قال حقا: «إنهم شعبي، بنون لا يخونون». فصار لهم مخلصا.  في كل ضيقهم تضايق، وملاك حضرته خلصهم. بمحبته ورأفته هو فكهم ورفعهم وحملهم كل الأيام القديمة. ولكنهم تمردوا وأحزنوا روح قدسه، فتحول لهم عدوا، وهو حاربهم. ثم ذكر الأيام القديمة، موسى وشعبه: «أين الذي أصعدهم من البحر مع راعي غنمه؟ أين الذي جعل في وسطهم روح قدسه، الذي سير ليمين موسى ذراع مجده، الذي شق المياه قدامهم ليصنع لنفسه اسما أبديا، الذي سيرهم في اللجج، كفرس في البرية فلم يعثروا؟ كبهائم تنزل إلى وطاء، روح الرب أراحهم». هكذا قدت شعبك لتصنع لنفسك اسم مجد. تطلع من السماوات وانظر من مسكن قدسك ومجدك: أين غيرتك وجبروتك؟ زفير أحشائك ومراحمك نحوي امتنعت. فإنك أنت أبونا وإن لم يعرفنا إبراهيم، وإن لم يدرنا إسرائيل. أنت يا رب أبونا، ولينا منذ الأبد اسمك. لماذا أضللتنا يا رب عن طرقك، قسيت قلوبنا عن مخافتك؟ ارجع من أجل عبيدك، أسباط ميراثك. إلى قليل امتلك شعب قدسك. مضايقونا داسوا مقدسك. قد كنا منذ زمان كالذين لم تحكم عليهم، ولم يدع عليهم باسمك."}, {"title": "صلاة أرميا من جهة القحط", "ref": "(أر 14 : 7 – 9 ، 19 - 22 )", "text": "وإن تكن آثامنا تشهد علينا يا رب، فاعمل لأجل اسمك. لأن معاصينا كثرت. إليك أخطأنا. يا رجاء إسرائيل، مخلصه في زمان الضيق، لماذا تكون كغريب في الأرض، وكمسافر يميل ليبيت؟ لماذا تكون كإنسان قد تحير، كجبار لا يستطيع أن يخلص؟ وأنت في وسطنا يا رب، وقد دعينا باسمك. لا تتركنا!  ..هل رفضت يهوذا رفضا، أو كرهت نفسك صهيون؟ لماذا ضربتنا ولا شفاء لنا؟ انتظرنا السلام فلم يكن خير، وزمان الشفاء فإذا رعب. قد عرفنا يا رب شرنا، إثم آبائنا، لأننا قد أخطأنا إليك. لا ترفض لأجل اسمك. لا تهن كرسي مجدك. اذكر. لا تنقض عهدك معنا. هل يوجد في أباطيل الأمم من يمطر، أو هل تعطي السماوات وابلا؟ أما أنت هو الرب إلهنا؟ فنرجوك، لأنك أنت صنعت كل هذه."}, {"title": "صلاة باروخ", "ref": "(بار 3 : 1 – 8 )", "text": "أيها الرب القدير إله إسرائيل قد صرخت إليك النفس في المضايق والروح في الكروب. فاسمع يا رب وارحم فإنك إله رحيم، ارحم فإنا قد خطئنا إليك. فإنك أنت تدوم إلى الأبد أما نحن فنهلك إلى الأبد. أيها الرب القدير إله إسرائيل اسمع صلاة قوم إسرائيل وبني الذين خطئوا إليك الذين لم يسمعوا لصوت إلههم وقد لحق الشر بنا لا تذكر أثام آبائنا بل اذكر يدك واسمك في هذا الزمان فإنك أنت الرب إلهنا وإياك نسبح يا رب. لأنك لذلك جعلت مخافتك في قلوبنا ولندعو باسمك، إنا نسبحك في جلائنا لأنا قد نبذنا عن قلوبنا كل إثم آبائنا الذين خطئوا أمامك وها إنا اليوم في الجلاء حيث شتتنا للتعيير واللعنة والعقاب لأجل جميع آثام آبائنا الذين ارتدوا عن الرب إلهنا."}, {"title": "بركة اسحق ليعقوب", "ref": "(تك 27 : 28 – 29 )", "text": "فليعطك الله من ندى السماء ومن دسم الأرض. وكثرة حنطة وخمر. ليستعبد لك شعوب، وتسجد لك قبائل. كن سيدا لإخوتك، وليسجد لك بنو أمك. ليكن لاعنوك ملعونين، ومباركوك مباركين»."}, {"title": "بلعام يبارك الشعب كما امره الرب", "ref": "( عد 24 : 5 – 9 )", "text": "ما أحسن خيامك يا يعقوب، مساكنك يا إسرائيل! كأودية ممتدة. كجنات على نهر، كشجرات عود غرسها الرب. كأرزات على مياه. يجري ماء من دلائه، ويكون زرعه على مياه غزيرة، ويتسامى ملكه على أجاج وترتفع مملكته. الله أخرجه من مصر. له مثل سرعة الرئم. يأكل أمما، مضايقيه، ويقضم عظامهم ويحطم سهامه. جثم كأسد. ربض كلبوة. من يقيمه؟ مباركك مبارك، ولاعنك ملعون»."}, {"title": "بركة هارون", "ref": "( عد 6 : 22 – 27 )", "text": "وكلم الرب موسى قائلا: «كلم هارون وبنيه قائلا: هكذا تباركون بني إسرائيل قائلين لهم: يباركك الرب ويحرسك. يضيء الرب بوجهه عليك ويرحمك. يرفع الرب وجهه عليك ويمنحك سلاما. فيجعلون اسمي على بني إسرائيل، وأنا أباركهم»."}, {"title": "صلاة أرميا", "ref": "( 15 : 15 – 21 )", "text": "أنت يا رب عرفت. اذكرني وتعهدني وانتقم لي من مضطهدي. بطول أناتك لا تأخذني. اعرف احتمالي العار لأجلك. وجد كلامك فأكلته، فكان كلامك لي للفرح ولبهجة قلبي، لأني دعيت باسمك يا رب إله الجنود. لم أجلس في محفل المازحين مبتهجا. من أجل يدك جلست وحدي، لأنك قد ملأتني غضبا. لماذا كان وجعي دائما وجرحي عديم الشفاء، يأبى أن يشفى؟ أتكون لي مثل كاذب، مثل مياه غير دائمة؟ لذلك هكذا قال الرب: «إن رجعت أرجعك، فتقف أمامي. وإذا أخرجت الثمين من المرذول فمثل فمي تكون. هم يرجعون إليك وأنت لا ترجع إليهم. وأجعلك لهذا الشعب سور نحاس حصينا، فيحاربونك ولا يقدرون عليك، لأني معك لأخلصك وأنقذك، يقول الرب. فأنقذك من يد الأشرار وأفديك من كف العتاة»."}, {"title": "صلاة أشعياء", "ref": "( أش 12 : 1 – 6 )", "text": "وتقول في ذلك اليوم: «أحمدك يا رب، لأنه إذ غضبت علي ارتد غضبك فتعزيني. هوذا الله خلاصي فأطمئن ولا أرتعب، لأن ياه يهوه قوتي وترنيمتي وقد صار لي خلاصا».  فتستقون مياها بفرح من ينابيع الخلاص. وتقولون في ذلك اليوم: «احمدوا الرب. ادعوا باسمه. عرفوا بين الشعوب بأفعاله. ذكروا بأن اسمه قد تعالى.  رنموا للرب لأنه قد صنع مفتخرا. ليكن هذا معروفا في كل الأرض. صوتي واهتفي يا ساكنة صهيون، لأن قدوس إسرائيل عظيم في وسطك»."}, {"title": "صلاة حبقوق", "ref": "( حب 1 : 2 – 4 ، 12 - 17 )", "text": "حتى متى يا رب أدعو وأنت لا تسمع؟ أصرخ إليك من الظلم وأنت لا تخلص؟لم تريني إثما، وتبصر جورا؟ وقدامي اغتصاب وظلم ويحدث خصام وترفع المخاصمة نفسها. لذلك جمدت الشريعة ولا يخرج الحكم بتة، لأن الشرير يحيط بالصديق، فلذلك يخرج الحكم معوجا. ألست أنت منذ الأزل يا رب إلهي قدوسي؟ لا نموت. يا رب للحكم جعلتها، ويا صخر للتأديب أسستها. عيناك أطهر من أن تنظرا الشر، ولا تستطيع النظر إلى الجور، فلم تنظر إلى الناهبين، وتصمت حين يبلع الشرير من هو أبر منه؟ وتجعل الناس كسمك البحر، كدبابات لا سلطان لها. تطلع الكل بشصها، وتصطادهم بشبكتها وتجمعهم في مصيدتها، فلذلك تفرح وتبتهج. لذلك تذبح لشبكتها، وتبخر لمصيدتها، لأنه بهما سمن نصيبها، وطعامها مسمن. أفلأجل هذا تفرغ شبكتها ولا تعفو عن قتل الأمم دائما؟"}, {"title": "صلاة أيوب للتوبة", "ref": "( أي 42 : 2 – 6 )", "text": "«قد علمت أنك تستطيع كل شيء، ولا يعسر عليك أمر. فمن ذا الذي يخفي القضاء بلا معرفة؟ ولكني قد نطقت بما لم أفهم. بعجائب فوقي لم أعرفها. اسمع الآن وأنا أتكلم. أسألك فتعلمني. بسمع الأذن قد سمعت عنك، والآن رأتك عيني. لذلك أرفض وأندم في التراب والرماد»."}, {"title": "صلاة اشعياء", "ref": "( أش 12 : 1 - 6 )", "text": "وتقول في ذلك اليوم: «أحمدك يا رب، لأنه إذ غضبت علي ارتد غضبك فتعزيني. هوذا الله خلاصي فأطمئن ولا أرتعب، لأن ياه يهوه قوتي وترنيمتي وقد صار لي خلاصا». فتستقون مياها بفرح من ينابيع الخلاص. وتقولون في ذلك اليوم: «احمدوا الرب. ادعوا باسمه. عرفوا بين الشعوب بأفعاله. ذكروا بأن اسمه قد تعالى. رنموا للرب لأنه قد صنع مفتخرا. ليكن هذا معروفا في كل الأرض. صوتي واهتفي يا ساكنة صهيون، لأن قدوس إسرائيل عظيم في وسطك»."}, {"title": "صلاة اشعياء", "ref": "( أش 42 : 10 - 17 )", "text": "لا تخف لأني معك. لا تتلفت لأني إلهك. قد أيدتك وأعنتك وعضدتك بيمين بري. إنه سيخزى ويخجل جميع المغتاظين عليك. يكون كلا شيء مخاصموك ويبيدون. تفتش على منازعيك ولا تجدهم. يكون محاربوك كلا شيء وكالعدم. لأني أنا الرب إلهك الممسك بيمينك، القائل لك: لا تخف. أنا أعينك. «لا تخف يا دودة يعقوب، يا شرذمة إسرائيل. أنا أعينك، يقول الرب، وفاديك قدوس إسرائيل. هأنذا قد جعلتك نورجا محددا جديدا ذا أسنان. تدرس الجبال وتسحقها، وتجعل الآكام كالعصافة. تذريها فالريح تحملها والعاصف تبددها، وأنت تبتهج بالرب. بقدوس إسرائيل تفتخر. «البائسون والمساكين طالبون ماء ولا يوجد. لسانهم من العطش قد يبس. أنا الرب أستجيب لهم. أنا إله إسرائيل لا أتركهم."}, {"title": "صلاة شكر لأرميا", "ref": "( ار 32 : 17 – 25 )", "text": "آه، أيها السيد الرب، ها إنك قد صنعت السماوات والأرض بقوتك العظيمة، وبذراعك الممدودة. لا يعسر عليك شيء. صانع الإحسان لألوف، ومجازي ذنب الآباء في حضن بنيهم بعدهم، الإله العظيم الجبار، رب الجنود اسمه. عظيم في المشورة، وقادر في العمل، الذي عيناك مفتوحتان على كل طرق بني آدم لتعطي كل واحد حسب طرقه، وحسب ثمر أعماله. الذي جعلت آيات وعجائب في أرض مصر إلى هذا اليوم، وفي إسرائيل وفي الناس، وجعلت لنفسك اسما كهذا اليوم، وأخرجت شعبك إسرائيل من أرض مصر بآيات وعجائب، وبيد شديدة وذراع ممدودة ومخافة عظيمة، وأعطيتهم هذه الأرض التي حلفت لآبائهم أن تعطيهم إياها، أرضا تفيض لبنا وعسلا. فأتوا وامتلكوها، ولم يسمعوا لصوتك، ولا ساروا في شريعتك. كل ما أوصيتهم أن يعملوه لم يعملوه، فأوقعت بهم كل هذا الشر. ها المتارس! قد أتوا إلى المدينة ليأخذوها، وقد دفعت المدينة ليد الكلدانيين الذين يحاربونها بسبب السيف والجوع والوبإ، وما تكلمت به فقد حدث، وها أنت ناظر. وقد قلت أنت لي أيها السيد الرب: اشتر لنفسك الحقل بفضة وأشهد شهودا، وقد دفعت المدينة ليد الكلدانيين."}, {"title": "صلاة شكر لدانيال النبي", "ref": "( دا 2 : 19 – 23 )", "text": "حينئذ لدانيآل كشف السر في رؤيا الليل. فبارك دانيآل إله السماوات. أجاب دانيآل وقال: «ليكن اسم الله مباركا من الأزل وإلى الأبد، لأن له الحكمة والجبروت. وهو يغير الأوقات والأزمنة. يعزل ملوكا وينصب ملوكا. يعطي الحكماء حكمة، ويعلم العارفين فهما. هو يكشف العمائق والأسرار. يعلم ما هو في الظلمة، وعنده يسكن النور. إياك يا إله آبائي أحمد، وأسبح الذي أعطاني الحكمة والقوة وأعلمني الآن ما طلبناه منك، لأنك أعلمتنا أمر الملك»."}, {"title": "صلاة يهوديت", "ref": "( يهوديت 16 : 1 – 9 )", "text": "حينئذ أنشدت يهوديت هذا النشيد للرب فقالت: «سبحوا الرب بالدفوف، رنموا للرب على الصنوج، أنشدوا له إنشادا جديدا، عظموه وادعوا باسمه. الرب يمحق الحروب، الرب اسمه. جعل معسكره في وسط شعبه لينقذنا من أيدي جميع أعدائنا. أتى أشور من الجبال الشمالية، أتى في كثرة قوته، فسدت كثرته الأودية وخيوله غطت الوهاد. قال إنه سيحرق تخومي، ويقتل فتياني بالسيف، ويجعل أطفالي غنيمة وأبكاري سبيا؛ الرب القدير ضربه وأسلمه إلى يد امرأة فطعنته. إن جبارهم لم يسقط بأيدي الشبان ولم يبطش به بنو طيطان ولا جبابرة طوال تعرضوا له، بل يهوديت ابنة مراري بجمال وجهها أهلكته. نزعت ثياب إرمالها، وتردت بثياب فرحها لابتهاج بني إسرائيل."}, {"title": "صلاة يهوديت", "ref": "( يهوديت 16 : 15 – 21 )", "text": "فلنسبح الرب تسبيحا، ونرنم نشيدا جديدا لإلهنا. أيها الرب أدوناي إنك عظيم شهير بجبروتك ولا يقوى عليك أحد. إياك فلتعبد خليقتك بأسرها، لأنك أنت قلت فكانوا أرسلت روحك فخلقوا، وليس من يقاوم كلمتك. تهتز الجبال من أساسها مع المياه، والصخور كالشمع تذوب أمام وجهك، والذين يتقونك يكونون أعزة عندك في كل شيء. الويل للأمة القائمة على شعبي، الرب القدير ينتقم منهم وفي يوم الدينونة يفتقدهم. يجعل لحومهم للنار والدود، لكي يحترقوا ويتألموا إلى الأبد»."}, {"title": "صلاة يشوع بن سيراخ", "ref": "( سيراخ 51 : 1 – 12 )", "text": "صلاة يشوع بن سيراخ: أعترف لك أيها الرب الملك وأسبح الله مخلصي. أعترف لاسمك، لأنك كنت لي مجيرا ونصيرا، وافتديت جسدي من الهلاك، ومن شرك سعاية اللسان، ومن شفاه مختلقي الزور، وكنت لي ناصرا تجاه المقاومين، وافتديتني برحمتك الغزيرة واسمك، من زئير المستعدين للافتراس. من أيدي طالبي نفسي، ومن مضايقي الكثيرة. من الاختناق باللهيب المحيط بي، ومن وسط النار حتى لا أصلى. من عمق جوف الجحيم، ومن اللسان الدنس، وكلام الزور، وسعاية اللسان الجائر عند الملك. دنت نفسي من الموت، واقتربت حياتي من عمق الجحيم. أحيط بي من كل جهة، ولا نصير. التفت لإغاثة الناس فلم تكن. فتذكرت رحمتك، أيها الرب، وصنيعك الذي منذ الدهر: كيف تنقذ الذين ينتظرونك، وتخلصهم من أيدي الأمم؟"}, {"title": "صلاة طوبيت", "ref": "( طوبيا 13 : 1 – 23 )", "text": "حينئذ فتح طوبيا الشيخ فاه مباركا للرب وقال: «عظيم أنت يا رب إلى الأبد وفي جميع الدهور ملكك، لأنك تجرح وتشفي وتحدر إلى الجحيم وتصعد منه، وليس من يفر من يدك. اعترفوا للرب يا بني إسرائيل وسبحوه أمام جميع الأمم، فإنه فرقكم بين الأمم الذين يجهلونه لكي تخبروا بمعجزاته وتعرفوهم أن لا إله قادرا على كل شيء سواه. هو أدبنا لأجل آثامنا، وهو يخلصنا لأجل رحمته. انظروا الآن ما صنع لنا، واعترفوا له بخوف ورعدة، ومجدوا ملك الدهور بأعمالكم. أما أنا ففي أرض جلائي أعترف له، لأنه أظهر جلاله في أمة خاطئة. ارجعوا الآن أيها الخطأة واصنعوا أمام الله برا، واثقين بأنه يصنع إليكم رحمة. أما أنا فنفسي تتهلل به. باركوا الرب يا جميع مختاريه، أقيموا أيام فرح واعترفوا له. يا أورشليم مدينة الله إن الرب أدبك بأعمال يديك. اشكري لله نعمته عليك، وباركي إله الدهور حتى يعود فيشيد مسكنه فيك، ويرد إليك جميع أهل الجلاء، وتبتهجي إلى دهر الدهور. تتلألئين بسنى بهيج وجميع شعوب الأرض لك يسجدون. يزورك الأمم من الأقاصي بقرابينهم ويسجدون فيك للرب ويعتدون أرضك أرضا مقدسة، لأنهم فيك يدعون الاسم العظيم. ملعونين يكونون الذين استهانوا بك، والذين جدفوا عليك يدانون، ويبارك الذين يبنونك. أما أنت فتفرحين ببنيك، لأنهم يباركون كافة، وإلى الرب يحتشدون. طوبى للذين يحبونك ويفرحون لك بالسلام. باركي يا نفسي الرب، لأن الرب إلهنا خلص أورشليم مدينته من جميع شدائدها. طوبى لي إن بقي من ذريتي من يبصر بهاء أورشليم. أبواب أورشليم من ياقوت وزمرد وكل محيط أسوارها من حجر كريم، وجميع أسواقها مفروشة بحجر أبيض نقي، وفي شوارعها ينشد هللويا. مبارك الرب الذي عظمها، وليكن ملكه فيها إلى دهر الدهور. آمين»."}, {"title": "صلاة شكر لبولس الرسول", "ref": "( أف 1 : 3 – 12 )", "text": "مبارك الله أبو ربنا يسوع المسيح، الذي باركنا بكل بركة روحية في السماويات في المسيح، كما اختارنا فيه قبل تأسيس العالم، لنكون قديسين وبلا لوم قدامه في المحبة، إذ سبق فعيننا للتبني بيسوع المسيح لنفسه، حسب مسرة مشيئته، لمدح مجد نعمته التي أنعم بها علينا في المحبوب، الذي فيه لنا الفداء بدمه، غفران الخطايا، حسب غنى نعمته، التي أجزلها لنا بكل حكمة وفطنة، إذ عرفنا بسر مشيئته، حسب مسرته التي قصدها في نفسه، لتدبير ملء الأزمنة، ليجمع كل شيء في المسيح، ما في السماوات وما على الأرض، في ذاك الذي فيه أيضا نلنا نصيبا، معينين سابقا حسب قصد الذي يعمل كل شيء حسب رأي مشيئته، لنكون لمدح مجده، نحن الذين قد سبق رجاؤنا في المسيح."}, {"title": "صلاة بطرس الرسول", "ref": "( 1 بط 1 : 3 – 5 )", "text": "مبارك الله أبو ربنا يسوع المسيح، الذي حسب رحمته الكثيرة ولدنا ثانية لرجاء حي، بقيامة يسوع المسيح من الأموات، لميراث لا يفنى ولا يتدنس ولا يضمحل، محفوظ في السماوات لأجلكم، أنتم الذين بقوة الله محروسون، بإيمان، لخلاص مستعد أن يعلن في الزمان الأخير."}, {"title": "التسبحة الثانية لموسي النبي", "ref": "( تث 32 : 1 – 43 )", "text": "«انصتي أيتها السماوات فأتكلم، ولتسمع الأرض أقوال فمي. يهطل كالمطر تعليمي، ويقطر كالندى كلامي. كالطل على الكلاء، وكالوابل على العشب. إني باسم الرب أنادي. أعطوا عظمة لإلهنا. هو الصخر الكامل صنيعه. إن جميع سبله عدل. إله أمانة لا جور فيه. صديق وعادل هو. «أفسد له الذين ليسوا أولاده عيبهم، جيل أعوج ملتو. ألرب تكافئون بهذا يا شعبا غبيا غير حكيم؟ أليس هو أباك ومقتنيك، هو عملك وأنشأك؟ اذكر أيام القدم، وتأملوا سني دور فدور. اسأل أباك فيخبرك، وشيوخك فيقولوا لك. «حين قسم العلي للأمم، حين فرق بني آدم، نصب تخوما لشعوب حسب عدد بني إسرائيل. إن قسم الرب هو شعبه. يعقوب حبل نصيبه. وجده في أرض قفر، وفي خلاء مستوحش خرب. أحاط به ولاحظه وصانه كحدقة عينه. كما يحرك النسر عشه وعلى فراخه يرف، ويبسط جناحيه ويأخذها ويحملها على مناكبه، هكذا الرب وحده اقتاده وليس معه إله أجنبي. أركبه على مرتفعات الأرض فأكل ثمار الصحراء، وأرضعه عسلا من حجر، وزيتا من صوان الصخر، وزبدة بقر ولبن غنم، مع شحم خراف وكباش أولاد باشان، وتيوس مع دسم لب الحنطة، ودم العنب شربته خمرا. «فسمن يشورون ورفس. سمنت وغلظت واكتسيت شحما! فرفض الإله الذي عمله، وغبي عن صخرة خلاصه. أغاروه بالأجانب، وأغاظوه بالأرجاس. ذبحوا لأوثان ليست الله. لآلهة لم يعرفوها، أحداث قد جاءت من قريب لم يرهبها آباؤكم. الصخر الذي ولدك تركته، ونسيت الله الذي أبدأك. «فرأى الرب ورذل من الغيظ بنيه وبناته. وقال: أحجب وجهي عنهم، وأنظر ماذا تكون آخرتهم. إنهم جيل متقلب، أولاد لا أمانة فيهم. هم أغاروني بما ليس إلها، أغاظوني بأباطيلهم. فأنا أغيرهم بما ليس شعبا، بأمة غبية أغيظهم. إنه قد اشتعلت نار بغضبي فتتقد إلى الهاوية السفلى، وتأكل الأرض وغلتها، وتحرق أسس الجبال. أجمع عليهم شرورا، وأنفد سهامي فيهم، إذ هم خاوون من جوع، ومنهوكون من حمى وداء سام، أرسل فيهم أنياب الوحوش مع حمة زواحف الأرض. من خارج السيف يثكل، ومن داخل الخدور الرعبة. الفتى مع الفتاة والرضيع مع الأشيب. قلت: أبددهم إلى الزوايا، وأبطل من الناس ذكرهم. لو لم أخف من إغاظة العدو، من أن ينكر أضدادهم، من أن يقولوا: يدنا ارتفعت وليس الرب فعل كل هذه. «إنهم أمة عديمة الرأي ولا بصيرة فيهم. لو عقلوا لفطنوا بهذه وتأملوا آخرتهم. كيف يطرد واحد ألفا، ويهزم اثنان ربوة، لولا أن صخرهم باعهم والرب سلمهم؟ لأنه ليس كصخرنا صخرهم، ولو كان أعداؤنا القضاة.لأن من جفنة سدوم جفنتهم، ومن كروم عمورة. عنبهم عنب سم، ولهم عناقيد مرارة. خمرهم حمة الثعابين وسم الأصلال القاتل. «أليس ذلك مكنوزا عندي، مختوما عليه في خزائني؟ لي النقمة والجزاء. في وقت تزل أقدامهم. إن يوم هلاكهم قريب والمهيآت لهم مسرعة. لأن الرب يدين شعبه، وعلى عبيده يشفق. حين يرى أن اليد قد مضت، ولم يبق محجوز ولا مطلق، يقول: أين آلهتهم، الصخرة التي التجأوا إليها ،التي كانت تأكل شحم ذبائحهم وتشرب خمر سكائبهم؟ لتقم وتساعدكم وتكن عليكم حماية! انظروا الآن! أنا أنا هو وليس إله معي. أنا أميت وأحيي. سحقت، وإني أشفي، وليس من يدي مخلص. إني أرفع إلى السماء يدي وأقول: حي أنا إلى الأبد. إذا سننت سيفي البارق، وأمسكت بالقضاء يدي، أرد نقمة على أضدادي، وأجازي مبغضي. أسكر سهامي بدم، ويأكل سيفي لحما. بدم القتلى والسبايا، ومن رؤوس قواد العدو.  «تهللوا أيها الأمم، شعبه، لأنه ينتقم بدم عبيده، ويرد نقمة على أضداده، ويصفح عن أرضه عن شعبه»."}, {"title": "صلاة حنة أم صموئيل النبي", "ref": "( 1 صم 2 : 1 – 10 )", "text": "فصلت حنة وقالت: «فرح قلبي بالرب. ارتفع قرني بالرب. اتسع فمي على أعدائي، لأني قد ابتهجت بخلاصك.  ليس قدوس مثل الرب، لأنه ليس غيرك، وليس صخرة مثل إلهنا.  لا تكثروا الكلام العالي المستعلي، ولتبرح وقاحة من أفواهكم. لأن الرب إله عليم، وبه توزن الأعمال.  قسي الجبابرة انحطمت، والضعفاء تمنطقوا بالبأس.  الشباعى آجروا أنفسهم بالخبز، والجياع كفوا. حتى أن العاقر ولدت سبعة، وكثيرة البنين ذبلت.  الرب يميت ويحيي. يهبط إلى الهاوية ويصعد.  الرب يفقر ويغني. يضع ويرفع.  يقيم المسكين من التراب. يرفع الفقير من المزبلة للجلوس مع الشرفاء ويملكهم كرسي المجد. لأن للرب أعمدة الأرض، وقد وضع عليها المسكونة.  أرجل أتقيائه يحرس، والأشرار في الظلام يصمتون. لأنه ليس بالقوة يغلب إنسان.  مخاصمو الرب ينكسرون. من السماء يرعد عليهم. الرب يدين أقاصي الأرض، ويعطي عزا لملكه، ويرفع قرن مسيحه»."}, {"title": "صلاة حبقوق النبي", "ref": "( حب 3 : 2 – 19 )", "text": "يا رب، قد سمعت خبرك فجزعت. يا رب، عملك في وسط السنين أحيه. في وسط السنين عرف. في الغضب اذكر الرحمة. الله جاء من تيمان، والقدوس من جبل فاران. جلاله غطى السماوات، والأرض امتلأت من تسبيحه. وكان لمعان كالنور. له من يده شعاع، وهناك استتار قدرته. قدامه ذهب الوبأ، وعند رجليه خرجت الحمى. وقف وقاس الأرض. نظر فرجف الأمم ودكت الجبال الدهرية وخسفت آكام القدم. مسالك الأزل له. رأيت خيام كوشان تحت بلية. رجفت شقق أرض مديان. هل على الأنهار حمي يا رب؟ هل على الأنهار غضبك؟ أو على البحر سخطك حتى إنك ركبت خيلك، مركباتك مركبات الخلاص؟ عريت قوسك تعرية. سباعيات سهام كلمتك. سلاه. شققت الأرض أنهارا. أبصرتك ففزعت الجبال. سيل المياه طما. أعطت اللجة صوتها. رفعت يديها إلى العلاء. الشمس والقمر وقفا في بروجهما لنور سهامك الطائرة، للمعان برق مجدك. بغضب خطرت في الأرض، بسخط دست الأمم. خرجت لخلاص شعبك، لخلاص مسيحك. سحقت رأس بيت الشرير معريا الأساس حتى العنق. ثقبت بسهامه رأس قبائله. عصفوا لتشتيتي. ابتهاجهم كما لأكل المسكين في الخفية. سلكت البحر بخيلك، كوم المياه الكثيرة. سمعت فارتعدت أحشائي. من الصوت رجفت شفتاي. دخل النخر في عظامي، وارتعدت في مكاني لأستريح في يوم الضيق، عند صعود الشعب الذي يزحمنا. فمع أنه لا يزهر التين، ولا يكون حمل في الكروم. يكذب عمل الزيتونة، والحقول لا تصنع طعاما. ينقطع الغنم من الحظيرة، ولا بقر في المذاود، فإني أبتهج بالرب وأفرح بإله خلاصي.  الرب السيد قوتي، ويجعل قدمي كالأيائل، ويمشيني على مرتفعاتي."}, {"title": "صلاة يونان النبي", "ref": "( 2: 1 – 9 )", "text": "فصلى يونان إلى الرب إلهه من جوف الحوت، وقال: «دعوت من ضيقي الرب، فاستجابني. صرخت من جوف الهاوية، فسمعت صوتي. لأنك طرحتني في العمق في قلب البحار، فأحاط بي نهر. جازت فوقي جميع تياراتك ولججك. فقلت: قد طردت من أمام عينيك. ولكنني أعود أنظر إلى هيكل قدسك. قد اكتنفتني مياه إلى النفس. أحاط بي غمر. التف عشب البحر برأسي. نزلت إلى أسافل الجبال. مغاليق الأرض علي إلى الأبد. ثم أصعدت من الوهدة حياتي أيها الرب إلهي. حين أعيت في نفسي ذكرت الرب، فجاءت إليك صلاتي إلى هيكل قدسك. الذين يراعون أباطيل كاذبة يتركون نعمتهم. أما أنا فبصوت الحمد أذبح لك، وأوفي بما نذرته. للرب الخلاص»."}, {"title": "صلاة حزقيا ملك يهوذا حين مرض وقام من مرضه", "ref": "( أش 38 : 10 – 20 )", "text": "أنا قلت: «في عز أيامي أذهب إلى أبواب الهاوية. قد أعدمت بقية سني. قلت: لا أرى الرب. الرب في أرض الأحياء. لا أنظر إنسانا بعد مع سكان الفانية. مسكني قد انقلع وانتقل عني كخيمة الراعي. لففت كالحائك حياتي. من النول يقطعني. النهار والليل تفنيني. صرخت إلى الصباح. كالأسد هكذا يهشم جميع عظامي. النهار والليل تفنيني. كسنونة مزقزقة هكذا أصيح. أهدر كحمامة. قد ضعفت عيناي ناظرة إلى العلاء. يا رب، قد تضايقت. كن لي ضامنا. بماذا أتكلم، فإنه قال لي وهو قد فعل. أتمشى متمهلا كل سني من أجل مرارة نفسي. أيها السيد، بهذه يحيون، وبها كل حياة روحي فتشفيني وتحييني. هوذا للسلامة قد تحولت لي المرارة، وأنت تعلقت بنفسي من وهدة الهلاك، فإنك طرحت وراء ظهرك كل خطاياي. لأن الهاوية لا تحمدك. الموت لا يسبحك. لا يرجو الهابطون إلى الجب أمانتك. الحي الحي هو يحمدك كما أنا اليوم. الأب يعرف البنين حقك. الرب لخلاصي. فنعزف بأوتارنا كل أيام حياتنا في بيت الرب»."}, {"title": "صلاة منسي الملك بن حزقيا ملك يهوذا", "ref": "(مزمور 152 - أخبار الأيام الثاني)", "text": "يا رب ضابط الكل الذي في السماء إله آبائنا إبراهيم واسحق ويعقوب وزرعهم الصديق الذي خلق السماء والأرض وكل زينتهما. الذي ربط البحر بكلمة أمره وختم فمه باسمه المخوف والمملوء مجداً. الذي يفزع ويرتعد كل شيء من قدام وجه قوته. لأنها لا تحد عظمة عز مجدك ولا يدرك غضب رجزك على الخطاة وغير محصاة ولا مدركة رحمة إرادتك، أنت الرب العلي الرحوم طويل الروح وكثير الرحمة وبار ومتأسف على شر البشر. أنت أيضاً يا رب على قدر صلاحك رسمت توبة لمن أخطأ إليك وبكثرة رحمتك بشرت بتوبة للخطأة لخلاصهم أنت يا رب إله الأبرار لم تجعل التوبة للصديقين إبراهيم واسحق ويعقوب هؤلاء الذين لم يخطئوا إليك بل جعلت التوبة لمثلي أنا الخاطئ لأني أخطأت أكثر من عدد رمل البحر، كثرت آثامي ولست مستحقاً أن أرفع عيني إلى السماء من قبل كثرة ظلمي ولست مستحقاً أن انحنى من أجل كثرة رباطات الحديد ولا أرفع رأسي من خطاياي والآن بالحقيقة قد أغضبتك ولا راحة لي لأني أسخطت رجزك، والشر صنعت بين يديك، وأقمت رجاساتي وأكثرت نجاساتي والآن أحنى ركبتي قلبي واطلب من صلاحك أخطأت يا رب أخطأت وآثامي أنا عارفها ، ولكن أسأل وأطلب إليك يا رب اغفر لي ولا تهلكني بآثامي ، ولا تحقد على إلى الدهر، ولا تحفظ شروري ولا تلقني في الدينونة في قرار أسفل الأرض، لأنك أنت هو إله التائبين ، وفي أظهر صلاحك لني غير مستحق . وخلصني بكثرة رحمتك. فأسبحك كل حين كل أيام حياتي لأنك أنت هو الذي تسبح لك كل قوات السموات ولك المجد إلى البد آمين.\n\nتسبحة أشعياء النبي الأولي"}, {"title": "تسبحة أشعياء النبي الأولي", "ref": "( أش 26 : 9 – 20 )", "text": "بنفسي اشتهيتك في الليل. أيضا بروحي في داخلي إليك أبتكر. لأنه حينما تكون أحكامك في الأرض يتعلم سكان المسكونة العدل. يرحم المنافق ولا يتعلم العدل. في أرض الاستقامة يصنع شرا ولا يرى جلال الرب. يا رب، ارتفعت يدك ولا يرون. يرون ويخزون من الغيرة على الشعب وتأكلهم نار أعدائك. يا رب، تجعل لنا سلاما لأنك كل أعمالنا صنعتها لنا. أيها الرب إلهنا، قد استولى علينا سادة سواك. بك وحدك نذكر اسمك. هم أموات لا يحيون. أخيلة لا تقوم. لذلك عاقبت وأهلكتهم وأبدت كل ذكرهم. زدت الأمة يا رب، زدت الأمة. تمجدت. وسعت كل أطراف الأرض. يا رب في الضيق طلبوك. سكبوا مخافتة عند تأديبك إياهم. كما أن الحبلى التي تقارب الولادة تتلوى وتصرخ في مخاضها، هكذا كنا قدامك يا رب. حبلنا تلوينا كأننا ولدنا ريحا. لم نصنع خلاصا في الأرض، ولم يسقط سكان المسكونة. تحيا أمواتك، تقوم الجثث. استيقظوا، ترنموا يا سكان التراب. لأن طلك طل أعشاب، والأرض تسقط الأخيلة. هلم يا شعبي ادخل مخادعك، وأغلق أبوابك خلفك. اختبئ نحو لحيظة حتى يعبر الغضب.\n\nتسبحة  أشعياء النبي الثانية"}, {"title": "تسبحة  أشعياء النبي الثانية", "ref": "( أش 25 : 1 – 12 )", "text": "يا رب، أنت إلهي أعظمك. أحمد اسمك لأنك صنعت عجبا. مقاصدك منذ القديم أمانة وصدق. لأنك جعلت مدينة رجمة. قرية حصينة ردما. قصر أعاجم أن لا تكون مدينة. لا يبنى إلى الأبد. لذلك يكرمك شعب قوي، وتخاف منك قرية أمم عتاة. لأنك كنت حصنا للمسكين، حصنا للبائس في ضيقه، ملجأ من السيل، ظلا من الحر، إذ كانت نفخة العتاة كسيل على حائط. كحر في يبس تخفض ضجيج الأعاجم. كحر بظل غيم يذل غناء العتاة. ويصنع رب الجنود لجميع الشعوب في هذا الجبل وليمة سمائن، وليمة خمر على دردي، سمائن ممخة، دردي مصفى. ويفني في هذا الجبل وجه النقاب. النقاب الذي على كل الشعوب، والغطاء المغطى به على كل الأمم. يبلع الموت إلى الأبد، ويمسح السيد الرب الدموع عن كل الوجوه، وينزع عار شعبه عن كل الأرض، لأن الرب قد تكلم. ويقال في ذلك اليوم: «هوذا هذا إلهنا. انتظرناه فخلصنا. هذا هو الرب انتظرناه. نبتهج ونفرح بخلاصه». لأن يد الرب تستقر على هذا الجبل، ويداس موآب في مكانه كما يداس التبن في ماء المزبلة. فيبسط يديه فيه كما يبسط السابح ليسبح، فيضع كبرياءه مع مكايد يديه. وصرح ارتفاع أسوارك يخفضه، يضعه، يلصقه بالأرض إلى التراب.\n\nتسبحة  أشعياء النبي الثالثة"}, {"title": "تسبحة  أشعياء النبي الثالثة", "ref": "( أش 26 : 1 – 9 )", "text": "في ذلك اليوم يغنى بهذه الأغنية في أرض يهوذا: لنا مدينة قوية. يجعل الخلاص أسوارا ومترسة. افتحوا الأبواب لتدخل الأمة البارة الحافظة الأمانة. ذو الرأي الممكن تحفظه سالما سالما، لأنه عليك متوكل. توكلوا على الرب إلى الأبد، لأن في ياه الرب صخر الدهور. لأنه يخفض سكان العلاء، يضع القرية المرتفعة. يضعها إلى الأرض. يلصقها بالتراب. تدوسها الرجل، رجلا البائس، أقدام المساكين. طريق الصديق استقامة. تمهد أيها المستقيم سبيل الصديق. ففي طريق أحكامك يا رب انتظرناك. إلى اسمك وإلى ذكرك شهوة النفس. بنفسي اشتهيتك في الليل. أيضا بروحي في داخلي إليك أبتكر. لأنه حينما تكون أحكامك في الأرض يتعلم سكان المسكونة العدل.\n\nتسبحة  باروخ النبي"}, {"title": "تسبحة  باروخ النبي", "ref": "(  باروخ 2: 11 – 16 )", "text": "فالآن أيها الرب إله إسرائيل الذي أخرج شعبه من أرض مصر بيد قديرة وبآيات ومعجزات وقوة عظيمة وذراع مبسوطة وأقام له اسما كما في هذا اليوم. إنا خطئنا ونافقنا وأثمنا أيها الرب إلهنا في جميع رسومك لينصرف غضبك عنا فقد بقينا نفرا قليلا في الأمم الذين شتتنا بينهم. اسمع يا رب صلاتنا وتضرعنا وأنقذنا لأجلك وأنلنا حظوة أمام وجوه الذين أجلونا لكي تعرف الأرض بأسرها أنك أنت الرب إلهنا وأنه باسمك دعي إسرائيل وعشائره. أيها الرب التفت من بيت قدسك وانظر إلينا وأمل أيها الرب أذنك واستجب.\n\nتسبحة  ايليا النبي"}, {"title": "تسبحة  ايليا النبي", "ref": "(  1 مل 18: 36 – 39 )", "text": "وكان عند إصعاد التقدمة أن إيليا النبي تقدم وقال: «أيها الرب إله إبراهيم وإسحاق وإسرائيل، ليعلم اليوم أنك أنت الله في إسرائيل، وأني أنا عبدك، وبأمرك قد فعلت كل هذه الأمور. استجبني يا رب استجبني، ليعلم هذا الشعب أنك أنت الرب الإله، وأنك أنت حولت قلوبهم رجوعا». فسقطت نار الرب وأكلت المحرقة والحطب والحجارة والتراب، ولحست المياه التي في القناة. فلما رأى جميع الشعب ذلك سقطوا على وجوههم وقالوا: «الرب هو الله! الرب هو الله!»"}, {"title": "صلاة داود النبي", "ref": "( 1 أخ 29 : 10 – 13 )", "text": "وبارك داود الرب أمام كل الجماعة، وقال داود: «مبارك أنت أيها الرب إله إسرائيل أبينا من الأزل وإلى الأبد. لك يا رب العظمة والجبروت والجلال والبهاء والمجد، لأن لك كل ما في السماء والأرض. لك يا رب الملك، وقد ارتفعت رأسا على الجميع. والغنى والكرامة من لدنك، وأنت تتسلط على الجميع، وبيدك القوة والجبروت، وبيدك تعظيم وتشديد الجميع. والآن، يا إلهنا نحمدك ونسبح اسمك الجليل."}, {"title": "صلاة الملك سليمان", "ref": "( 1 مل 8 : 22 – 30 )", "text": "ووقف سليمان أمام مذبح الرب تجاه كل جماعة إسرائيل، وبسط يديه إلى السماء وقال: «أيها الرب إله إسرائيل، ليس إله مثلك في السماء من فوق، ولا على الأرض من أسفل، حافظ العهد والرحمة لعبيدك السائرين أمامك بكل قلوبهم. الذي قد حفظت لعبدك داود أبي ما كلمته به، فتكلمت بفمك وأكملت بيدك كهذا اليوم. والآن أيها الرب إله إسرائيل احفظ لعبدك داود أبي ما كلمته به قائلا: لا يعدم لك أمامي رجل يجلس على كرسي إسرائيل، إن كان بنوك إنما يحفظون طرقهم حتى يسيروا أمامي كما سرت أنت أمامي. والآن يا إله إسرائيل فليتحقق كلامك الذي كلمت به عبدك داود أبي. لأنه هل يسكن الله حقا على الأرض؟ هوذا السماوات وسماء السماوات لا تسعك، فكم بالأقل هذا البيت الذي بنيت؟ فالتفت إلى صلاة عبدك وإلى تضرعه أيها الرب إلهي، واسمع الصراخ والصلاة التي يصليها عبدك أمامك اليوم. لتكون عيناك مفتوحتين على هذا البيت ليلا ونهارا، على الموضع الذي قلت: إن اسمي يكون فيه، لتسمع الصلاة التي يصليها عبدك في هذا الموضع. واسمع تضرع عبدك وشعبك إسرائيل الذين يصلون في هذا الموضع، واسمع أنت في موضع سكناك في السماء، وإذا سمعت فاغفر."}, {"title": "صلاة دانيال النبي", "ref": "( دا 9 : 4 – 19 )", "text": "وصليت إلى الرب إلهي واعترفت وقلت: «أيها الرب الإله العظيم المهوب، حافظ العهد والرحمة لمحبيه وحافظي وصاياه. أخطأنا وأثمنا وعملنا الشر، وتمردنا وحدنا عن وصاياك وعن أحكامك. وما سمعنا من عبيدك الأنبياء الذين باسمك كلموا ملوكنا ورؤساءنا وآباءنا وكل شعب الأرض. لك يا سيد البر، أما لنا فخزي الوجوه، كما هو اليوم لرجال يهوذا ولسكان أورشليم، ولكل إسرائيل القريبين والبعيدين في كل الأراضي التي طردتهم إليها، من أجل خيانتهم التي خانوك إياها. يا سيد، لنا خزي الوجوه، لملوكنا، لرؤسائنا ولآبائنا لأننا أخطأنا إليك. للرب إلهنا المراحم والمغفرة، لأننا تمردنا عليه. وما سمعنا صوت الرب إلهنا لنسلك في شرائعه التي جعلها أمامنا عن يد عبيده الأنبياء. وكل إسرائيل قد تعدى على شريعتك، وحادوا لئلا يسمعوا صوتك، فسكبت علينا اللعنة والحلف المكتوب في شريعة موسى عبد الله، لأننا أخطأنا إليه. وقد أقام كلماته التي تكلم بها علينا وعلى قضاتنا الذين قضوا لنا، ليجلب علينا شرا عظيما، ما لم يجر تحت السماوات كلها كما أجري على أورشليم. كما كتب في شريعة موسى، قد جاء علينا كل هذا الشر، ولم نتضرع إلى وجه الرب إلهنا لنرجع من آثامنا ونفطن بحقك. فسهر الرب على الشر وجلبه علينا، لأن الرب إلهنا بار في كل أعماله التي عملها إذ لم نسمع صوته. والآن أيها السيد إلهنا، الذي أخرجت شعبك من أرض مصر بيد قوية، وجعلت لنفسك اسما كما هو هذا اليوم، قد أخطأنا، عملنا شرا. يا سيد، حسب كل رحمتك اصرف سخطك وغضبك عن مدينتك أورشليم جبل قدسك، إذ لخطايانا ولآثام آبائنا صارت أورشليم وشعبك عارا عند جميع الذين حولنا. فاسمع الآن يا إلهنا صلاة عبدك وتضرعاته، وأضئ بوجهك على مقدسك الخرب من أجل السيد. أمل أذنك يا إلهي واسمع. افتح عينيك وانظر خربنا والمدينة التي دعي اسمك عليها، لأنه لا لأجل برنا نطرح تضرعاتنا أمام وجهك، بل لأجل مراحمك العظيمة. يا سيد اسمع. يا سيد اغفر. يا سيد أصغ واصنع. لا تؤخر من أجل نفسك يا إلهي، لأن اسمك دعي على مدينتك وعلى شعبك»."}, {"title": "صلاة عزريا", "ref": "( تتمة دانيال 3 : 25 – 51 )", "text": "ووقف عزاريا وصلي هكذا وفتح فاه في وسط النار وقال مبارك أنت أيها الرب إله آبائنا وحميد واسمك مملوء مجداً إلى الأبد. لأنك عادل في جميع ما صنعت بنا وأعمالك كلها صدق وطرقك كلها مستقيمة وجميع أحكامك أحكام حق وقد أجريت أحكام حق فيما جلبته علينا وعلى مدينة آبائنا المقدسة اورشليم لأنك بالحق والحكم جلبت جميع هذا علينا لأجل خطايانا. إذ قد أخطأنا وأثمنا لنبتعد عنك وأجرمنا في كل شيء. ولم نسمع لوصاياك ولم نحفظها ولم نعمل بما أوصيتنا  لكي يكون لنا خيراً فجميع ما جلبته علينا وجميع ما صنعت بنا أنما صنعته بحكم حق. فأسلمتنا إلى أيدي أعداء أئمة وكفرة مبغضين أشرار وملك ظالم أشر من كل من على الأرض . والآن ليس لنا أن نفتح أفواهنا فقد صار الخزي والعار لعبيدك الذين يعبودنك فلا تخذلنا إلى الانقضاء لجل اسمك ولا تنقض عهدك ولا تنزع عنا رحمتك من أجل إبراهيم حبيبك واسحق عبدك وإسرائيل قديسك. الذين قلت لهم أنك تكثر نسلهم كنجوم السماء وكالرمل الذي على شاطئ البحر لأننا يا سيدنا قد قللنا عدداً أكثر من كل الأمم وقد اتضعنا ونحن اليوم في كل الأرض لأجل خطايانا. وليس لنا في هذا الزمان رئيس ولا نبي ولا مدبر ولا محرقة ولا ذبيحة ولا تقدمة ولا بخور ولا موضع لنثمر فيه أمامك ولنجد رحمة نحوك يا رب ولكن بنفس منسحقة وروح متواضعة تقبلنا إليك. وكمحرقات الكباش والثيران وربوات الحملان السمان هكذا فلتكن ذبيحتنا أمامك اليوم وتكمل حلفك فإنه لا يخزَى المتوكلين عليك والآن نتبعك بكل قلوبنا ونتقيك ونبتغي وجهك فلا تخزنا بل اصنع معنا رحمة كدعتك وككثرة رحمتك. وانقذنا كحسب عجائبك وأعط المجد لإسمك يا رب وليخجل جميع الذين يطلبون الشر لعبيدك وليخزوا من كل قوتهم واقتدارهم وليتحطم عزهم وليعلموا انك أنت الرب الإله وحدك المكرم على كل المسكونة. ولم يفتر الذين يوقدون أتون النار خدام الملك وهم يوقدون الأتون بكبريت وزفت ومشاقة فارتفع اللهيب فوق الأتون تسعة وأربعون ذراعاً. وانتشر وأحرق الكلدانيين الذين وجدهم حول الأتون. وملاك الرب نزل مع عزاريا في أتون النار المتقدة ونفض لهيب النار عن الأتون وجعل وسط الأتون ريحاً ذات نداء بارد فلم تمسهم النار البتة ولم تؤلمهم ولم تزعجهم . حينئذ سبح الثلاثة من فم واحد ومجدوا وباركوا الله في وسط الأتون قائلين: مبارك أنت..\n\nتسبحة العذراء مريم"}, {"title": "تسبحة العذراء مريم", "ref": "( لو 1 : 46 : 55 )", "text": "فقالت مريم: «تعظم نفسي الرب، وتبتهج روحي بالله مخلصي، لأنه نظر إلى اتضاع أمته. فهوذا منذ الآن جميع الأجيال تطوبني، لأن القدير صنع بي عظائم، واسمه قدوس، ورحمته إلى جيل الأجيال للذين يتقونه. صنع قوة بذراعه. شتت المستكبرين بفكر قلوبهم. أنزل الأعزاء عن الكراسي ورفع المتضعين. أشبع الجياع خيرات وصرف الأغنياء فارغين. عضد إسرائيل فتاه ليذكر رحمة، كما كلم آباءنا. لإبراهيم ونسله إلى الأبد»."}, {"title": "صلاة زكريا الكاهن", "ref": "( لو 1 : 58 – 79 )", "text": "«مبارك الرب إله إسرائيل لأنه افتقد وصنع فداء لشعبه،  وأقام لنا قرن خلاص في بيت داود فتاه.  كما تكلم بفم أنبيائه القديسين الذين هم منذ الدهر،  خلاص من أعدائنا ومن أيدي جميع مبغضينا.  ليصنع رحمة مع آبائنا ويذكر عهده المقدس،  القسم الذي حلف لإبراهيم أبينا:  أن يعطينا إننا بلا خوف، منقذين من أيدي أعدائنا، نعبده  بقداسة وبر قدامه جميع أيام حياتنا.  وأنت أيها الصبي نبي العلي تدعى، لأنك تتقدم أمام وجه الرب لتعد طرقه.  لتعطي شعبه معرفة الخلاص بمغفرة خطاياهم،  بأحشاء رحمة إلهنا التي بها افتقدنا المشرق من العلاء.  ليضيء على الجالسين في الظلمة وظلال الموت، لكي يهدي أقدامنا في طريق السلام»."}, {"title": "صلاة سمعان الشيخ", "ref": "( لو 2 : 29 : 32 )", "text": "«الآن تطلق عبدك يا سيد حسب قولك بسلام، لأن عيني قد أبصرتا خلاصك، الذي أعددته قدام وجه جميع الشعوب. نور إعلان للأمم، ومجدا لشعبك إسرائيل»."}]};
